  1	// src/lib/plattform/backend/demo/speicher.js
  2	//
  3	// Datei-Datenbank des Demo-Backends: eine JSON-Datei unter .data/plattform.json
  4	// (steht in .gitignore). Schreiben nur unter einer Sperrdatei (funktioniert auch,
  5	// wenn Next.js das Modul mehrfach lädt) und atomar über Datei + Umbenennen.
  6	// Uploads liegen unter .data/uploads/ mit zufälligen Dateinamen.
  7	
  8	import { promises as fs, readFileSync, statSync } from "node:fs";
  9	import path from "node:path";
 10	import { AsyncLocalStorage } from "node:async_hooks";
 11	
 12	export const DATEN_ORDNER = path.join(process.cwd(), ".data");
 13	export const UPLOAD_ORDNER = path.join(DATEN_ORDNER, "uploads");
 14	const DATEI = path.join(DATEN_ORDNER, "plattform.json");
 15	const SPERRE = path.join(DATEN_ORDNER, "plattform.lock");
 16	const SCHEMA = 2; // 2: Benachrichtigungen, Postausgang, Aufgaben, Checklisten
 17	
 18	let cache = null; // { mtimeMs, size, db }
 19	
 20	const warte = (ms) => new Promise((r) => setTimeout(r, ms));
 21	
 22	// Sperrdatei: schützt gegen parallele Schreiber aus mehreren Prozessen.
 23	// Unter Last (viele parallele Tests) darf sie NIE einem lebenden Prozess
 24	// weggenommen werden – sonst gehen Schreibvorgänge verloren. Verwaist ist eine
 25	// Sperre nur, wenn der eingetragene Prozess nicht mehr existiert oder sie sehr
 26	// alt ist (Absturz mitten im Schreiben).
 27	function prozessLebt(pid) {
 28	  if (!pid) return false;
 29	  try {
 30	    process.kill(pid, 0);
 31	    return true;
 32	  } catch (e) {
 33	    return e.code === "EPERM";
 34	  }
 35	}
 36	
 37	async function sperren() {
 38	  await fs.mkdir(DATEN_ORDNER, { recursive: true });
 39	  const start = Date.now();
 40	  for (;;) {
 41	    try {
 42	      const h = await fs.open(SPERRE, "wx");
 43	      await h.writeFile(String(process.pid));
 44	      await h.close();
 45	      return;
 46	    } catch (e) {
 47	      if (e.code !== "EEXIST") throw e;
 48	      try {
 49	        const st = await fs.stat(SPERRE);
 50	        const pid = Number(readFileSync(SPERRE, "utf8")) || 0;
 51	        const alt = Date.now() - st.mtimeMs;
 52	        if ((!prozessLebt(pid) && alt > 2000) || alt > 120000) await fs.rm(SPERRE, { force: true });
 53	      } catch {
 54	        /* inzwischen weg */
 55	      }
 56	      if (Date.now() - start > 60000) throw new Error("Demo-Datenbank ist gesperrt");
 57	      await warte(15 + Math.random() * 35);
 58	    }
 59	  }
 60	}
 61	
 62	async function entsperren() {
 63	  await fs.rm(SPERRE, { force: true }).catch(() => {});
 64	}
 65	
 66	// Innerhalb eines Prozesses: Schreibvorgänge strikt nacheinander (Warteschlange),
 67	// statt dass viele gleichzeitige Anfragen um die Sperrdatei konkurrieren.
 68	// Auf globalThis, damit mehrfach geladene Modulinstanzen dieselbe Schlange teilen.
 69	const SCHLANGE = Symbol.for("oekoinvest.demo.schreibschlange");
 70	const IM_SCHREIBEN = (globalThis[Symbol.for("oekoinvest.demo.imSchreiben")] ||= new AsyncLocalStorage());
 71	function nacheinander(fn) {
 72	  // Verschachtelter Schreibzugriff würde auf sich selbst warten (Deadlock) –
 73	  // und außerdem die äußere Änderung überschreiben. Deshalb klarer Fehler.
 74	  // Nur solange die äußere Änderung läuft; danach gestartete Folgeaufgaben (die den
 75	  // Kontext erben) dürfen normal schreiben.
 76	  if (IM_SCHREIBEN.getStore()?.aktiv) throw new Error("Verschachtelter Schreibzugriff auf die Demo-Datenbank (aendern in aendern)");
 77	  const vorher = globalThis[SCHLANGE] || Promise.resolve();
 78	  const lauf = vorher.catch(() => {}).then(() => {
 79	    const zustand = { aktiv: true };
 80	    return IM_SCHREIBEN.run(zustand, async () => {
 81	      try {
 82	        return await fn();
 83	      } finally {
 84	        zustand.aktiv = false;
 85	      }
 86	    });
 87	  });
 88	  globalThis[SCHLANGE] = lauf.catch(() => {});
 89	  return lauf;
 90	}
 91	
 92	// Wiederhergestellt (Team Service): dateiLesen, dateiSchreiben und seedFn fehlten seit Commit 640c032
 93	// (ReferenceError bei jedem Zugriff) – unverändert aus dem Stand davor übernommen.
 94	
 95	// BEWUSST SYNCHRON: React 19 schneidet im Dev-Modus den Rückgabewert von
 96	// awaited I/O (fs.promises) für die Debug-Anzeige mit und liefert ihn im
 97	// HTML aus – das war die komplette Demo-Datenbank inkl. Passwort-Hashes auf
 98	// jeder Seite (2–5 MB). Synchrones Lesen erzeugt keinen solchen I/O-Eintrag.
 99	async function dateiLesen() {
100	  try {
101	    const st = statSync(DATEI);
102	    if (cache && cache.mtimeMs === st.mtimeMs && cache.size === st.size) return structuredClone(cache.db);
103	    const roh = readFileSync(DATEI, "utf8");
104	    const db = JSON.parse(roh);
105	    cache = { mtimeMs: st.mtimeMs, size: st.size, db };
106	    return structuredClone(db);
107	  } catch (e) {
108	    if (e.code === "ENOENT") return null;
109	    throw e;
110	  }
111	}
112	
113	async function dateiSchreiben(db) {
114	  const tmp = `${DATEI}.${process.pid}.${Date.now()}.tmp`;
115	  await fs.writeFile(tmp, JSON.stringify(db, null, 1), "utf8");
116	  for (let i = 0; ; i++) {
117	    try {
118	      await fs.rename(tmp, DATEI);
119	      break;
120	    } catch (e) {
121	      // Windows: Ziel kurzzeitig von einem Leser geöffnet
122	      if (i > 20 || !["EPERM", "EBUSY", "EACCES"].includes(e.code)) {
123	        await fs.rm(tmp, { force: true }).catch(() => {});
124	        throw e;
125	      }
126	      await warte(15);
127	    }
128	  }
129	  cache = null;
130	}
131	
132	let seedFn = null;
133	/** Seed-Funktion registrieren (liefert eine neue, befüllte Datenbank) */
134	export function seedSetzen(fn) {
135	  seedFn = fn;
136	}
137	
138	async function sicherstellen() {
139	  const db = await dateiLesen();
140	  if (db && db.schema === SCHEMA) return db;
141	  await sperren();
142	  try {
143	    const erneut = await dateiLesen();
144	    if (erneut && erneut.schema === SCHEMA) return erneut;
145	    const neu = await seedFn();
146	    neu.schema = SCHEMA;
147	    await dateiSchreiben(neu);
148	    return structuredClone(neu);
149	  } finally {
150	    await entsperren();
151	  }
152	}
153	
154	/** Nur lesen (Kopie – Änderungen daran werden NICHT gespeichert) */
155	export async function lesen() {
156	  return sicherstellen();
157	}
158	
159	/** Lesen, ändern, speichern unter Sperre. `fn(db)` darf db verändern und ein Ergebnis liefern. */
160	export async function aendern(fn) {
161	  await sicherstellen();
162	  return nacheinander(async () => {
163	    await sperren();
164	    try {
165	      const db = await dateiLesen();
166	      const ergebnis = await fn(db);
167	      await dateiSchreiben(db);
168	      return ergebnis;
169	    } finally {
170	      await entsperren();
171	    }
172	  });
173	}
174	
175	export async function uploadSchreiben(dateiname, daten) {
176	  await fs.mkdir(UPLOAD_ORDNER, { recursive: true });
177	  await fs.writeFile(path.join(UPLOAD_ORDNER, path.basename(dateiname)), daten);
178	}
179	
180	export async function uploadLesen(dateiname) {
181	  return fs.readFile(path.join(UPLOAD_ORDNER, path.basename(dateiname)));
182	}
183	
184	export async function uploadLoeschen(dateiname) {
185	  await fs.rm(path.join(UPLOAD_ORDNER, path.basename(dateiname)), { force: true });
186	}

  1	// src/lib/plattform/planung/geo.js
  2	//
  3	// Georeferenzierte Pläne für die Vorschau: GeoJSON und KML → Primitive im selben Format wie dxf.js (aufloesen), damit
  4	// Viewer, Messwerkzeug und Kennzahlen (Layer-Konvention über properties.layer bzw. Name) identisch funktionieren.
  5	// WGS84-Koordinaten werden lokal in Meter projiziert (gleichabständig um den Schwerpunkt – für Planmaßstäbe bis einige
  6	// Kilometer genau genug); als „projiziert“ gekennzeichnete Daten (Shapefile ohne Umrechnung) bleiben in ihren Einheiten.
  7	
  8	import { punkteFlaeche, punkteLaenge } from "./dxf.js";
  9	
 10	const M_PRO_GRAD_LAT = 110574;
 11	const M_PRO_GRAD_LON = 111320;
 12	
 13	/** KML-Text → GeoJSON-FeatureCollection (Point, LineString, Polygon äußere Ringe; Name aus Placemark) */
 14	export function kmlZuGeojson(kml) {
 15	  const features = [];
 16	  const s = String(kml);
 17	  const placemarks = s.match(/<Placemark[\s\S]*?<\/Placemark>/gi) || [];
 18	  const koords = (t) =>
 19	    t.trim().split(/\s+/).map((p) => p.split(",").map(Number)).filter((p) => p.length >= 2 && p.every((x) => Number.isFinite(x))).map((p) => [p[0], p[1]]);
 20	  for (const pm of placemarks) {
 21	    const name = (pm.match(/<name>([\s\S]*?)<\/name>/i)?.[1] || "").replace(/<!\[CDATA\[|\]\]>/g, "").trim();
 22	    for (const m of pm.matchAll(/<(Point|LineString|Polygon)[\s>][\s\S]*?<\/\1>/gi)) {
 23	      const typ = m[1].toLowerCase();
 24	      if (typ === "polygon") {
 25	        const ring = m[0].match(/<outerBoundaryIs>[\s\S]*?<coordinates>([\s\S]*?)<\/coordinates>/i)?.[1];
 26	        if (ring) features.push({ type: "Feature", properties: { name }, geometry: { type: "Polygon", coordinates: [koords(ring)] } });
 27	      } else {
 28	        const c = m[0].match(/<coordinates>([\s\S]*?)<\/coordinates>/i)?.[1];
 29	        if (!c) continue;
 30	        const k = koords(c);
 31	        features.push({ type: "Feature", properties: { name }, geometry: typ === "point" ? { type: "Point", coordinates: k[0] } : { type: "LineString", coordinates: k } });
 32	      }
 33	    }
 34	  }
 35	  return { type: "FeatureCollection", features };
 36	}
 37	
 38	function features(gj) {
 39	  if (!gj) return [];
 40	  if (gj.type === "FeatureCollection") return gj.features || [];
 41	  if (gj.type === "Feature") return [gj];
 42	  return [{ type: "Feature", properties: {}, geometry: gj }];
 43	}
 44	
 45	function geometrien(g, out = []) {
 46	  if (!g) return out;
 47	  if (g.type === "GeometryCollection") for (const x of g.geometries || []) geometrien(x, out);
 48	  else out.push(g);
 49	  return out;
 50	}
 51	
 52	/**
 53	 * GeoJSON → { prims, einheit, projiziert, ursprung } – Layer aus properties.layer, sonst name, sonst Geometrietyp.
 54	 * `projiziert: true` (Shapefile) → Koordinaten unverändert in Metern.
 55	 */
 56	export function geojsonPrimitive(gj, { projiziert = !!gj?.oekoinvestProjiziert } = {}) {
 57	  const liste = features(gj);
 58	  // Bezugspunkt: Mittel aller Koordinaten
 59	  let sx = 0;
 60	  let sy = 0;
 61	  let n = 0;
 62	  const alle = (c, f) => (typeof c[0] === "number" ? f(c) : c.forEach((x) => alle(x, f)));
 63	  for (const ft of liste) for (const g of geometrien(ft.geometry)) alle(g.coordinates || [], (p) => ((sx += p[0]), (sy += p[1]), n++));
 64	  const lon0 = n ? sx / n : 0;
 65	  const lat0 = n ? sy / n : 0;
 66	  const kx = projiziert ? 1 : M_PRO_GRAD_LON * Math.cos((lat0 * Math.PI) / 180);
 67	  const ky = projiziert ? 1 : M_PRO_GRAD_LAT;
 68	  const proj = (p) => (projiziert ? [p[0], p[1]] : [(p[0] - lon0) * kx, (p[1] - lat0) * ky]);
 69	  const prims = [];
 70	  let g = 0;
 71	  for (const ft of liste) {
 72	    const pr = ft.properties || {};
 73	    const L = String(pr.layer || pr.Layer || pr.LAYER || pr.name || pr.Name || ft.geometry?.type || "Geometrie").slice(0, 80);
 74	    for (const geo of geometrien(ft.geometry)) {
 75	      const basis = { L, aci: null, rgb: null, g, i: String(g), q: geo.type };
 76	      const linie = (koord, zu) => {
 77	        const pts = [];
 78	        for (const p of koord) pts.push(...proj(p));
 79	        if (zu && pts.length >= 4 && (pts[0] !== pts[pts.length - 2] || pts[1] !== pts[pts.length - 1])) pts.push(pts[0], pts[1]);
 80	        prims.push({ t: "p", ...basis, pts, zu, laenge: punkteLaenge(pts), flaeche: zu ? punkteFlaeche(pts.slice(0, -2)) : 0 });
 81	      };
 82	      switch (geo.type) {
 83	        case "Point": {
 84	          const [x, y] = proj(geo.coordinates);
 85	          prims.push({ t: "p", ...basis, pts: [x, y, x, y], zu: false, laenge: 0, flaeche: 0, punkt: true });
 86	          if (pr.name) prims.push({ t: "t", ...basis, x, y, h: 0, text: String(pr.name).slice(0, 80), rot: 0, ha: 0, va: 1, pixel: 11 });
 87	          break;
 88	        }
 89	        case "MultiPoint":
 90	          for (const c of geo.coordinates) {
 91	            const [x, y] = proj(c);
 92	            prims.push({ t: "p", ...basis, pts: [x, y, x, y], zu: false, laenge: 0, flaeche: 0, punkt: true });
 93	          }
 94	          break;
 95	        case "LineString":
 96	          linie(geo.coordinates, false);
 97	          break;
 98	        case "MultiLineString":
 99	          for (const c of geo.coordinates) linie(c, false);
100	          break;
101	        case "Polygon":
102	          (geo.coordinates || []).forEach((ring) => linie(ring, true)); // Löcher als eigene Kontur (Fläche dann getrennt)
103	          break;
104	        case "MultiPolygon":
105	          for (const poly of geo.coordinates) for (const ring of poly) linie(ring, true);
106	          break;
107	        default:
108	          break;
109	      }
110	    }
111	    g++;
112	  }
113	  return { prims, einheit: { code: 6, kurz: "m", label: projiziert ? "Meter (Koordinatensystem der Datei)" : "Meter (aus WGS84 lokal projiziert)", m: 1, angenommen: false }, projiziert, ursprung: projiziert ? null : [lon0, lat0] };
114	}
115	// src/lib/plattform/planung/analyse.js
116	//
117	// NUR SERVERSEITIG: Analyse einer hochgeladenen Planversion (Demo-Backend und Frappe-Adapter gleich): DXF → Einheit,
118	// Objektzähler, Ausdehnung, Layer, Kennzahlen nach Layer-Konvention; GeoJSON/KML → dieselben Kennzahlen; KMZ und
119	// Shapefile-ZIP → zusätzlich abgeleitete Vorschau-Datei (GeoJSON), weil der Browser nicht entpackt.
120	// Fehler in der Analyse verhindern den Upload nicht (Datei bleibt Nachweis), sie landen in `analyse.fehler`.
121	
122	import { analysieren, bbox, dxfDekodieren, kennzahlen } from "./dxf.js";
123	import { geojsonPrimitive, kmlZuGeojson } from "./geo.js";
124	import { kmzZuGeojson, shapeZuGeojson } from "./zip.js";
125	
126	function geoAnalyse(gj) {
127	  const { prims, einheit, projiziert, ursprung } = geojsonPrimitive(gj);
128	  const bb = bbox(prims);
129	  const layer = {};
130	  for (const p of prims) layer[p.L] = (layer[p.L] || 0) + 1;
131	  return {
132	    einheit, projiziert, ursprung, primitive: prims.length, entitaeten: (gj.features || []).length || 1, bbox: bb,
133	    groesse: bb ? { breiteM: bb[2] - bb[0], hoeheM: bb[3] - bb[1] } : null,
134	    layer: Object.entries(layer).map(([name, objekte]) => ({ name, objekte })),
135	    kennzahlen: kennzahlen(prims, einheit),
136	  };
137	}
138	
139	/** → { analyse, abgeleitet: { name, mime, daten, art } | null } */
140	export function analyseDatei(format, daten, info = {}) {
141	  try {
142	    switch (format) {
143	      case "dxf": {
144	        const a = analysieren(dxfDekodieren(daten));
145	        return { analyse: { ...a, layer: a.layer.slice(0, 500) }, abgeleitet: null };
146	      }
147	      case "geojson":
148	        return { analyse: geoAnalyse(JSON.parse(Buffer.from(daten).toString("utf8"))), abgeleitet: null };
149	      case "kml":
150	        return { analyse: geoAnalyse(kmlZuGeojson(Buffer.from(daten).toString("utf8"))), abgeleitet: null };
151	      case "kmz":
152	      case "shape": {
153	        const gj = format === "kmz" ? kmzZuGeojson(daten) : shapeZuGeojson(daten);
154	        const text = JSON.stringify(gj);
155	        return { analyse: { ...geoAnalyse(gj), prj: info.prj ?? null }, abgeleitet: { name: "vorschau.geojson", mime: "application/geo+json", daten: Buffer.from(text), art: "geojson" } };
156	      }
157	      case "dwg":
158	        return { analyse: { dwgVersion: info.dwgVersion, dwgRelease: info.dwgRelease }, abgeleitet: null };
159	      default:
160	        return { analyse: {}, abgeleitet: null };
161	    }
162	  } catch (e) {
163	    return { analyse: { fehler: String(e?.message || "Datei konnte nicht ausgewertet werden.").slice(0, 200) }, abgeleitet: null };
164	  }
165	}
166	// src/lib/plattform/planung/ausgabe.js
167	//
168	// Aufbereitung der Kostenkalkulation für Portal, PDF und CSV – gemeinsam für Demo-Backend und Frappe-Adapter, damit beide
169	// Betriebsarten identische Ausgaben liefern. Eingabe sind die gespeicherten Rohdaten (Frappe: planung.kalkulation liefert
170	// genau diese Felder), Ausgabe das Objekt, das Kalkulation.js und kosten-pdf.js erwarten.
171	
172	import { GEWERKE, GRUPPEN, KOSTENSTAENDE, VERLEGEARTEN, berechnen, sollIst, standVergleich, trassenLaenge, vorschlag, zusammenfuehren } from "./kosten.js";
173	
174	/** Parameter der Kalkulation: Typ, Land, Leistung und Gutachten immer aus dem Projekt; Fläche/Grundstücke als Vorbelegung */
175	export function parameterFuer(projektParameter, gespeichert = null) {
176	  const s = gespeichert?.parameter || {};
177	  const pp = projektParameter;
178	  return {
179	    ...s, typ: pp.typ, land: pp.land, mwp: pp.mwp, mwh: pp.mwh, gutachten: pp.gutachten,
180	    flaecheHa: s.flaecheHa ?? pp.flaecheHa, flaechenAnzahl: s.flaechenAnzahl ?? pp.flaechenAnzahl,
181	    kostenstand: gespeichert?.kostenstand || s.kostenstand || "schaetzung",
182	  };
183	}
184	
185	/**
186	 * roh = { projekt: {id,titel,typ,land,mwp,mwh}, projektParameter, gespeichert: {id, kostenstand, parameter, positionen, geaendertAm, geaendertVon} | null,
187	 *         ist: {jeArt, quelle} | null, staende: [{id, stand, am, von, kommentar, summen, gruppen}], uebergabe, quellen: {akquise, dxf}, darfBearbeiten }
188	 */
189	export function kalkulationAusgabe(roh) {
190	  const k = roh.gespeichert || null;
191	  const parameter = parameterFuer(roh.projektParameter, k);
192	  const e = berechnen(zusammenfuehren(k?.positionen || [], vorschlag(parameter)), parameter);
193	  const staende = [...(roh.staende || [])].sort((a, b) => String(b.am).localeCompare(String(a.am)));
194	  return {
195	    projekt: roh.projekt,
196	    id: k?.id || null, gespeichert: !!k, kostenstand: parameter.kostenstand, kostenstandLabel: KOSTENSTAENDE[parameter.kostenstand]?.label || parameter.kostenstand,
197	    parameter: { ...e.parameter, trasseLaengeM: trassenLaenge(e.parameter), contingencyEigen: k?.parameter?.contingency !== null && k?.parameter?.contingency !== undefined },
198	    positionen: e.positionen, gruppen: e.gruppen, gewerke: e.gewerke, summen: e.summen, benchmark: e.benchmark,
199	    sollIst: sollIst(e, roh.ist), istQuelle: roh.ist ? roh.ist.quelle || "plattform" : "manuell",
200	    staende: staende.map((s, i) => ({ ...s, standLabel: KOSTENSTAENDE[s.stand]?.label || s.stand, vergleich: standVergleich(s, staende[i + 1]) })),
201	    uebergabe: roh.uebergabe || null,
202	    quellen: roh.quellen || { akquise: null, dxf: [] },
203	    auswahl: { gruppen: GRUPPEN, gewerke: Object.fromEntries(Object.entries(GEWERKE).map(([id, g]) => [id, { label: g.label, gruppe: g.gruppe, kg: g.kg }])), kostenstaende: KOSTENSTAENDE, verlegearten: VERLEGEARTEN },
204	    geaendertAm: k?.geaendertAm || null, geaendertVon: k?.geaendertVon || "",
205	    darfBearbeiten: !!roh.darfBearbeiten,
206	  };
207	}
208	// src/lib/plattform/planung/konverter.js
209	//
210	// NUR SERVERSEITIG: Aufruf des CAD-Konvertierungsdienstes (Backend-Import/dienste/cad-konverter) DWG → DXF.
211	//   CAD_KONVERTER_URL    z. B. http://cad-konverter:8080 (internes Netz, nie öffentlich)
212	//   CAD_KONVERTER_TOKEN  Bearer-Token (≥ 32 Zeichen, identisch mit KONVERTER_TOKEN im Dienst)
213	// Ohne Konfiguration: { ok:false, status:"nicht_verfuegbar" } – der Plan bleibt mit Hinweis „Vorschau nach Konvertierung“.
214	
215	import { dxfArt } from "./dxf.js";
216	
217	export const KONVERTER_TIMEOUT_MS = 120000;
218	
219	export function konverterKonfiguriert() {
220	  return !!(process.env.CAD_KONVERTER_URL && (process.env.CAD_KONVERTER_TOKEN || "").length >= 32);
221	}
222	
223	/** DWG-Bytes → { ok, daten (DXF-Buffer), dauerMs } | { ok:false, status: nicht_verfuegbar|fehler, fehler } */
224	export async function dwgNachDxf(daten) {
225	  if (!konverterKonfiguriert()) return { ok: false, status: "nicht_verfuegbar", fehler: "Kein Konvertierungsdienst konfiguriert (CAD_KONVERTER_URL/CAD_KONVERTER_TOKEN)." };
226	  const start = Date.now();
227	  try {
228	    const res = await fetch(`${process.env.CAD_KONVERTER_URL.replace(/\/$/, "")}/v1/konvertieren?ziel=dxf`, {
229	      method: "POST",
