 71	/** Nächster Änderungsindex: – → A → B … Z → AA … */
 72	export function naechsterIndex(vorhandene = []) {
 73	  const zahlVon = (s) => [...String(s || "").toUpperCase()].reduce((n, c) => n * 26 + (c.charCodeAt(0) - 64), 0);
 74	  const max = vorhandene.reduce((m, s) => (/^[A-Z]{1,3}$/i.test(String(s || "")) ? Math.max(m, zahlVon(s)) : m), 0);
 75	  let n = max + 1;
 76	  let s = "";
 77	  while (n > 0) {
 78	    const r = (n - 1) % 26;
 79	    s = String.fromCharCode(65 + r) + s;
 80	    n = Math.floor((n - 1) / 26);
 81	  }
 82	  return s;
 83	}
