 85	// ---------------------------------------------------------------- Erkennung
 86	
 87	const text = (b, von, bis) => {
 88	  let s = "";
 89	  for (let k = von; k < Math.min(bis, b.length); k++) s += String.fromCharCode(b[k]);
 90	  return s;
 91	};
