 93	/** Namen im zentralen Verzeichnis einer ZIP-Datei (ohne Entpacken). Leer, wenn keine gültige ZIP. */
 94	export function zipNamen(b) {
 95	  const n = b.length;
 96	  const dv = new DataView(b.buffer, b.byteOffset, b.byteLength);
 97	  for (let i = n - 22; i >= Math.max(0, n - 22 - 65535); i--) {
 98	    if (dv.getUint32(i, true) !== 0x06054b50) continue;
 99	    const anzahl = dv.getUint16(i + 10, true);
100	    let p = dv.getUint32(i + 16, true);
101	    const namen = [];
102	    for (let k = 0; k < anzahl && p + 46 <= n; k++) {
103	      if (dv.getUint32(p, true) !== 0x02014b50) break;
104	      const ln = dv.getUint16(p + 28, true);
105	      const lx = dv.getUint16(p + 30, true);
106	      const lk = dv.getUint16(p + 32, true);
107	      namen.push(new TextDecoder().decode(b.subarray(p + 46, p + 46 + ln)));
108	      p += 46 + ln + lx + lk;
109	    }
110	    return namen;
111	  }
112	  return [];
113	}
