115	/**
116	 * Format am Inhalt erkennen. Ergebnis { ok, format, info } oder { ok:false, status, fehler }.
117	 * `name` dient nur für Hinweise (Endung passt nicht) – maßgeblich sind die Bytes.
118	 */
119	export function formatErkennen(bytes, name = "") {
120	  const b = bytes instanceof Uint8Array ? bytes : new Uint8Array(bytes);
121	  if (!b.length) return { ok: false, status: 422, fehler: "Die Datei ist leer." };
122	  const kopf = text(b, 0, 8);
123	  let format = "";
124	  const info = {};
125	  if (kopf.startsWith("%PDF-")) format = "pdf";
126	  else if (/^AC10\d\d/.test(kopf)) {
127	    format = "dwg";
128	    info.dwgVersion = kopf.slice(0, 6);
129	    info.dwgRelease = DWG_VERSIONEN[info.dwgVersion] || "unbekannte Version";
130	  } else if (b[0] === 0x50 && b[1] === 0x4b && b[2] === 0x03 && b[3] === 0x04) {
131	    const namen = zipNamen(b).map((x) => x.toLowerCase());
132	    if (!namen.length) return { ok: false, status: 415, fehler: "Die ZIP-Datei ist beschädigt." };
133	    if (namen.some((x) => x.includes("..") || x.startsWith("/"))) return { ok: false, status: 415, fehler: "Die ZIP-Datei enthält unzulässige Pfade." };
134	    if (namen.some((x) => x.endsWith(".kml"))) format = "kmz";
135	    else if (["shp", "shx", "dbf"].every((e) => namen.some((x) => x.endsWith(`.${e}`)))) {
136	      format = "shape";
137	      info.prj = namen.some((x) => x.endsWith(".prj"));
138	    } else return { ok: false, status: 415, fehler: "ZIP-Dateien nur als Shapefile (.shp, .shx, .dbf, .prj) oder KMZ." };
139	    info.dateien = namen.length;
140	  } else {
141	    const anfang = text(b, 0, 400);
142	    const art = dxfArt(anfang);
143	    if (art === "binaer") return { ok: false, status: 415, fehler: "Binär-DXF wird nicht unterstützt – bitte als ASCII-DXF speichern (DXF R12–2018)." };
144	    if (art === "ascii") format = "dxf";
145	    else if (/^\s*(<\?xml[^>]*>\s*)?(<!--[\s\S]*?-->\s*)*<kml[\s>]/i.test(anfang)) format = "kml";
146	    else if (/^\s*\{/.test(anfang)) {
147	      try {
148	        const j = JSON.parse(new TextDecoder().decode(b));
149	        if (["FeatureCollection", "Feature", "Polygon", "MultiPolygon", "LineString", "MultiLineString", "Point", "MultiPoint", "GeometryCollection"].includes(j?.type)) format = "geojson";
150	      } catch {
151	        /* kein JSON */
152	      }
153	    }
154	  }
155	  if (!format) return { ok: false, status: 415, fehler: "Erlaubt sind DWG, DXF (ASCII), PDF, KML/KMZ, GeoJSON und Shapefile (ZIP)." };
156	  if (b.length > FORMATE[format].maxBytes) return { ok: false, status: 413, fehler: `${FORMATE[format].label}: höchstens ${Math.round(FORMATE[format].maxBytes / MB)} MB.` };
157	  const endung = String(name).toLowerCase().split(".").pop();
158	  if (name && endung && ![FORMATE[format].endung, format === "geojson" ? "json" : ""].includes(endung)) info.hinweis = `Dateiendung „.${endung}“ passt nicht zum Inhalt (${FORMATE[format].label}).`;
159	  return { ok: true, format, info };
160	}
