164	/**
165	 * Zugriff auf einen Plan: z = { backoffice, schreiben, nutzerId, gutachterMs: Set(Meilenstein-IDs), investor: Freigabe|null }.
166	 * Ergebnis { sehen, hochladen, planer, versionen: (v) => bool }.
167	 * Gutachter/Planer: Pläne an zugewiesenen Meilensteinen oder mit ihm als Planer; Co-Investor: nur freigegebene Versionen
168	 * (Freigabe mit Schalter „Dokumente“); Eigentümer und alle anderen: kein Zugriff.
169	 */
170	export function planZugriff(z, plan, versionen = []) {
171	  const planer = !!z.nutzerId && ((plan.meilensteinId && z.gutachterMs?.has(plan.meilensteinId)) || plan.planerId === z.nutzerId);
172	  const investor = !!z.investor && !!z.investor.dokumente;
173	  const sichtbar = (v) => z.backoffice || planer || (investor && v.status === "freigegeben");
174	  return {
175	    sehen: z.backoffice || planer || (investor && versionen.some((v) => v.status === "freigegeben")),
176	    hochladen: (z.backoffice && z.schreiben) || planer,
177	    planer,
178	    version: sichtbar,
179	  };
180	}
181	// src/lib/plattform/planung/zip.js
182	//
183	// NUR SERVERSEITIG (node:zlib): KMZ bzw. Shapefile-ZIP entpacken und in GeoJSON überführen, damit der Browser eine
184	// Vorschau zeigen kann (abgeleitete Datei „vorschau.geojson“ an der Planversion). Schutz gegen ZIP-Bomben: höchstens
185	// 50 MB entpackt je Datei und 200 Einträge; nur Deflate/Stored; keine Pfade mit „..“.
186	//   Shapefile: Punkt, Multipunkt, Linie, Polygon (auch Z/M-Varianten); Attribute (.dbf) werden nicht gelesen, der Layer
187	//   heißt wie die .shp-Datei. Mit .prj ohne PROJCS (reines GEOGCS) gelten Koordinaten als WGS84-Länge/Breite.
188	
189	import { inflateRawSync } from "node:zlib";
190	import { kmlZuGeojson } from "./geo.js";
191	
192	const MAX_ENTPACKT = 50 * 1024 * 1024;
193	
194	/** Einträge einer ZIP-Datei: [{ name, methode, groesse, gepackt, offset }] */
195	export function zipEintraege(buf) {
196	  const b = Buffer.isBuffer(buf) ? buf : Buffer.from(buf);
197	  for (let i = b.length - 22; i >= Math.max(0, b.length - 22 - 65535); i--) {
198	    if (b.readUInt32LE(i) !== 0x06054b50) continue;
199	    const anzahl = b.readUInt16LE(i + 10);
200	    if (anzahl > 200) throw new Error("Zu viele Dateien im ZIP-Archiv.");
201	    let p = b.readUInt32LE(i + 16);
202	    const liste = [];
203	    for (let k = 0; k < anzahl; k++) {
204	      if (b.readUInt32LE(p) !== 0x02014b50) break;
205	      const ln = b.readUInt16LE(p + 28);
206	      const lx = b.readUInt16LE(p + 30);
207	      const lk = b.readUInt16LE(p + 32);
208	      liste.push({ name: b.subarray(p + 46, p + 46 + ln).toString("utf8"), methode: b.readUInt16LE(p + 10), gepackt: b.readUInt32LE(p + 20), groesse: b.readUInt32LE(p + 24), offset: b.readUInt32LE(p + 42) });
209	      p += 46 + ln + lx + lk;
210	    }
211	    return liste;
212	  }
213	  return [];
214	}
215	
216	/** Einen Eintrag entpacken */
217	export function zipLesen(buf, eintrag) {
218	  const b = Buffer.isBuffer(buf) ? buf : Buffer.from(buf);
219	  if (eintrag.groesse > MAX_ENTPACKT) throw new Error("Datei im ZIP-Archiv ist zu groß.");
220	  const o = eintrag.offset;
221	  if (b.readUInt32LE(o) !== 0x04034b50) throw new Error("ZIP-Archiv beschädigt.");
222	  const start = o + 30 + b.readUInt16LE(o + 26) + b.readUInt16LE(o + 28);
223	  const roh = b.subarray(start, start + eintrag.gepackt);
224	  if (eintrag.methode === 0) return Buffer.from(roh);
225	  if (eintrag.methode === 8) return inflateRawSync(roh, { maxOutputLength: MAX_ENTPACKT });
226	  throw new Error("Nicht unterstützte ZIP-Kompression.");
227	}
228	
229	/** KMZ → GeoJSON (erste .kml-Datei, bevorzugt doc.kml) */
230	export function kmzZuGeojson(buf) {
231	  const liste = zipEintraege(buf);
232	  const kml = liste.find((e) => /(^|\/)doc\.kml$/i.test(e.name)) || liste.find((e) => /\.kml$/i.test(e.name));
233	  if (!kml) throw new Error("Keine KML-Datei im KMZ-Archiv.");
234	  return kmlZuGeojson(zipLesen(buf, kml).toString("utf8"));
235	}
236	
237	/** .shp-Inhalt → GeoJSON-Geometrien */
238	export function shpGeometrien(shp) {
239	  const b = Buffer.isBuffer(shp) ? shp : Buffer.from(shp);
240	  if (b.length < 100 || b.readInt32BE(0) !== 9994) throw new Error("Keine gültige .shp-Datei.");
241	  const geos = [];
242	  let p = 100;
243	  while (p + 12 <= b.length && geos.length < 200000) {
244	    const laenge = b.readInt32BE(p + 4) * 2;
245	    const c = p + 8;
246	    if (c + laenge > b.length) break;
247	    const typ = b.readInt32LE(c);
248	    const basis = typ % 10; // 1 Punkt, 3 Linie, 5 Polygon, 8 Multipunkt (Z = +10, M = +20)
249	    if (basis === 1) geos.push({ type: "Point", coordinates: [b.readDoubleLE(c + 4), b.readDoubleLE(c + 12)] });
250	    else if (basis === 3 || basis === 5) {
251	      const teile = b.readInt32LE(c + 36);
252	      const punkte = b.readInt32LE(c + 40);
253	      const idx = [];
254	      for (let k = 0; k < teile; k++) idx.push(b.readInt32LE(c + 44 + 4 * k));
255	      const pp = c + 44 + 4 * teile;
256	      const linien = idx.map((von, k) => {
257	        const bis = k + 1 < teile ? idx[k + 1] : punkte;
258	        const l = [];
259	        for (let j = von; j < bis; j++) l.push([b.readDoubleLE(pp + 16 * j), b.readDoubleLE(pp + 16 * j + 8)]);
260	        return l;
261	      });
262	      geos.push(basis === 5 ? { type: "Polygon", coordinates: linien } : { type: "MultiLineString", coordinates: linien });
263	    } else if (basis === 8) {
264	      const punkte = b.readInt32LE(c + 36);
265	      const l = [];
266	      for (let j = 0; j < punkte; j++) l.push([b.readDoubleLE(c + 40 + 16 * j), b.readDoubleLE(c + 48 + 16 * j)]);
267	      geos.push({ type: "MultiPoint", coordinates: l });
268	    }
269	    p = c + laenge;
270	  }
271	  return geos;
272	}
273	
274	/** Shapefile-ZIP → GeoJSON (alle .shp-Dateien; Layer = Dateiname) */
275	export function shapeZuGeojson(buf) {
276	  const liste = zipEintraege(buf);
277	  const features = [];
278	  let projiziert = true;
279	  for (const e of liste.filter((x) => /\.shp$/i.test(x.name) && !x.name.includes(".."))) {
280	    const layer = e.name.split("/").pop().replace(/\.shp$/i, "");
281	    const prj = liste.find((x) => x.name.toLowerCase() === e.name.toLowerCase().replace(/\.shp$/, ".prj"));
282	    if (prj) {
283	      const wkt = zipLesen(buf, prj).toString("utf8");
284	      if (/^\s*GEOGCS/i.test(wkt)) projiziert = false;
285	    }
286	    for (const geometry of shpGeometrien(zipLesen(buf, e))) features.push({ type: "Feature", properties: { layer }, geometry });
287	  }
288	  if (!features.length) throw new Error("Keine Geometrien im Shapefile gefunden.");
289	  return { type: "FeatureCollection", features, oekoinvestProjiziert: projiziert };
290	}

