 51	const ACI_FEST = { 1: [255, 0, 0], 2: [255, 255, 0], 3: [0, 255, 0], 4: [0, 255, 255], 5: [0, 0, 255], 6: [255, 0, 255], 7: [255, 255, 255], 8: [128, 128, 128], 9: [192, 192, 192] };
 52	const ACI_GRAU = { 250: 51, 251: 80, 252: 105, 253: 130, 254: 190, 255: 255 };
