 54	function hsvRgb(h, s, v) {
 55	  const f = (n) => {
 56	    const k = (n + h / 60) % 6;
 57	    return Math.round(255 * (v - v * s * Math.max(0, Math.min(k, 4 - k, 1))));
 58	  };
 59	  return [f(5), f(3), f(1)];
 60	}
