 62	/** ACI 1–255 → [r,g,b] (Näherung der Standardpalette für 10–249: Farbton in 15°-Schritten, Helligkeit/Sättigung je Stufe) */
 63	export function aciRgb(i) {
 64	  const n = Math.abs(Math.round(Number(i) || 7));
 65	  if (ACI_FEST[n]) return ACI_FEST[n];
 66	  if (ACI_GRAU[n] !== undefined) return [ACI_GRAU[n], ACI_GRAU[n], ACI_GRAU[n]];
 67	  if (n >= 10 && n <= 249) {
 68	    const h = Math.floor((n - 10) / 10) * 15;
 69	    const r = (n - 10) % 10;
 70	    const v = [1, 1, 0.8, 0.8, 0.6, 0.6, 0.5, 0.5, 0.3, 0.3][r];
 71	    const s = r % 2 === 0 ? 1 : 0.5;
 72	    return hsvRgb(h, s, v);
 73	  }
 74	  return [255, 255, 255];
 75	}
