 77	/** Farbe für die Darstellung auf hellem Grund: Weiß/sehr helle Farben werden abgedunkelt (ACI 7 = Tinte) */
 78	export function anzeigeFarbe({ aci = 7, rgb = null } = {}) {
 79	  let [r, g, b] = rgb || aciRgb(aci);
 80	  if (!rgb && Math.abs(aci) === 7) return "#151a24";
 81	  const hell = (0.2126 * r + 0.7152 * g + 0.0722 * b) / 255;
 82	  if (hell > 0.72) {
 83	    const f = 0.72 / hell;
 84	    r = Math.round(r * f * 0.8);
 85	    g = Math.round(g * f * 0.8);
 86	    b = Math.round(b * f * 0.8);
 87	  }
 88	  return `#${[r, g, b].map((x) => x.toString(16).padStart(2, "0")).join("")}`;
 89	}
