 98	/** Paare (Gruppencode, Wert) – tolerant gegenüber \r\n, Leerzeichen und fehlender Endzeile */
 99	function paare(text) {
100	  const zeilen = String(text).split(/\r\n|\r|\n/);
101	  const codes = new Int32Array(Math.ceil(zeilen.length / 2));
102	  const werte = new Array(codes.length);
103	  let n = 0;
104	  for (let i = 0; i + 1 < zeilen.length; i += 2) {
105	    const c = parseInt(zeilen[i], 10);
106	    if (Number.isNaN(c)) {
107	      // aus dem Takt (z. B. Leerzeile) – eine Zeile weiter versuchen
108	      i -= 1;
109	      continue;
110	    }
111	    codes[n] = c;
112	    werte[n] = zeilen[i + 1];
113	    n++;
114	  }
115	  return { codes, werte, n };
116	}
