123	/** Ist der Inhalt (Anfang) eine ASCII-DXF? Binär-DXF wird erkannt, aber nicht gelesen. */
124	export function dxfArt(anfang) {
125	  const s = typeof anfang === "string" ? anfang : new TextDecoder("latin1").decode(anfang.subarray ? anfang.subarray(0, 64) : anfang.slice(0, 64));
126	  if (s.startsWith("AutoCAD Binary DXF")) return "binaer";
127	  return /^\s*(?:999\s*[\r\n]+[^\r\n]*[\r\n]+\s*)*0\s*[\r\n]+\s*SECTION\b/.test(s.slice(0, 400)) ? "ascii" : "";
