130	/**
131	 * DXF-Text lesen. Ergebnis: { version, header, layer: {name: {name, aci, rgb, aus, gefroren}}, bloecke: {name: {name, basis:[x,y], entitaeten}},
132	 * entitaeten: [...], zaehler: {TYP: n}, nichtUnterstuetzt: {TYP: n} }
133	 */
134	export function lesen(text, { maxEntitaeten = 2_000_000 } = {}) {
135	  const { codes, werte, n } = paare(text);
136	  const doc = { version: "", header: {}, layer: {}, bloecke: {}, entitaeten: [], zaehler: {}, nichtUnterstuetzt: {}, warnungen: [] };
137	  let i = 0;
138	  let abschnitt = "";
139	  let block = null; // aktueller Block (Abschnitt BLOCKS)
140	  let anzahl = 0;
141	
142	  const naechsteEntitaet = () => {
143	    // Gruppen bis zum nächsten Code 0 lesen
144	    const felder = [];
145	    i++;
146	    while (i < n && codes[i] !== 0) {
147	      felder.push([codes[i], werte[i]]);
148	      i++;
149	    }
150	    return felder;
151	  };
152	
153	  while (i < n) {
154	    const c = codes[i];
155	    const w = String(werte[i]).trim();
156	    if (c !== 0) {
157	      i++;
158	      continue;
159	    }
160	    if (w === "SECTION") {
161	      i++;
162	      abschnitt = codes[i] === 2 ? String(werte[i]).trim() : "";
163	      i++;
164	      if (abschnitt === "HEADER") i = headerLesen(codes, werte, n, i, doc);
165	      continue;
166	    }
167	    if (w === "ENDSEC") {
168	      abschnitt = "";
169	      block = null;
170	      i++;
171	      continue;
172	    }
173	    if (w === "EOF") break;
174	    if (abschnitt === "TABLES") {
175	      if (w === "LAYER") {
176	        const f = naechsteEntitaet();
177	        const l = layerAus(f);
178	        if (l && l.name) doc.layer[l.name] = l;
179	      } else {
180	        i++;
181	      }
182	      continue;
183	    }
184	    if (abschnitt === "BLOCKS") {
185	      if (w === "BLOCK") {
186	        const f = naechsteEntitaet();
187	        const name = wert(f, 2) || wert(f, 3) || "";
188	        block = { name, basis: [zahl(wert(f, 10)), zahl(wert(f, 20))], layer: wert(f, 8) || "0", entitaeten: [] };
189	        doc.bloecke[name] = block;
190	        continue;
191	      }
192	      if (w === "ENDBLK") {
193	        naechsteEntitaet();
194	        block = null;
195	        continue;
196	      }
197	      if (block) {
198	        const { ent, weiter } = entitaetLesen(codes, werte, n, i, doc);
199	        i = weiter;
200	        if (ent) block.entitaeten.push(ent);
201	        continue;
202	      }
203	      i++;
204	      continue;
205	    }
206	    if (abschnitt === "ENTITIES") {
207	      const { ent, weiter } = entitaetLesen(codes, werte, n, i, doc);
208	      i = weiter;
209	      if (ent && !ent.papier) {
210	        doc.entitaeten.push(ent);
211	        if (++anzahl > maxEntitaeten) {
212	          doc.warnungen.push(`Mehr als ${maxEntitaeten} Objekte – Rest nicht gelesen.`);
213	          break;
214	        }
215	      }
216	      continue;
217	    }
218	    i++;
219	  }
220	  doc.version = doc.header.$ACADVER || "";
221	  // Layer „0“ existiert immer
222	  if (!doc.layer["0"]) doc.layer["0"] = { name: "0", aci: 7, rgb: null, aus: false, gefroren: false };
223	  return doc;
224	}
