231	function headerLesen(codes, werte, n, i, doc) {
232	  let variable = "";
233	  while (i < n) {
234	    const c = codes[i];
235	    const w = String(werte[i]).trim();
236	    if (c === 0 && w === "ENDSEC") return i;
237	    if (c === 9) variable = w;
238	    else if (variable === "$INSUNITS" && c === 70) doc.header.$INSUNITS = parseInt(w, 10) || 0;
239	    else if (variable === "$ACADVER" && c === 1) doc.header.$ACADVER = w;
240	    else if ((variable === "$EXTMIN" || variable === "$EXTMAX") && (c === 10 || c === 20)) {
241	      doc.header[variable] ||= [0, 0];
242	      doc.header[variable][c === 10 ? 0 : 1] = zahl(w);
243	    }
244	    i++;
245	  }
246	  return i;
247	}
