249	function layerAus(f) {
250	  const name = wert(f, 2);
251	  if (!name) return null;
252	  const aci = parseInt(wert(f, 62) ?? "7", 10);
253	  const flags = parseInt(wert(f, 70) ?? "0", 10) || 0;
254	  const tc = wert(f, 420);
255	  return { name, aci: Math.abs(aci) || 7, rgb: tc !== undefined ? rgbAus420(tc) : null, aus: aci < 0, gefroren: (flags & 1) === 1 };
