261	    case 8: e.layer = String(w).trim(); return true;
262	    case 62: e.aci = parseInt(w, 10); return true;
263	    case 420: e.rgb = rgbAus420(w); return true;
264	    case 60: e.unsichtbar = parseInt(w, 10) === 1; return true;
265	    case 67: e.papier = parseInt(w, 10) === 1; return true;
266	    case 230: e.ez = zahl(w, 1); return true;
267	    default: return false;
268	  }
269	}
