271	/** Liest die Entität ab Index i (Code 0) inkl. Folgeobjekten (VERTEX/SEQEND, ATTRIB). */
272	function entitaetLesen(codes, werte, n, i, doc) {
273	  const typ = String(werte[i]).trim();
274	  doc.zaehler[typ] = (doc.zaehler[typ] || 0) + 1;
275	  i++;
276	  const e = { typ, layer: "0", aci: 256 };
277	  const f = []; // typspezifische Paare
278	  while (i < n && codes[i] !== 0) {
279	    if (!basisEigenschaften(e, codes[i], werte[i])) f.push([codes[i], werte[i]]);
280	    i++;
281	  }
282	  switch (typ) {
283	    case "LINE":
284	      e.p1 = [zahl(wert(f, 10)), zahl(wert(f, 20))];
285	      e.p2 = [zahl(wert(f, 11)), zahl(wert(f, 21))];
286	      break;
287	    case "POINT":
288	      e.p = [zahl(wert(f, 10)), zahl(wert(f, 20))];
289	      break;
290	    case "CIRCLE":
291	      e.m = [zahl(wert(f, 10)), zahl(wert(f, 20))];
292	      e.r = zahl(wert(f, 40));
293	      break;
294	    case "ARC":
295	      e.m = [zahl(wert(f, 10)), zahl(wert(f, 20))];
296	      e.r = zahl(wert(f, 40));
297	      e.a1 = zahl(wert(f, 50));
298	      e.a2 = zahl(wert(f, 51));
299	      break;
300	    case "ELLIPSE":
301	      e.m = [zahl(wert(f, 10)), zahl(wert(f, 20))];
302	      e.achse = [zahl(wert(f, 11)), zahl(wert(f, 21))];
303	      e.verhaeltnis = zahl(wert(f, 40), 1);
304	      e.t1 = zahl(wert(f, 41), 0);
305	      e.t2 = zahl(wert(f, 42), Math.PI * 2);
306	      break;
307	    case "LWPOLYLINE": {
308	      e.geschlossen = ((parseInt(wert(f, 70) ?? "0", 10) || 0) & 1) === 1;
309	      e.punkte = [];
310	      let akt = null;
311	      for (const [c, w] of f) {
312	        if (c === 10) {
313	          akt = { x: zahl(w), y: 0, b: 0 };
314	          e.punkte.push(akt);
315	        } else if (c === 20 && akt) akt.y = zahl(w);
316	        else if (c === 42 && akt) akt.b = zahl(w);
317	      }
318	      break;
319	    }
320	    case "POLYLINE": {
321	      const flags = parseInt(wert(f, 70) ?? "0", 10) || 0;
322	      e.geschlossen = (flags & 1) === 1;
323	      e.netz = (flags & 16) === 16 || (flags & 64) === 64;
324	      e.punkte = [];
325	      // VERTEX … SEQEND
326	      while (i < n && codes[i] === 0 && String(werte[i]).trim() === "VERTEX") {
327	        i++;
328	        const v = { x: 0, y: 0, b: 0, flags: 0 };
329	        while (i < n && codes[i] !== 0) {
330	          const c = codes[i];
331	          if (c === 10) v.x = zahl(werte[i]);
332	          else if (c === 20) v.y = zahl(werte[i]);
333	          else if (c === 42) v.b = zahl(werte[i]);
334	          else if (c === 70) v.flags = parseInt(werte[i], 10) || 0;
335	          i++;
336	        }
337	        if (!(v.flags & 128) && !(v.flags & 16)) e.punkte.push(v); // keine Flächennetz-Datensätze/Spline-Rahmenpunkte
338	      }
339	      if (i < n && codes[i] === 0 && String(werte[i]).trim() === "SEQEND") {
340	        i++;
341	        while (i < n && codes[i] !== 0) i++;
342	      }
343	      break;
344	    }
345	    case "TEXT":
346	    case "ATTRIB":
347	    case "ATTDEF": {
348	      e.p = [zahl(wert(f, 10)), zahl(wert(f, 20))];
349	      const ha = parseInt(wert(f, 72) ?? "0", 10) || 0;
350	      const va = parseInt(wert(f, typ === "TEXT" ? 73 : 74) ?? "0", 10) || 0;
351	      if ((ha || va) && wert(f, 11) !== undefined) e.p = [zahl(wert(f, 11)), zahl(wert(f, 21))];
352	      e.h = zahl(wert(f, 40), 1);
353	      e.text = textBereinigen(wert(f, 1) || "");
354	      e.rot = (zahl(wert(f, 50)) * Math.PI) / 180;
355	      e.ha = [0, 1, 2, 1, 1, 1][ha] ?? 0; // 3 aligned, 4 middle, 5 fit → mittig
356	      e.va = ha === 4 ? 2 : va; // 0 Grundlinie, 1 unten, 2 Mitte, 3 oben
357	      if (typ !== "TEXT") e.unsichtbar = e.unsichtbar || ((parseInt(wert(f, 70) ?? "0", 10) || 0) & 1) === 1;
