360	    }
361	    case "MTEXT": {
362	      e.p = [zahl(wert(f, 10)), zahl(wert(f, 20))];
363	      e.h = zahl(wert(f, 40), 1);
364	      const teile = f.filter(([c]) => c === 3).map(([, w]) => w);
365	      e.text = mtextBereinigen(teile.join("") + (wert(f, 1) || ""));
366	      const dx = wert(f, 11);
367	      e.rot = dx !== undefined ? Math.atan2(zahl(wert(f, 21)), zahl(dx)) : (zahl(wert(f, 50)) * Math.PI) / 180;
368	      const anker = parseInt(wert(f, 71) ?? "1", 10) || 1; // 1 oben links … 9 unten rechts
369	      e.ha = (anker - 1) % 3;
370	      e.va = [3, 2, 1][Math.floor((anker - 1) / 3)] ?? 3;
