372	      break;
373	    }
374	    case "INSERT": {
375	      e.block = wert(f, 2) || "";
376	      e.p = [zahl(wert(f, 10)), zahl(wert(f, 20))];
377	      e.sx = zahl(wert(f, 41), 1) || 1;
378	      e.sy = zahl(wert(f, 42), 1) || 1;
379	      e.rot = (zahl(wert(f, 50)) * Math.PI) / 180;
380	      e.spalten = Math.max(1, Math.min(1000, parseInt(wert(f, 70) ?? "1", 10) || 1));
381	      e.reihen = Math.max(1, Math.min(1000, parseInt(wert(f, 71) ?? "1", 10) || 1));
382	      e.dx = zahl(wert(f, 44));
383	      e.dy = zahl(wert(f, 45));
384	      e.attribute = [];
385	      if (parseInt(wert(f, 66) ?? "0", 10) === 1) {
386	        while (i < n && codes[i] === 0 && String(werte[i]).trim() === "ATTRIB") {
387	          const r = entitaetLesen(codes, werte, n, i, doc);
388	          i = r.weiter;
389	          if (r.ent) e.attribute.push(r.ent);
390	        }
391	        if (i < n && codes[i] === 0 && String(werte[i]).trim() === "SEQEND") {
392	          i++;
393	          while (i < n && codes[i] !== 0) i++;
394	        }
395	      }
396	      break;
397	    }
398	    case "DIMENSION":
399	      e.block = wert(f, 2) || "";
400	      break;
401	    case "SPLINE": {
402	      const fit = [];
403	      const ctrl = [];
404	      let akt = null;
405	      let liste = null;
406	      for (const [c, w] of f) {
407	        if (c === 10 || c === 11) {
408	          liste = c === 10 ? ctrl : fit;
409	          akt = { x: zahl(w), y: 0, b: 0 };
410	          liste.push(akt);
411	        } else if ((c === 20 || c === 21) && akt) akt.y = zahl(w);
412	      }
413	      e.punkte = fit.length >= 2 ? fit : ctrl;
414	      e.geschlossen = ((parseInt(wert(f, 70) ?? "0", 10) || 0) & 1) === 1;
415	      e.naeherung = true;
416	      break;
417	    }
418	    default:
419	      doc.nichtUnterstuetzt[typ] = (doc.nichtUnterstuetzt[typ] || 0) + 1;
420	      return { ent: null, weiter: i };
421	  }
422	  return { ent: e, weiter: i };
423	}
