470	/** Polylinie mit Bulges → Punkte (flach), exakte Länge und (bei geschlossen) Fläche mit Kreissegmenten */
471	export function polylinie(punkte, geschlossen) {
472	  const out = [];
473	  let laenge = 0;
474	  let flaeche2 = 0; // doppelte Shoelace-Fläche
475	  let segment = 0; // Kreissegmente (vorzeichenbehaftet)
476	  const n = punkte.length;
477	  if (!n) return { pts: out, laenge: 0, flaeche: 0 };
478	  const grenze = geschlossen ? n : n - 1;
479	  out.push(punkte[0].x, punkte[0].y);
480	  for (let k = 0; k < grenze; k++) {
481	    const a = punkte[k];
482	    const b = punkte[(k + 1) % n];
483	    const dx = b.x - a.x;
484	    const dy = b.y - a.y;
485	    const s = Math.hypot(dx, dy);
486	    flaeche2 += a.x * b.y - b.x * a.y;
487	    if (a.b && s > 0) {
488	      const theta = 4 * Math.atan(a.b); // eingeschlossener Winkel (vorzeichenbehaftet)
489	      const r = s / (2 * Math.sin(Math.abs(theta) / 2));
490	      laenge += Math.abs(theta) * r;
491	      segment += ((r * r) / 2) * (Math.abs(theta) - Math.sin(Math.abs(theta))) * Math.sign(theta);
492	      // Mittelpunkt
493	      const mx = (a.x + b.x) / 2;
494	      const my = (a.y + b.y) / 2;
495	      const h = (s / 2) / Math.tan(theta / 2); // Abstand Sehnenmitte → Mittelpunkt (vorzeichenbehaftet)
496	      const cx = mx - (dy / s) * h;
497	      const cy = my + (dx / s) * h;
498	      const w1 = Math.atan2(a.y - cy, a.x - cx);
499	      const schritte = Math.max(2, Math.min(64, Math.ceil(Math.abs(theta) / (Math.PI / 36))));
500	      for (let j = 1; j <= schritte; j++) {
501	        const w = w1 + (theta * j) / schritte;
502	        out.push(cx + Math.abs(r) * Math.cos(w), cy + Math.abs(r) * Math.sin(w));
503	      }
504	    } else {
505	      laenge += s;
506	      out.push(b.x, b.y);
507	    }
508	  }
509	  const flaeche = geschlossen ? Math.abs(flaeche2 / 2 + segment) : 0;
510	  return { pts: out, laenge, flaeche };
511	}
