513	/** Länge einer flachen Punktliste */
514	export function punkteLaenge(pts) {
515	  let l = 0;
516	  for (let k = 2; k < pts.length; k += 2) l += Math.hypot(pts[k] - pts[k - 2], pts[k + 1] - pts[k - 1]);
517	  return l;
518	}
519	
520	/** Fläche einer flachen Punktliste (geschlossen, Shoelace) */
521	export function punkteFlaeche(pts) {
522	  let s = 0;
523	  const n = pts.length / 2;
524	  for (let k = 0; k < n; k++) {
525	    const j = (k + 1) % n;
526	    s += pts[2 * k] * pts[2 * j + 1] - pts[2 * j] * pts[2 * k + 1];
527	  }
528	  return Math.abs(s / 2);
529	}
