531	function transformiere(pts, m) {
532	  if (m === IDENT) return pts;
533	  const out = new Array(pts.length);
534	  for (let k = 0; k < pts.length; k += 2) {
535	    out[k] = m[0] * pts[k] + m[2] * pts[k + 1] + m[4];
536	    out[k + 1] = m[1] * pts[k] + m[3] * pts[k + 1] + m[5];
537	  }
538	  return out;
539	}
