545	/**
546	 * Primitive: { t: "p", L (Layer), aci, rgb, pts: [x0,y0,…], zu (geschlossen), laenge, flaeche, g (Objektnummer der
547	 * obersten Ebene), q (Quelltyp) } bzw. { t: "t", L, aci, rgb, x, y, h, rot, text, ha, va, g }.
548	 */
549	export function aufloesen(doc, { maxPrimitive = 1_500_000, maxTiefe = 12 } = {}) {
550	  const prims = [];
551	  const zaehler = { primitive: 0, abgeschnitten: false };
552	  let g = 0;
553	
554	  const push = (p) => {
555	    if (prims.length >= maxPrimitive) {
556	      zaehler.abgeschnitten = true;
557	      return;
558	    }
559	    prims.push(p);
560	  };
561	
562	  const farbeVon = (e, erbe) => {
563	    if (e.rgb) return { aci: e.aci, rgb: e.rgb };
564	    if (e.aci === 0) return { aci: erbe.aci, rgb: erbe.rgb }; // BYBLOCK
565	    if (e.aci === 256 || e.aci === undefined || Number.isNaN(e.aci)) return null; // BYLAYER → später
566	    return { aci: Math.abs(e.aci), rgb: null };
567	  };
568	
569	  const zeichne = (e, m, erbe, tiefe) => {
570	    if (e.unsichtbar) return;
571	    const layer = e.layer === "0" && erbe.layer ? erbe.layer : e.layer || "0";
572	    const f = farbeVon(e, erbe) || { aci: null, rgb: null }; // null = BYLAYER
573	    let mm = m;
574	    if (e.ez !== undefined && e.ez < 0) mm = mult(m, SPIEGEL_X);
575	    const basis = { L: layer, aci: f.aci, rgb: f.rgb, g: erbe.g, i: erbe.i, q: e.typ };
576	    switch (e.typ) {
577	      case "LINE": {
578	        const pts = transformiere([e.p1[0], e.p1[1], e.p2[0], e.p2[1]], mm);
579	        push({ t: "p", ...basis, pts, zu: false, laenge: punkteLaenge(pts), flaeche: 0 });
580	        break;
581	      }
582	      case "POINT": {
583	        const [x, y] = anwenden(mm, e.p[0], e.p[1]);
584	        push({ t: "p", ...basis, pts: [x, y, x, y], zu: false, laenge: 0, flaeche: 0, punkt: true });
585	        break;
586	      }
587	      case "CIRCLE": {
588	        const roh = [];
589	        bogenPunkte(e.m[0], e.m[1], e.r, 0, Math.PI * 2, roh);
590	        const pts = transformiere(roh, mm);
591	        const s = Math.abs(det(mm));
592	        push({ t: "p", ...basis, pts, zu: true, laenge: 2 * Math.PI * e.r * Math.sqrt(s), flaeche: Math.PI * e.r * e.r * s });
593	        break;
594	      }
595	      case "ARC": {
596	        const roh = [];
597	        bogenPunkte(e.m[0], e.m[1], e.r, (e.a1 * Math.PI) / 180, (e.a2 * Math.PI) / 180, roh);
598	        const pts = transformiere(roh, mm);
599	        push({ t: "p", ...basis, pts, zu: false, laenge: punkteLaenge(pts), flaeche: 0 });
600	        break;
601	      }
602	      case "ELLIPSE": {
603	        const a = Math.hypot(e.achse[0], e.achse[1]);
604	        const w = Math.atan2(e.achse[1], e.achse[0]);
605	        const b = a * e.verhaeltnis;
606	        let t1 = e.t1;
607	        let t2 = e.t2;
608	        while (t2 <= t1) t2 += Math.PI * 2;
609	        const voll = t2 - t1 >= Math.PI * 2 - 1e-9;
610	        const nS = Math.max(8, Math.min(128, Math.ceil((t2 - t1) / (Math.PI / 36))));
611	        const roh = [];
612	        for (let k = 0; k <= nS; k++) {
613	          const t = t1 + ((t2 - t1) * k) / nS;
614	          const x = a * Math.cos(t);
615	          const y = b * Math.sin(t);
616	          roh.push(e.m[0] + x * Math.cos(w) - y * Math.sin(w), e.m[1] + x * Math.sin(w) + y * Math.cos(w));
617	        }
618	        const pts = transformiere(roh, mm);
619	        push({ t: "p", ...basis, pts, zu: voll, laenge: punkteLaenge(pts), flaeche: voll ? Math.PI * a * b * Math.abs(det(mm)) : 0 });
620	        break;
621	      }
622	      case "LWPOLYLINE":
623	      case "POLYLINE":
624	      case "SPLINE": {
625	        if (e.netz || !e.punkte?.length) break;
626	        const r = polylinie(e.punkte, e.geschlossen);
627	        const pts = transformiere(r.pts, mm);
628	        const s = Math.abs(det(mm));
629	        const gleichmaessig = Math.abs(Math.hypot(mm[0], mm[1]) - Math.hypot(mm[2], mm[3])) < 1e-9 * Math.max(1, Math.hypot(mm[0], mm[1]));
630	        push({ t: "p", ...basis, pts, zu: e.geschlossen, laenge: gleichmaessig ? r.laenge * Math.sqrt(s) : punkteLaenge(pts), flaeche: r.flaeche * s, naeherung: !!e.naeherung });
631	        break;
632	      }
633	      case "TEXT":
634	      case "ATTRIB":
635	      case "MTEXT": {
636	        if (!e.text) break;
637	        const [x, y] = anwenden(mm, e.p[0], e.p[1]);
638	        const sk = Math.sqrt(Math.abs(det(mm))) || 1;
639	        push({ t: "t", ...basis, x, y, h: e.h * sk, rot: e.rot + Math.atan2(mm[1], mm[0]), text: e.text, ha: e.ha, va: e.va, mehrzeilig: !!e.mehrzeilig });
640	        break;
641	      }
642	      case "INSERT":
643	      case "DIMENSION": {
644	        const blk = doc.bloecke[e.block];
645	        if (!blk || tiefe >= maxTiefe) break;
646	        const erbeNeu = { layer, aci: f.aci ?? erbe.aci, rgb: f.rgb ?? erbe.rgb, g: erbe.g, i: erbe.i };
647	        if (e.typ === "DIMENSION") {
648	          for (const k of blk.entitaeten) zeichne(k, mm, erbeNeu, tiefe + 1);
649	          break;
650	        }
651	        for (let sp = 0; sp < e.spalten; sp++) {
652	          for (let rh = 0; rh < e.reihen; rh++) {
653	            // Reihen/Spalten im gedrehten Blocksystem versetzt
654	            const off = anwenden(drehung(e.rot), sp * e.dx, rh * e.dy);
655	            const lokal = mult(mult(mult(verschiebung(e.p[0] + off[0], e.p[1] + off[1]), drehung(e.rot)), skalierung(e.sx, e.sy)), verschiebung(-blk.basis[0], -blk.basis[1]));
656	            const mNeu = mult(mm, lokal);
657	            const zelle = tiefe === 0 ? { ...erbeNeu, i: `${erbe.g}:${sp}:${rh}` } : erbeNeu; // jede Blockinstanz der obersten Ebene zählt einzeln
658	            for (const k of blk.entitaeten) zeichne(k, mNeu, zelle, tiefe + 1);
659	          }
660	        }
661	        for (const a of e.attribute || []) zeichne(a, mm, erbeNeu, tiefe + 1); // ATTRIB stehen in Weltkoordinaten des INSERT
662	        break;
663	      }
664	      default:
665	        break;
666	    }
667	  };
668	
669	  for (const e of doc.entitaeten) {
670	    zeichne(e, IDENT, { layer: "", aci: 7, rgb: null, g, i: String(g) }, 0);
671	    g++;
672	  }
673	  zaehler.primitive = prims.length;
674	  zaehler.objekte = g;
675	  return { prims, zaehler };
676	}
