678	/** Bounding Box über Primitive: [minX, minY, maxX, maxY] (null bei leer). Optional nur sichtbare Layer. */
679	export function bbox(prims, { layerAus = null } = {}) {
680	  let x0 = Infinity;
681	  let y0 = Infinity;
682	  let x1 = -Infinity;
683	  let y1 = -Infinity;
684	  for (const p of prims) {
685	    if (layerAus && layerAus.has(p.L)) continue;
686	    if (p.t === "t") {
687	      if (p.x < x0) x0 = p.x;
688	      if (p.y < y0) y0 = p.y;
689	      if (p.x > x1) x1 = p.x;
690	      if (p.y > y1) y1 = p.y;
691	      continue;
692	    }
693	    const pts = p.pts;
694	    for (let k = 0; k < pts.length; k += 2) {
695	      const x = pts[k];
696	      const y = pts[k + 1];
697	      if (x < x0) x0 = x;
698	      if (y < y0) y0 = y;
699	      if (x > x1) x1 = x;
700	      if (y > y1) y1 = y;
701	    }
702	  }
703	  return Number.isFinite(x0) ? [x0, y0, x1, y1] : null;
704	}
