706	/** Bounding Box je Primitiv (für Sichtbarkeitsprüfung/Trefferprüfung) – wird am Primitiv als p.bb gespeichert */
707	export function bboxenSetzen(prims) {
708	  for (const p of prims) {
709	    if (p.t === "t") {
710	      const r = p.h * Math.max(1, (p.text?.length || 1) * 0.7);
711	      p.bb = [p.x - r, p.y - r, p.x + r, p.y + r];
712	      continue;
713	    }
714	    let x0 = Infinity;
715	    let y0 = Infinity;
716	    let x1 = -Infinity;
717	    let y1 = -Infinity;
718	    const pts = p.pts;
719	    for (let k = 0; k < pts.length; k += 2) {
720	      if (pts[k] < x0) x0 = pts[k];
721	      if (pts[k] > x1) x1 = pts[k];
722	      if (pts[k + 1] < y0) y0 = pts[k + 1];
723	      if (pts[k + 1] > y1) y1 = pts[k + 1];
724	    }
725	    p.bb = [x0, y0, x1, y1];
726	  }
727	  return prims;
728	}
