730	/** Punkt in Polygon (flache Punktliste, gerade-ungerade-Regel) */
731	export function punktInPolygon(x, y, pts) {
732	  let innen = false;
733	  const n = pts.length / 2;
734	  for (let i = 0, j = n - 1; i < n; j = i++) {
735	    const xi = pts[2 * i];
736	    const yi = pts[2 * i + 1];
737	    const xj = pts[2 * j];
738	    const yj = pts[2 * j + 1];
739	    if (yi > y !== yj > y && x < ((xj - xi) * (y - yi)) / (yj - yi) + xi) innen = !innen;
740	  }
741	  return innen;
742	}
