746	/** Layer-Name normalisieren: klein, Trennzeichen „_“, Umlaute vereinfacht */
747	export const layerSchluessel = (name) => String(name || "").toLowerCase().replace(/ä/g, "ae").replace(/ö/g, "oe").replace(/ü/g, "ue").replace(/ß/g, "ss").replace(/[\s\-.]+/g, "_");
748	
749	/**
750	 * Konvention (Präfix, groß/klein egal, „-“/Leerzeichen = „_“):
751	 *   PV_Module*          Tische (Objekte bzw. Blockinstanzen der obersten Ebene mit geschlossener Kontur) und Modulfläche
752	 *   Zaun*               Zaunlänge (m)            Kabel_MS*   Trassenlänge Mittelspannung (m)
753	 *   Kabel_DC* / Kabel_AC*  Kabellängen (m)       Wege*       Wegefläche (m², geschlossene Konturen)
754	 *   Trafo*              Anzahl Stationen          Baugrenze*, Umgriff*, Anlagenflaeche*  Anlagenfläche (m² → ha)
755	 */
756	export const LAYER_KONVENTION = [
757	  { id: "module", praefix: ["pv_modul", "pv_tisch", "module"], label: "PV_Module", art: "tische" },
758	  { id: "zaun", praefix: ["zaun"], label: "Zaun", art: "laenge" },
759	  { id: "kabelMs", praefix: ["kabel_ms", "ms_kabel", "ms_trasse", "kabeltrasse_ms"], label: "Kabel_MS", art: "laenge" },
760	  { id: "kabelDc", praefix: ["kabel_dc", "dc_kabel"], label: "Kabel_DC", art: "laenge" },
761	  { id: "kabelAc", praefix: ["kabel_ac", "ac_kabel", "kabel_ns"], label: "Kabel_AC", art: "laenge" },
762	  { id: "wege", praefix: ["wege", "weg_", "zufahrt"], label: "Wege", art: "flaeche" },
763	  { id: "trafo", praefix: ["trafo", "station", "uebergabe"], label: "Trafostation", art: "anzahl" },
764	  { id: "anlage", praefix: ["baugrenze", "umgriff", "anlagenflaeche", "baufeld"], label: "Baugrenze", art: "flaeche" },
765	];
766	
767	export function konventionVon(layerName) {
768	  const s = layerSchluessel(layerName);
769	  return LAYER_KONVENTION.find((k) => k.praefix.some((p) => s.startsWith(p))) || null;
770	}
