772	/** Nennleistung je m² Modulfläche (kWp/m²) für die Schätzung – ~225 Wp/m² wie CARPORT in markt.js */
773	export const KWP_PRO_M2 = 0.225;
774	
775	/**
776	 * Kennzahlen aus aufgelösten Primitiven (Werte in Metern/m² über die Einheit). Nur Layer nach Konvention; unbekannte
777	 * Layer werden ignoriert. Ergebnis: { einheit, tische, modulflaecheM2, kwpGeschaetzt, zaunM, kabelMsM, kabelDcM, kabelAcM,
778	 * wegeM2, trafos, anlageM2, anlageHa, layerGefunden: [..], hinweise: [..] }
779	 */
780	export function kennzahlen(prims, einheit = { m: 1 }) {
781	  const f = einheit.m || 1;
782	  const k = { tische: 0, modulflaecheM2: 0, zaunM: 0, kabelMsM: 0, kabelDcM: 0, kabelAcM: 0, wegeM2: 0, trafos: 0, anlageM2: 0 };
783	  const tischGruppen = new Set();
784	  const trafoGruppen = new Set();
785	  const gefunden = new Set();
786	  for (const p of prims) {
787	    if (p.t !== "p") continue;
788	    const konv = konventionVon(p.L);
789	    if (!konv) continue;
790	    gefunden.add(konv.label);
791	    switch (konv.id) {
792	      case "module":
793	        if (p.zu && p.flaeche > 0) {
794	          tischGruppen.add(p.i);
795	          k.modulflaecheM2 += p.flaeche * f * f;
796	        }
797	        break;
798	      case "zaun":
799	        k.zaunM += p.laenge * f;
800	        break;
801	      case "kabelMs":
802	        k.kabelMsM += p.laenge * f;
803	        break;
804	      case "kabelDc":
805	        k.kabelDcM += p.laenge * f;
806	        break;
807	      case "kabelAc":
808	        k.kabelAcM += p.laenge * f;
809	        break;
810	      case "wege":
811	        if (p.zu) k.wegeM2 += p.flaeche * f * f;
812	        break;
813	      case "trafo":
814	        trafoGruppen.add(p.i);
815	        break;
816	      case "anlage":
817	        if (p.zu) k.anlageM2 += p.flaeche * f * f;
818	        break;
819	      default:
820	        break;
821	    }
822	  }
823	  k.tische = tischGruppen.size;
824	  k.trafos = trafoGruppen.size;
825	  const r = (x, s = 1) => Math.round(x * s) / s;
826	  const erg = {
827	    tische: k.tische,
828	    modulflaecheM2: r(k.modulflaecheM2),
829	    kwpGeschaetzt: r(k.modulflaecheM2 * KWP_PRO_M2),
830	    zaunM: r(k.zaunM, 10),
831	    kabelMsM: r(k.kabelMsM, 10),
832	    kabelDcM: r(k.kabelDcM, 10),
833	    kabelAcM: r(k.kabelAcM, 10),
834	    wegeM2: r(k.wegeM2),
835	    trafos: k.trafos,
836	    anlageM2: r(k.anlageM2),
837	    anlageHa: r(k.anlageM2 / 10000, 100),
838	    layerGefunden: [...gefunden],
839	    hinweise: [],
840	  };
841	  if (!gefunden.size) erg.hinweise.push("Keine Layer nach Konvention gefunden (PV_Module, Zaun, Kabel_MS, Wege, Trafostation, Baugrenze) – Kennzahlen bitte manuell erfassen.");
842	  if (einheit.angenommen) erg.hinweise.push("Zeichnung ohne Einheit ($INSUNITS = 0): Meter angenommen – bitte prüfen.");
843	  return erg;
844	}
