846	/** Bytes → Text: UTF-8 (ab AutoCAD 2007), bei Ersatzzeichen Windows-1252 (ältere DXF mit $DWGCODEPAGE ANSI_1252) */
847	export function dxfDekodieren(bytes) {
848	  const u8 = bytes instanceof Uint8Array ? bytes : new Uint8Array(bytes);
849	  const utf8 = new TextDecoder("utf-8").decode(u8);
850	  if (!utf8.includes("�")) return utf8;
851	  try {
852	    return new TextDecoder("windows-1252").decode(u8);
853	  } catch {
854	    return utf8;
855	  }
856	}
