858	/** Komplette Analyse eines DXF-Texts (Upload-Prüfung, Test): Zähler, Einheit, bbox, Layer, Kennzahlen */
859	export function analysieren(text, optionen = {}) {
860	  const doc = lesen(text, optionen);
861	  const { prims, zaehler } = aufloesen(doc, optionen);
862	  const e = einheitVon(doc);
863	  const aus = new Set(Object.values(doc.layer).filter((l) => l.aus || l.gefroren).map((l) => l.name));
864	  const bb = bbox(prims, { layerAus: aus }); // sichtbare Ausdehnung (ausgeschaltete/gefrorene Layer zählen nicht)
865	  const layerGenutzt = {};
866	  for (const p of prims) layerGenutzt[p.L] = (layerGenutzt[p.L] || 0) + 1;
867	  return {
868	    version: doc.version,
869	    einheit: { code: e.code, kurz: e.kurz, label: e.label, m: e.m, angenommen: !!e.angenommen },
870	    entitaeten: doc.entitaeten.length,
871	    zaehler: doc.zaehler,
872	    nichtUnterstuetzt: doc.nichtUnterstuetzt,
873	    bloecke: Object.keys(doc.bloecke).filter((b) => !b.startsWith("*")).length,
874	    primitive: zaehler.primitive,
875	    abgeschnitten: !!zaehler.abgeschnitten,
876	    bbox: bb,
877	    groesse: bb ? { breite: bb[2] - bb[0], hoehe: bb[3] - bb[1], breiteM: (bb[2] - bb[0]) * e.m, hoeheM: (bb[3] - bb[1]) * e.m } : null,
878	    layer: Object.values(doc.layer).map((l) => ({ name: l.name, aci: l.aci, farbe: anzeigeFarbe(l), aus: l.aus || l.gefroren, objekte: layerGenutzt[l.name] || 0, konvention: konventionVon(l.name)?.label || null })),
879	    kennzahlen: kennzahlen(prims, e),
880	    warnungen: doc.warnungen,
881	  };
882	}

