94	    94	/** Parameter vervollständigen (Standardwerte aus markt.js) */
95	    95	export function parameterVoll(p = {}) {
96	    96	  const typ = p.typ || "freiflaeche";
97	    97	  const kostenstand = KOSTENSTAENDE[p.kostenstand] ? p.kostenstand : "schaetzung";
98	    98	  const q = p.trasse?.querungen || {};
99	    99	  return {
100	   100	    typ,
101	   101	    land: p.land || "DE",
102	   102	    mwp: Math.max(0, Number(p.mwp) || 0),
103	   103	    mwh: Math.max(0, Number(p.mwh) || 0),
104	   104	    flaecheHa: Math.max(0, Number(p.flaecheHa) || 0),
105	   105	    flaechenAnzahl: Math.max(1, Math.round(Number(p.flaechenAnzahl) || 1)),
106	   106	    zaunM: Math.max(0, Number(p.zaunM) || 0),
107	   107	    trasse: {
108	   108	      abschnitte: (Array.isArray(p.trasse?.abschnitte) ? p.trasse.abschnitte : []).filter((a) => VERLEGEARTEN[a?.art] && Number(a.laengeM) > 0).map((a) => ({ art: a.art, laengeM: Number(a.laengeM) })),
109	   109	      querungen: { strasse: Math.max(0, Math.round(Number(q.strasse) || 0)), bahn: Math.max(0, Math.round(Number(q.bahn) || 0)), gewaesser: Math.max(0, Math.round(Number(q.gewaesser) || 0)) },
110	   110	      quelle: p.trasse?.quelle || "",
111	   111	    },
112	   112	    speicherNetzbezug: !!p.speicherNetzbezug,
113	   113	    kostenstand,
114	   114	    contingency: Number.isFinite(Number(p.contingency)) && p.contingency !== null && p.contingency !== "" ? Math.max(0, Math.min(0.5, Number(p.contingency))) : PK.contingency[kostenstand],
115	   115	    fkQuote: Number.isFinite(Number(p.fkQuote)) && p.fkQuote !== null && p.fkQuote !== "" ? Math.max(0, Math.min(1, Number(p.fkQuote))) : FINANZIERUNG.fremdkapitalQuote,
116	   116	    zinsBau: Number.isFinite(Number(p.zinsBau)) && p.zinsBau !== null && p.zinsBau !== "" ? Math.max(0, Math.min(0.2, Number(p.zinsBau))) : (FINANZIERUNG.projekt.referenzzinsPct + FINANZIERUNG.projekt.margePct) / 100,
117	   117	    bauzeitMonate: Math.max(1, Math.min(36, Math.round(Number(p.bauzeitMonate) || PK.bauzeitMonate[typ] || 6))),
118	   118	    gutachten: (Array.isArray(p.gutachten) ? p.gutachten : []).filter((g) => g?.schluessel).map((g) => ({ schluessel: String(g.schluessel), titel: String(g.titel || g.schluessel) })),
119	   119	  };
120	   120	}
