144	   144	  const entwGesamt = kwp * FREIFLAECHE.entwicklungProKwp.min > 0 ? (kwp * (FREIFLAECHE.entwicklungProKwp.min + FREIFLAECHE.entwicklungProKwp.max)) / 2 : 0;
