152	   152	    add({ schluessel: `ent_${k}`, gewerk: `ent_${k}`, bezeichnung: GEWERKE[`ent_${k}`].label, menge: 1, einheit: "psch", ep: r2(rest * PK.entwicklungAnteile[k]), quelle: "markt.js FREIFLAECHE.entwicklungProKwp (Mitte) abzgl. Gutachten" });
