230	   230	/**
231	   231	 * Gespeicherte Positionen mit dem aktuellen Vorschlag zusammenführen: manuelle Positionen bleiben, nicht manuelle
232	   232	 * folgen dem Vorschlag (Ist und Notiz bleiben), freie Positionen („frei:…“) bleiben immer.
233	   233	 */
234	   234	export function zusammenfuehren(gespeichert = [], vorschlaege = []) {
235	   235	  const alt = new Map(gespeichert.map((x) => [x.schluessel, x]));
236	   236	  const out = [];
237	   237	  for (const v of vorschlaege) {
238	   238	    const a = alt.get(v.schluessel);
239	   239	    const vor = { menge: v.menge, ep: v.ep, satz: v.satz };
240	   240	    if (a?.manuell) out.push({ ...v, ...pick(a), manuell: true, vorschlag: vor });
241	   241	    else out.push({ ...v, id: a?.id, istEur: a?.istEur ?? null, notiz: a?.notiz || "", angebot: a?.angebot || "", manuell: false, vorschlag: vor });
242	   242	    alt.delete(v.schluessel);
243	   243	  }
244	   244	  for (const a of alt.values()) {
245	   245	    if (String(a.schluessel).startsWith("frei:") || a.manuell || Number(a.istEur) > 0) out.push({ ...a, vorschlag: a.schluessel.startsWith("frei:") ? null : a.vorschlag || null, entfallen: !a.schluessel.startsWith("frei:") });
246	   246	  }
247	   247	  return out;
248	   248	}
249	   249	const pick = (a) => ({ id: a.id, bezeichnung: a.bezeichnung, menge: a.menge, ep: a.ep, satz: a.satz, einheit: a.einheit, istEur: a.istEur ?? null, notiz: a.notiz || "", angebot: a.angebot || "" });
