251	   251	/**
252	   252	 * Berechnung: Beträge je Position, Summen je Gruppe/Gewerk, Kennzahlen, Benchmark-Ampeln.
253	   253	 * Ergebnis { positionen[+betrag, eurProKwp, abweichung, ampel], gruppen{}, gewerke{}, summen{…}, benchmark{…} }
254	   254	 */
255	   255	export function berechnen(positionen, parameter) {
256	   256	  const p = parameterVoll(parameter);
257	   257	  const kwp = p.mwp * 1000;
258	   258	  const liste = positionen.map((x) => ({ ...x, gruppe: GEWERKE[x.gewerk]?.gruppe || "neben" }));
259	   259	  const betragMenge = (x) => r2((Number(x.menge) || 0) * (Number(x.ep) || 0));
260	   260	  const summeWo = (f) => liste.filter(f).reduce((s, x) => s + (x.betrag || 0), 0);
261	   261	  // 1. Mengenpositionen
262	   262	  for (const x of liste) if (x.art === "menge" || !x.art) x.betrag = betragMenge(x);
263	   263	  // 2. Aufschläge auf Technik (Bauleitung/EPC-Marge)
264	   264	  const technikBasis = summeWo((x) => x.gruppe === "technik" && x.art !== "prozent" && x.gewerk !== "speicher");
265	   265	  for (const x of liste) if (x.art === "prozent" && x.basis === "technik") x.betrag = r2(technikBasis * (Number(x.satz) || 0));
266	   266	  // 3. Bezug Bau (Technik + Netz): Versicherung, Unvorhergesehenes
267	   267	  const bau = summeWo((x) => x.gruppe === "technik" || x.gruppe === "netz");
268	   268	  for (const x of liste) if (x.art === "prozent" && x.basis === "bau") x.betrag = r2(bau * (Number(x.satz) || 0));
269	   269	  // 4. Bauzeitzinsen: FK-Quote × (Bau + Neben + Reserve) × Zins × Monate/12 × 0,5
270	   270	  const bauGesamt = summeWo((x) => ["technik", "netz", "neben", "reserve"].includes(x.gruppe) && x.art !== "zins");
271	   271	  for (const x of liste) if (x.art === "zins") x.betrag = r2(p.fkQuote * bauGesamt * (Number(x.satz) || 0) * (p.bauzeitMonate / 12) * 0.5);
272	   272	  // 5. Bezug Investition (alles außer Finanzierung/Sicherheit): Gebühren
273	   273	  const invest = summeWo((x) => !["finanzierung", "sicherheit"].includes(x.gruppe));
274	   274	  for (const x of liste) if (x.art === "prozent" && x.basis === "invest") x.betrag = r2(invest * (Number(x.satz) || 0));
275	   275	
276	   276	  const gruppen = {};
277	   277	  const gewerke = {};
278	   278	  for (const g of Object.keys(GRUPPEN)) gruppen[g] = { soll: 0, ist: 0, eurProKwp: null };
279	   279	  for (const x of liste) {
280	   280	    gruppen[x.gruppe].soll += x.betrag || 0;
281	   281	    gruppen[x.gruppe].ist += Number(x.istEur) || 0;
282	   282	    const gw = (gewerke[x.gewerk] ||= { soll: 0, ist: 0, vorschlag: 0, eurProKwp: null });
283	   283	    gw.soll += x.betrag || 0;
284	   284	    gw.ist += Number(x.istEur) || 0;
285	   285	    // Vorschlagswert der Position (für Abweichung)
286	   286	    if (x.vorschlag && (x.art === "menge" || !x.art)) x.vorschlagBetrag = r2((Number(x.vorschlag.menge) || 0) * (Number(x.vorschlag.ep) || 0));
287	   287	    else if (x.vorschlag && x.satz && x.vorschlag.satz) x.vorschlagBetrag = r2((x.betrag || 0) * (x.vorschlag.satz / x.satz));
288	   288	    else x.vorschlagBetrag = null;
289	   289	    x.abweichung = x.vorschlagBetrag ? (x.betrag - x.vorschlagBetrag) / x.vorschlagBetrag : null;
290	   290	    x.ampel = x.abweichung === null || !x.manuell ? null : Math.abs(x.abweichung) <= 0.1 ? "gruen" : Math.abs(x.abweichung) <= 0.25 ? "gelb" : "rot";
291	   291	    x.eurProKwp = kwp > 0 ? r2(x.betrag / kwp) : null;
292	   292	    gw.vorschlag += x.vorschlagBetrag ?? x.betrag ?? 0;
293	   293	  }
294	   294	  for (const g of Object.values(gruppen)) {
295	   295	    g.soll = r2(g.soll);
296	   296	    g.ist = r2(g.ist);
297	   297	    g.eurProKwp = kwp > 0 ? r2(g.soll / kwp) : null;
298	   298	  }
299	   299	  for (const g of Object.values(gewerke)) {
300	   300	    g.soll = r2(g.soll);
301	   301	    g.ist = r2(g.ist);
302	   302	    g.vorschlag = r2(g.vorschlag);
303	   303	    g.eurProKwp = kwp > 0 ? r2(g.soll / kwp) : null;
304	   304	  }
305	   305	  const gesamt = r2(Object.entries(gruppen).filter(([k]) => k !== "sicherheit").reduce((s, [, g]) => s + g.soll, 0));
306	   306	  const capex = r2(gesamt - gruppen.finanzierung.soll);
307	   307	  const finanzierungsbedarf = r2(gesamt + gruppen.sicherheit.soll);
308	   308	  const epcOhneSpeicher = r2(gruppen.technik.soll - (gewerke.speicher?.soll || 0));
309	   309	  const summen = {
310	   310	    gesamt, capex, finanzierungsbedarf, bau: r2(bau), invest: r2(invest),
311	   311	    ist: r2(liste.reduce((s, x) => s + (Number(x.istEur) || 0), 0)),
312	   312	    eurProKwp: kwp > 0 ? r2(gesamt / kwp) : null,
313	   313	    capexProKwp: kwp > 0 ? r2(capex / kwp) : null,
314	   314	    epcProKwp: kwp > 0 && p.typ !== "speicher" ? r2(epcOhneSpeicher / kwp) : null,
315	   315	    eurProKwh: p.mwh > 0 ? r2((gewerke.speicher?.soll || 0) / (p.mwh * 1000)) : null,
316	   316	    kwp,
317	   317	  };
318	   318	  return { positionen: liste, gruppen, gewerke, summen, benchmark: benchmark(summen, gruppen, p), parameter: p };
319	   319	}
