332	   332	    const anteil = summen.epcProKwp > 0 ? gruppen.netz.soll / (summen.epcProKwp * kwp) : 0;
333	   333	    out.push({ id: "netz", label: "Netzanschluss in % der Anlage", wert: r2(anteil * 10000) / 100, einheit: "%", ampel: anteil <= 0.15 ? "gruen" : anteil <= 0.3 ? "gelb" : "rot", text: "bis 15 % unkritisch, über 30 % drückt die Rendite spürbar (Netzanschluss-Check)" });
334	   334	  }
335	   335	  if (p.mwh > 0) {
336	   336	    const w = summen.eurProKwh;
