338	   338	    out.push({ id: "speicher", label: "Speicher €/kWh", wert: w, min: sp.min, max: sp.max, mittel: sp.mittel, ampel: w <= sp.max && w >= sp.min ? "gruen" : w <= sp.max * 1.1 ? "gelb" : "rot", text: `Spanne ${sp.min}–${sp.max} €/kWh` });
339	   339	  }
340	   340	  const schlecht = out.some((b) => b.ampel === "rot") ? "rot" : out.some((b) => b.ampel === "gelb") ? "gelb" : "gruen";
341	   341	  return { eintraege: out, ampel: out.length ? schlecht : null };
