348	   348	export function sollIst(ergebnis, istFinanzen = null) {
349	   349	  const zeilen = {};
350	   350	  for (const x of ergebnis.positionen) {
351	   351	    const art = GEWERKE[x.gewerk]?.kostenart || (x.gruppe === "entwicklung" ? "sonstiges" : null);
352	   352	    const key = art || `gruppe:${x.gruppe}`;
353	   353	    const z = (zeilen[key] ||= { schluessel: key, kostenart: art, gruppe: x.gruppe, soll: 0, istManuell: 0, istFinanzen: null });
