202	async function konvertieren(version, daten) {
203	  const r = await dwgNachDxf(daten);
204	  if (!r.ok) return { konvertierung: { status: r.status, hinweis: r.status === "nicht_verfuegbar" ? "Vorschau nach Konvertierung (Dienst nicht eingerichtet)." : r.fehler, am: jetzt() } };
205	  const datei = `${version.id}-${zufallsToken().slice(0, 12)}.dxf`;
206	  await uploadSchreiben(datei, r.daten);
207	  const { analyse } = analyseDatei("dxf", r.daten);
208	  return {
209	    konvertierung: { status: "fertig", hinweis: `DWG → DXF in ${Math.round(r.dauerMs / 100) / 10} s`, am: jetzt() },
210	    abgeleitet: { name: String(version.datei.name || "plan").replace(/\.dwg$/i, "") + ".dxf", mime: FORMATE.dxf.mime, groesse: r.daten.length, datei, art: "dxf" },
211	    analyse: { ...analyse, dwgVersion: version.analyse?.dwgVersion, dwgRelease: version.analyse?.dwgRelease },
212	  };
213	}
