215	/**
216	 * Upload einer Planversion. Ohne planId entsteht ein neuer Plan (Backoffice oder Gutachter am zugewiesenen Meilenstein).
217	 * daten = Buffer; Format wird am Inhalt erkannt (formatErkennen), Größenlimit je Format.
218	 */
219	export async function planungHochladen(n, { projektId, planId = "", plan = {}, version = {}, name = "", daten } = {}) {
220	  angemeldet(n);
221	  const erk = formatErkennen(daten, name);
222	  if (!erk.ok) throw new PlattformFehler(erk.status, erk.fehler);
223	  const db0 = await lesenBereit();
224	  const p0 = projektLaden(db0, projektId);
225	  const z0 = kontext(db0, n, p0);
226	  let planAlt = null;
227	  if (planId) {
228	    planAlt = PL(db0).plaene.find((x) => x.id === v.kennung(planId) && x.projektId === p0.id);
229	    if (!planAlt) throw nichtGefunden("Plan nicht gefunden.");
230	    const zg = planZugriff(z0, planAlt, PL(db0).versionen.filter((x) => x.planId === planAlt.id));
231	    if (!zg.hochladen) throw verboten("Neue Planstände dürfen nur die Projektentwicklung und der beauftragte Planer hochladen.");
232	  } else {
233	    const msId = v.kennung(plan.meilensteinId);
234	    if (!z0.schreiben && !(msId && z0.gutachterMs.has(msId))) throw verboten("Neue Pläne dürfen nur die Projektentwicklung und zugewiesene Planer/Gutachter anlegen.");
235	    if (msId && !meilensteine(db0, p0.id).some((m) => m.id === msId)) throw ungueltig("Meilenstein gehört nicht zu diesem Projekt.");
236	  }
237	  const endung = FORMATE[erk.format].endung;
238	  const versionId = neueId("PLV");
239	  const datei = `${versionId}-${zufallsToken().slice(0, 12)}.${endung}`;
240	  await uploadSchreiben(datei, daten);
241	  const { analyse, abgeleitet: abg } = analyseDatei(erk.format, daten, erk.info);
242	  let abgeleitet = null;
243	  if (abg) {
244	    const d2 = `${versionId}-${zufallsToken().slice(0, 12)}-vorschau.geojson`;
245	    await uploadSchreiben(d2, abg.daten);
246	    abgeleitet = { name: abg.name, mime: abg.mime, groesse: abg.daten.length, datei: d2, art: abg.art };
247	  }
248	  const sauber = v.text(String(name || "").replace(/[\\/:*?"<>|]/g, "_"), 160) || `plan.${endung}`;
249	  const neu = {
250	    id: versionId, format: erk.format, datei: { name: sauber, mime: FORMATE[erk.format].mime, groesse: daten.length, datei }, abgeleitet, analyse: { ...analyse, hinweis: erk.info.hinweis || undefined },
251	    konvertierung: erk.format === "dwg" ? { status: "ausstehend", hinweis: "Vorschau nach Konvertierung", am: jetzt() } : null,
252	  };
253	  if (erk.format === "dwg") Object.assign(neu, await konvertieren(neu, daten));
254	
255	  return aendern((db) => {
256	    const p = projektLaden(db, projektId);
257	    const z = kontext(db, n, p);
258	    let pl;
259	    if (planId) pl = PL(db).plaene.find((x) => x.id === planAlt.id);
260	    else {
261	      const kopf = planDaten(plan);
262	      if (PL(db).plaene.some((y) => y.projektId === p.id && y.plannummer.toLowerCase() === kopf.plannummer.toLowerCase())) throw konflikt(`Plannummer „${kopf.plannummer}“ ist bereits vergeben – bitte als neuen Planstand zum bestehenden Plan hochladen.`);
263	      const msId = v.kennung(plan.meilensteinId) || null;
264	      pl = { id: neueId("PL"), projektId: p.id, ...kopf, meilensteinId: msId, planerId: z.schreiben ? null : n.id, erstelltVon: n.id, erstelltAm: jetzt(), geaendertAm: jetzt() };
265	      PL(db).plaene.push(pl);
266	    }
267	    const vorhanden = PL(db).versionen.filter((x) => x.planId === pl.id);
268	    const x = {
269	      ...neu, planId: pl.id, projektId: p.id, index: naechsterIndex(vorhanden.map((y) => y.index)),
270	      planstand: /^\d{4}-\d{2}-\d{2}$/.test(String(version.planstand || "")) ? version.planstand : jetzt().slice(0, 10),
271	      planer: v.text(version.planer, 120) || pl.planer || nameVon(db, n.id), aenderung: v.text(version.aenderung, 300) || (vorhanden.length ? "" : "Erstausgabe"),
272	      status: "entwurf", statusVerlauf: [{ status: "entwurf", am: jetzt(), vonId: n.id, kommentar: "Hochgeladen" }], vonId: n.id, am: jetzt(),
273	    };
274	    PL(db).versionen.push(x);
275	    pl.geaendertAm = jetzt();
276	    protokoll(db, n, "plan", "entwicklung", p.id, `Planstand ${pl.plannummer} Index ${x.index} hochgeladen (${FORMATE[x.format].label})`);
277	    return { plan: planAusgabe(db, pl, z), version: versionAusgabe(db, x, { ...z, planer: true }) };
278	  });
279	}
