289	/** Statusaktion an einer Version: einreichen | freigeben | zurueckweisen | zurueckziehen | konvertieren | analysieren (Kennzahlen neu auswerten) */
290	export async function planungVersionAktion(n, versionId, { aktion, kommentar = "" } = {}) {
291	  angemeldet(n);
292	  const db0 = await lesenBereit();
293	  const { x: x0, plan: plan0, p: p0 } = versionFinden(db0, versionId);
294	  const z0 = kontext(db0, n, p0);
295	  const zg0 = planZugriff(z0, plan0, [x0]);
296	  if (!zg0.version(x0)) throw verboten("Kein Zugriff auf diesen Plan.");
297	  if (aktion === "konvertieren") {
298	    if (!z0.schreiben) throw verboten("Nur die Projektentwicklung kann die Konvertierung anstoßen.");
299	    if (x0.format !== "dwg") throw ungueltig("Nur DWG-Dateien werden konvertiert.");
300	    const erg = await konvertieren(x0, await uploadLesen(x0.datei.datei));

300	    const erg = await konvertieren(x0, await uploadLesen(x0.datei.datei));
301	    return aendern((db) => {
302	      const { x, plan, p } = versionFinden(db, versionId);
303	      Object.assign(x, erg);
304	      protokoll(db, n, "plan", "entwicklung", p.id, `Konvertierung ${plan.plannummer} Index ${x.index}: ${erg.konvertierung.status}`);
305	      return versionAusgabe(db, x, { ...kontext(db, n, p), planer: true });
306	    });
307	  }
308	  if (aktion === "analysieren") {
309	    if (!z0.schreiben) throw verboten("Nur die Projektentwicklung kann die Auswertung anstoßen.");
310	    const quelle = x0.format === "dwg" ? x0.abgeleitet : x0.datei;
311	    if (!quelle?.datei) throw konflikt("Noch keine auswertbare Datei – DWG bitte erst konvertieren.");
312	    const { analyse } = analyseDatei(x0.format === "dwg" ? "dxf" : x0.format, await uploadLesen(quelle.datei), {});
313	    return aendern((db) => {
314	      const { x, plan, p } = versionFinden(db, versionId);
315	      x.analyse = { ...(x.analyse || {}), ...analyse };
316	      protokoll(db, n, "plan", "entwicklung", p.id, `Plan ${plan.plannummer} Index ${x.index} ausgewertet`);
317	      return versionAusgabe(db, x, { ...kontext(db, n, p), planer: true });
318	    });
319	  }
320	  const rolle = z0.schreiben ? "bo" : zg0.planer ? "planer" : "";
321	  if (!rolle) throw verboten("Dafür fehlt Ihnen das Recht.");
322	  return aendern((db) => {
323	    const { x, plan, p } = versionFinden(db, versionId);
324	    const pr = aktionPruefen(aktion, { status: x.status, rolle, kommentar });
325	    if (!pr.ok) throw new PlattformFehler(pr.status, pr.fehler);
326	    x.status = pr.nach;
327	    x.statusVerlauf = [...(x.statusVerlauf || []), { status: pr.nach, am: jetzt(), vonId: n.id, kommentar: v.text(kommentar, 300) }];
328	    if (pr.nach === "freigegeben") {
329	      for (const y of PL(db).versionen) {
330	        if (y.planId === plan.id && y.id !== x.id && y.status === "freigegeben") {
331	          y.status = "ersetzt";
332	          y.statusVerlauf = [...(y.statusVerlauf || []), { status: "ersetzt", am: jetzt(), vonId: n.id, kommentar: `Ersetzt durch Index ${x.index}` }];
333	        }
334	      }
335	      x.freigegebenAm = jetzt();
336	      x.freigegebenVon = n.id;
337	    }
338	    // Benachrichtigungen: Einreichung → Projektleitung; Freigabe/Zurückweisung → Planer (Hochladender, falls extern)
339	    const pl = p.projektleiterId ? nutzerById(db, p.projektleiterId) : null;
340	    if (aktion === "einreichen" && pl && pl.id !== n.id) benachrichtigen(db, pl, { art: "entwicklung", titel: `Plan zur Prüfung: ${plan.plannummer}`, text: `${plan.titel} (Index ${x.index}) im Projekt „${p.titel}“ wartet auf Prüfung.`, link: `/portal/admin/entwicklung/${p.id}?reiter=planung`, objektArt: "entwicklung", objektId: p.id }, { mailBetreff: "Plan zur Prüfung – ÖkoInvest", mailText: "Ein Planstand wurde zur Prüfung eingereicht. Details finden Sie im Portal." });
