/** Beispiel-Datenblatt je Demo-Projekt (Phase/Typ-gerecht, fiktiv) */
export function demoDatenblatt(p) {

  1	// src/lib/plattform/geodaten/geo.js
  2	//
  3	// Reine Geometrie-Helfer für das Akquise-Cockpit (Client + Server, ohne Fremdpakete). Koordinaten wie in
  4	// GeoJSON: [lon, lat] in WGS84 (EPSG:4326). Flächen und Abstände werden in einer lokalen, flächentreuen
  5	// Näherung (äquirektangulär um den Mittelpunkt) gerechnet – für Parzellen und Cluster bis einige Kilometer
  6	// ist der Fehler < 0,5 %. Der Geodaten-Dienst rechnet im Betrieb exakt in EPSG:31287 (MGI / Austria Lambert).
  7	// Gegenstück in Python: Backend-Import/dienste/geodaten/geodaten/geometrie.py (gleiche Formeln, gleiche Tests).
  8	
  9	export const ERDRADIUS_M = 6371008.8;
 10	const RAD = Math.PI / 180;
 11	
 12	/** Großkreisentfernung in Metern zwischen [lon, lat] und [lon, lat] */
 13	export function distanzM(a, b) {
 14	  const dLat = (b[1] - a[1]) * RAD;
 15	  const dLon = (b[0] - a[0]) * RAD;
 16	  const h = Math.sin(dLat / 2) ** 2 + Math.cos(a[1] * RAD) * Math.cos(b[1] * RAD) * Math.sin(dLon / 2) ** 2;
 17	  return 2 * ERDRADIUS_M * Math.asin(Math.min(1, Math.sqrt(h)));
 18	}
 19	
 20	/** Projektion [lon, lat] → [x, y] in Metern um einen Bezugspunkt (lokal äquirektangulär) */
 21	export function projektor(bezug) {
 22	  const kx = Math.cos(bezug[1] * RAD) * ERDRADIUS_M * RAD;
 23	  const ky = ERDRADIUS_M * RAD;
 24	  return (p) => [(p[0] - bezug[0]) * kx, (p[1] - bezug[1]) * ky];
 25	}
 26	
 27	/** Äußerer Ring eines GeoJSON-Polygons bzw. aller Teile eines MultiPolygons */
 28	export function ringe(geometrie) {
 29	  if (!geometrie) return [];
 30	  if (geometrie.type === "Polygon") return [geometrie.coordinates];
 31	  if (geometrie.type === "MultiPolygon") return geometrie.coordinates;
 32	  return [];
 33	}
 34	
 35	function ringFlaeche(ring) {
 36	  let s = 0;
 37	  for (let i = 0, j = ring.length - 1; i < ring.length; j = i++) s += ring[j][0] * ring[i][1] - ring[i][0] * ring[j][1];
 38	  return s / 2;
 39	}
 40	
 41	function ringUmfang(ring) {
 42	  let s = 0;
 43	  for (let i = 1; i < ring.length; i++) s += Math.hypot(ring[i][0] - ring[i - 1][0], ring[i][1] - ring[i - 1][1]);
 44	  return s;
 45	}
 46	
 47	/** Bounding Box [minLon, minLat, maxLon, maxLat] beliebiger GeoJSON-Geometrie */
 48	export function bbox(geometrie) {
 49	  const b = [Infinity, Infinity, -Infinity, -Infinity];
 50	  const lauf = (c) => {
 51	    if (typeof c[0] === "number") {
 52	      if (c[0] < b[0]) b[0] = c[0];
 53	      if (c[1] < b[1]) b[1] = c[1];
 54	      if (c[0] > b[2]) b[2] = c[0];
 55	      if (c[1] > b[3]) b[3] = c[1];
 56	    } else for (const x of c) lauf(x);
 57	  };
 58	  if (geometrie?.coordinates) lauf(geometrie.coordinates);
 59	  return b;
 60	}
 61	
 62	export const bboxSchneidet = (a, b) => a[0] <= b[2] && a[2] >= b[0] && a[1] <= b[3] && a[3] >= b[1];
 63	
 64	/** Schwerpunkt (Flächenschwerpunkt des größten Teils; bei Punkten der Punkt) als [lon, lat] */
 65	export function schwerpunkt(geometrie) {
 66	  if (geometrie?.type === "Point") return geometrie.coordinates;
 67	  const teile = ringe(geometrie);
 68	  if (!teile.length) return null;
 69	  let best = null;
 70	  let bestA = -1;
 71	  for (const poly of teile) {
 72	    const ring = poly[0];
 73	    const bb = bbox({ coordinates: ring });
 74	    const bezug = [(bb[0] + bb[2]) / 2, (bb[1] + bb[3]) / 2];
 75	    const p = projektor(bezug);
 76	    const xy = ring.map(p);
 77	    const a = ringFlaeche(xy);
 78	    if (Math.abs(a) <= bestA) continue;
 79	    let cx = 0;
 80	    let cy = 0;
 81	    for (let i = 0, j = xy.length - 1; i < xy.length; j = i++) {
 82	      const f = xy[j][0] * xy[i][1] - xy[i][0] * xy[j][1];
 83	      cx += (xy[j][0] + xy[i][0]) * f;
 84	      cy += (xy[j][1] + xy[i][1]) * f;
 85	    }
 86	    if (a === 0) continue;
 87	    cx /= 6 * a;
 88	    cy /= 6 * a;
 89	    const kx = Math.cos(bezug[1] * RAD) * ERDRADIUS_M * RAD;
 90	    const ky = ERDRADIUS_M * RAD;
 91	    best = [bezug[0] + cx / kx, bezug[1] + cy / ky];
 92	    bestA = Math.abs(a);
 93	  }
 94	  return best;
 95	}
 96	
 97	/** Fläche in m² (Außenringe minus Löcher) */
 98	export function flaecheM2(geometrie) {
 99	  const teile = ringe(geometrie);
100	  if (!teile.length) return 0;
101	  const bb = bbox(geometrie);
102	  const p = projektor([(bb[0] + bb[2]) / 2, (bb[1] + bb[3]) / 2]);
103	  let s = 0;
104	  for (const poly of teile) {
105	    poly.forEach((ring, i) => {
106	      const a = Math.abs(ringFlaeche(ring.map(p)));
107	      s += i === 0 ? a : -a;
108	    });
109	  }
110	  return Math.max(0, s);
111	}
112	
113	/** Umfang in m (nur Außenringe) */
114	export function umfangM(geometrie) {
115	  const teile = ringe(geometrie);
116	  if (!teile.length) return 0;
117	  const bb = bbox(geometrie);
118	  const p = projektor([(bb[0] + bb[2]) / 2, (bb[1] + bb[3]) / 2]);
119	  return teile.reduce((s, poly) => s + ringUmfang(poly[0].map(p)), 0);
120	}
121	
122	/** Konvexe Hülle (Andrew's Monotone Chain) von Punkten [x, y] */
123	export function konvexeHuelle(punkte) {
124	  const p = [...punkte].sort((a, b) => a[0] - b[0] || a[1] - b[1]);
125	  if (p.length < 3) return p;
126	  const kreuz = (o, a, b) => (a[0] - o[0]) * (b[1] - o[1]) - (a[1] - o[1]) * (b[0] - o[0]);
127	  const unten = [];
128	  for (const q of p) {
129	    while (unten.length >= 2 && kreuz(unten[unten.length - 2], unten[unten.length - 1], q) <= 0) unten.pop();
130	    unten.push(q);
131	  }
132	  const oben = [];
133	  for (let i = p.length - 1; i >= 0; i--) {
134	    const q = p[i];
135	    while (oben.length >= 2 && kreuz(oben[oben.length - 2], oben[oben.length - 1], q) <= 0) oben.pop();
136	    oben.push(q);
137	  }
138	  return unten.slice(0, -1).concat(oben.slice(0, -1));
139	}
140	
141	/**
142	 * Kompaktheit eines Flächenverbunds (0–1): Anteil der Fläche an ihrer konvexen Hülle („Solidity“),
143	 * kombiniert mit dem Seitenverhältnis des umschließenden Rechtecks (schmale Streifen sind schlecht belegbar).
144	 * `geometrien` = Liste von Polygonen (Parzellen eines Clusters), `flaeche` = Summe ihrer Flächen in m².
145	 */
146	export function kompaktheit(geometrien, flaeche) {
147	  const alle = geometrien.flatMap((g) => ringe(g).flatMap((poly) => poly[0]));
148	  if (alle.length < 3 || !flaeche) return 0;
149	  const bb = bbox({ coordinates: alle });
150	  const p = projektor([(bb[0] + bb[2]) / 2, (bb[1] + bb[3]) / 2]);
151	  const huelle = konvexeHuelle(alle.map(p));
152	  const hA = Math.abs(ringFlaeche([...huelle, huelle[0]]));
153	  const solidity = hA > 0 ? Math.min(1, flaeche / hA) : 0;
154	  // Seitenverhältnis über die Hauptachsen der Hülle (Kovarianz der Hüllpunkte)
155	  const n = huelle.length;
156	  const mx = huelle.reduce((s, q) => s + q[0], 0) / n;
157	  const my = huelle.reduce((s, q) => s + q[1], 0) / n;
158	  let sxx = 0;
159	  let syy = 0;
160	  let sxy = 0;
161	  for (const q of huelle) {
162	    sxx += (q[0] - mx) ** 2;
163	    syy += (q[1] - my) ** 2;
164	    sxy += (q[0] - mx) * (q[1] - my);
165	  }
166	  const spur = sxx + syy;
167	  const d = Math.sqrt(Math.max(0, ((sxx - syy) / 2) ** 2 + sxy ** 2));
168	  const l1 = spur / 2 + d;
169	  const l2 = Math.max(1e-9, spur / 2 - d);
170	  const verhaeltnis = Math.sqrt(l1 / l2); // 1 = rund/quadratisch
171	  const streckung = verhaeltnis <= 2.5 ? 1 : Math.max(0, 1 - (verhaeltnis - 2.5) / 5);
172	  return Math.round(solidity * streckung * 1000) / 1000;
173	}
