175	/** Punkt in Polygon (Ray Casting, Löcher berücksichtigt) */
176	export function punktInPolygon(pt, geometrie) {
177	  for (const poly of ringe(geometrie)) {
178	    const drin = (ring) => {
179	      let ja = false;
180	      for (let i = 0, j = ring.length - 1; i < ring.length; j = i++) {
181	        const [xi, yi] = ring[i];
182	        const [xj, yj] = ring[j];
183	        if (yi > pt[1] !== yj > pt[1] && pt[0] < ((xj - xi) * (pt[1] - yi)) / (yj - yi + 1e-300) + xi) ja = !ja;
184	      }
185	      return ja;
186	    };
187	    if (drin(poly[0]) && !poly.slice(1).some(drin)) return true;
188	  }
189	  return false;
190	}
191	
192	function abstandPunktStrecke(p, a, b) {
193	  const dx = b[0] - a[0];
194	  const dy = b[1] - a[1];
195	  const l2 = dx * dx + dy * dy;
196	  const t = l2 ? Math.max(0, Math.min(1, ((p[0] - a[0]) * dx + (p[1] - a[1]) * dy) / l2)) : 0;
197	  return Math.hypot(p[0] - (a[0] + t * dx), p[1] - (a[1] + t * dy));
198	}
