200	/** Kürzester Abstand in m zwischen Punkt [lon, lat] und Polygon (0, wenn innen) */
201	export function abstandPunktPolygonM(pt, geometrie) {
202	  if (punktInPolygon(pt, geometrie)) return 0;
203	  const p = projektor(pt);
204	  const q = p(pt);
205	  let min = Infinity;
206	  for (const poly of ringe(geometrie)) {
207	    for (const ring of poly) {
208	      const xy = ring.map(p);
209	      for (let i = 1; i < xy.length; i++) min = Math.min(min, abstandPunktStrecke(q, xy[i - 1], xy[i]));
210	    }
211	  }
212	  return min;
213	}
214	
215	/** Kürzester Abstand in m zwischen zwei Polygonen (Näherung über Stützpunkte beider Seiten; 0 bei Überlappung) */
216	export function abstandPolygonPolygonM(g1, g2) {
217	  let min = Infinity;
218	  for (const poly of ringe(g1)) for (const pt of poly[0]) {
219	    min = Math.min(min, abstandPunktPolygonM(pt, g2));
220	    if (min === 0) return 0;
221	  }
222	  for (const poly of ringe(g2)) for (const pt of poly[0]) {
223	    min = Math.min(min, abstandPunktPolygonM(pt, g1));
224	    if (min === 0) return 0;
225	  }
226	  return min;
227	}
