229	/** Anteil (0–1) der Stützpunkte von g1, die in g2 liegen – grobe Überdeckungsschätzung für die Demo */
230	export function ueberdeckung(g1, g2) {
231	  const pkt = ringe(g1).flatMap((poly) => poly[0].slice(0, -1));
232	  const s = schwerpunkt(g1);
233	  if (s) pkt.push(s);
234	  if (!pkt.length) return 0;
235	  return pkt.filter((q) => punktInPolygon(q, g2)).length / pkt.length;
236	}
