238	/** Kreis als Polygon (für Radien/Zonen), `m` Radius in Metern */
239	export function kreis(mitte, m, schritte = 48) {
240	  const kx = Math.cos(mitte[1] * RAD) * ERDRADIUS_M * RAD;
241	  const ky = ERDRADIUS_M * RAD;
242	  const ring = [];
243	  for (let i = 0; i <= schritte; i++) {
244	    const w = (i / schritte) * 2 * Math.PI;
245	    ring.push([mitte[0] + (Math.cos(w) * m) / kx, mitte[1] + (Math.sin(w) * m) / ky]);
246	  }
247	  return { type: "Polygon", coordinates: [ring] };
248	}
