250	/** BBox-Text "minLon,minLat,maxLon,maxLat" prüfen (Österreich/DACH-Grenzen, max. Ausdehnung) */
251	export function bboxLesen(text, { maxGrad = 3 } = {}) {
252	  if (!text) return null;
253	  const z = String(text).split(",").map(Number);
254	  if (z.length !== 4 || z.some((x) => !Number.isFinite(x))) return null;
255	  const [a, b, c, d] = z;
256	  if (a >= c || b >= d || a < 4 || c > 18 || b < 44 || d > 56) return null;
257	  if (c - a > maxGrad || d - b > maxGrad) return null;
258	  return z;
259	}
