263	/** Kürzester Abstand in m zwischen Punkt [lon, lat] und LineString/MultiLineString */
264	export function abstandPunktLinieM(pt, linie) {
265	  if (!linie?.coordinates) return Infinity;
266	  const teile = linie.type === "MultiLineString" ? linie.coordinates : [linie.coordinates];
267	  const p = projektor(pt);
268	  const q = p(pt);
269	  let min = Infinity;
270	  for (const t of teile) {
271	    const xy = t.map(p);
272	    for (let i = 1; i < xy.length; i++) min = Math.min(min, abstandPunktStrecke(q, xy[i - 1], xy[i]));
273	  }
274	  return min;
275	}
