277	/** Stichprobenpunkte einer Fläche: Stützpunkte, Kantenmitten und Schwerpunkt (für Flächenanteile in Korridoren) */
278	export function stichproben(geometrie) {
279	  const pkt = [];
280	  for (const poly of ringe(geometrie)) {
281	    const r = poly[0] || [];
282	    for (let i = 1; i < r.length; i++) pkt.push(r[i - 1], [(r[i - 1][0] + r[i][0]) / 2, (r[i - 1][1] + r[i][1]) / 2]);
283	  }
284	  const s = schwerpunkt(geometrie);
285	  if (s) pkt.push(s, s); // Schwerpunkt doppelt gewichtet
286	  return pkt;
287	}

