172	 * Widmungslage je Bundesland. `lage` = { bundesland, uwAbstandKm (nächstes UW ≥ 110 kV), zoneAbstandM (nächste
173	 * verordnete Zone; 0 = innerhalb; null = keine Zonendaten) }. Liefert { status: zone|angrenzend|ausserhalb|unklar, text }.
174	 */
175	export function widmungslage({ bundesland, uwAbstandKm = null, zoneAbstandM = null, land = null, privilegiertAnteil = null, eignungAnteil = null } = {}) {
176	  const regel = WIDMUNG[bundesland] || (land && land !== "AT" ? WIDMUNG[`_${land}`] : null);
177	  if (!regel) return { status: "unklar", text: "Keine Widmungsregel hinterlegt – Einzelfallprüfung.", regel: null };
178	  if (regel.art === "baugb") {
179	    // § 35 Abs. 1 Nr. 8 lit. b BauGB: privilegiert auf Flächen längs Autobahnen bzw. zweigleisiger Schienenwege des übergeordneten Netzes bis 200 m
180	    const p = Number(privilegiertAnteil) || 0;
181	    if (p >= 0.5) return { status: "zone", text: `Privilegiert nach § 35 Abs. 1 Nr. 8 lit. b BauGB (${Math.round(p * 100)} % im 200-m-Streifen an Autobahn bzw. zweigleisiger Hauptbahn) – kein Bebauungsplan zwingend, öffentliche Belange und Gemeinde dennoch einbinden. ${regel.text}`, regel };
182	    if (p > 0) return { status: "angrenzend", text: `Teilweise privilegiert (${Math.round(p * 100)} % im 200-m-Streifen) – übrige Fläche über Bebauungsplan. ${regel.text}`, regel };
183	    return { status: "unklar", text: `Bebauungsplan nötig. ${regel.text}`, regel };
184	  }
185	  if (regel.art === "richtplan") {
186	    const e = Number(eignungAnteil) || 0;
187	    if (e >= 0.5) return { status: "zone", text: `Im kantonalen Eignungsgebiet (${Math.round(e * 100)} %). ${regel.text}`, regel };
188	    if (e > 0) return { status: "angrenzend", text: `Teilweise im Eignungsgebiet (${Math.round(e * 100)} %). ${regel.text}`, regel };
189	    return { status: "unklar", text: regel.text, regel };
190	  }
191	  if (regel.art === "uw_radius") {
192	    if (uwAbstandKm == null) return { status: "unklar", text: regel.text, regel };
193	    if (uwAbstandKm <= regel.zoneKm) return { status: "zone", text: `Priorität 1 (≤ ${regel.zoneKm} km zum Umspannwerk). ${regel.text}`, regel };
194	    if (uwAbstandKm <= regel.angrenzendKm) return { status: "angrenzend", text: `Priorität 2 (≤ ${String(regel.angrenzendKm).replace(".", ",")} km zum Umspannwerk). ${regel.text}`, regel };
195	    return { status: "ausserhalb", text: `Außerhalb der Prioritätsradien. ${regel.text}`, regel };
196	  }
197	  if (regel.art === "zonen") {
198	    if (zoneAbstandM == null) return { status: "unklar", text: `Zonendaten nicht geladen. ${regel.text}`, regel };
199	    if (zoneAbstandM <= 0) return { status: "zone", text: `Innerhalb einer verordneten Zone. ${regel.text}`, regel };
200	    if (regel.angrenzendM && zoneAbstandM <= regel.angrenzendM) return { status: "angrenzend", text: `Angrenzend an eine Zone (${Math.round(zoneAbstandM)} m). ${regel.text}`, regel };
201	    return { status: "ausserhalb", text: `Außerhalb der Zonen. ${regel.text}`, regel };
202	  }
203	  return { status: "unklar", text: regel.text, regel };
204	}
