206	const SUED = ["S", "SO", "SW", "eben"];
207	
208	/**
209	 * Punktwert einer Kandidatenfläche.
210	 * m = {
211	 *   ha, kompaktheit (0–1), neigungGrad, exposition (N|NO|O|SO|S|SW|W|NW|eben), nutzung: { acker, gruenland, sonstige } in ha,
212	 *   schutz: [{ art, anteil (0–1), abstandM }], siedlungAbstandM,
213	 *   netz: { knoten: { art, kapazitaet }, luftlinieM, trasseM, kosten: { anteil, … } } | null,
214	 *   widmung: { status, text, regel }, bundesland, land
215	 * }
216	 * Liefert { score, ampel, ko[], kriterien[{ id, label, punkte, max, text, art }], mwp }.
217	 */
218	export function bewerte(m) {
219	  const k = [];
220	  const ko = [];
221	  const add = (id, label, punkte, max, text, art = punkte >= max * 0.66 ? "plus" : punkte > 0 ? "neutral" : "minus") => k.push({ id, label, punkte: r1(punkte), max, text, art });
222	  const ha = Number(m.ha) || 0;
223	  const mwp = mwpFuer(ha);
224	  const land = GEWICHTE_LAND[m.land] ? m.land : "AT";
225	  const L = GEWICHTE_LAND[land];
226	  const sk = (id, p) => (L === GEWICHTE ? p : p * (L[id] / GEWICHTE[id])); // Grundpunkte → Landesgewicht
227	
228	  // Größe
229	  let pg;
230	  if (ha < SCHWELLEN.mindestHa) pg = 0;
231	  else if (ha < 3) pg = 6;
232	  else if (ha < SCHWELLEN.idealHa[0]) pg = 6 + ((ha - 3) / 2) * 8;
233	  else if (ha <= SCHWELLEN.idealHa[1]) pg = 20;
234	  else pg = 16;
235	  if (ha < SCHWELLEN.mindestHa) ko.push({ id: "groesse", text: `Unter ${SCHWELLEN.mindestHa} ha – für Freiflächen-PV meist unwirtschaftlich.`, deckel: 25 });
236	  add("groesse", "Größe", sk("groesse", pg), L.groesse, `${r1(ha).toLocaleString("de-DE")} ha${ha > 50 ? " – sehr groß (UVP-Schwelle und Netzkapazität prüfen)" : ha >= 5 ? " – ideale Größe" : ""}`);
237	
238	  // Form
239	  const kp = clamp(Number(m.kompaktheit) || 0);
240	  const pf = clamp((kp - 0.45) / 0.45) * GEWICHTE.form;
241	  add("form", "Form/Kompaktheit", sk("form", pf), L.form, kp >= 0.85 ? "kompakt, gut belegbar" : kp >= 0.65 ? "brauchbare Form" : "zerklüftet oder schmal – Belegung eingeschränkt");
242	
243	  // Neigung/Exposition
244	  const n = Math.max(0, Number(m.neigungGrad) || 0);
245	  const exp = m.exposition || "eben";
246	  const sued = SUED.includes(exp) || n <= 2;
247	  let pn;
248	  if (n <= 3) pn = 12;
249	  else if (n <= 7) pn = sued ? 10 : 6;
250	  else if (n <= 12) pn = sued ? 6 : 1;
251	  else pn = sued ? 2 : 0;
252	  if (n > SCHWELLEN.maxNeigungGrad) ko.push({ id: "neigung", text: `Mittlere Neigung ${r1(n)}° – zu steil für wirtschaftliche Aufständerung.`, deckel: 20 });
253	  add("neigung", "Neigung/Exposition", sk("neigung", pn), L.neigung, `${r1(n).toLocaleString("de-DE")}° im Mittel, ${exp === "eben" ? "eben" : `Exposition ${exp}`}`);
254	
255	  // Nutzung
256	  const nu = m.nutzung || {};
257	  const summe = (nu.acker || 0) + (nu.gruenland || 0) + (nu.sonstige || 0) || 1;
258	  const pn2 = ((nu.acker || 0) * 8 + (nu.gruenland || 0) * 7 + (nu.sonstige || 0) * 3) / summe;
259	  const hauptnutzung = (nu.acker || 0) >= (nu.gruenland || 0) ? "Acker" : "Grünland";
260	  const nutzungHinweis = { AT: "EAG-Abschlag 25 % auf Agrarflächen beachten", DE: "EEG: Agri-PV (DIN SPEC 91434) im besonderen Solarsegment auch außerhalb der Kulisse", CH: "Fruchtfolgeflächen nur mit Interessenabwägung" }[land];
261	  add("nutzung", "Nutzung", sk("nutzung", pn2), L.nutzung, `${hauptnutzung}${nu.acker && nu.gruenland ? " (gemischt)" : ""} – Agri-PV ${hauptnutzung === "Acker" ? "als Option" : "mit Beweidung möglich"}; ${nutzungHinweis}`);
262	
263	  // Schutzgebiete
264	  for (const s of m.schutz || []) {
265	    const def = SCHUTZ_ARTEN[s.art] || SCHUTZ_ARTEN.sonstig;
266	    const anteil = clamp(Number(s.anteil) || 0);
267	    if (anteil > 0.05 && def.kern) {
268	      ko.push({ id: `schutz_${s.art}`, text: `${Math.round(anteil * 100)} % im ${def.label}${s.name ? ` „${s.name}“` : ""} – in der Regel ausgeschlossen.`, deckel: 15 });
269	      add(`schutz_${s.art}`, def.label, -10, 0, `überdeckt ${Math.round(anteil * 100)} %${s.name ? ` (${s.name})` : ""}`, "ko");
270	    } else if (anteil > 0.05) {
271	      add(`schutz_${s.art}`, def.label, -def.abzug * Math.min(1, anteil * 2), 0, `überdeckt ${Math.round(anteil * 100)} %${s.name ? ` (${s.name})` : ""} – Bewilligung erschwert`, "minus");
272	    } else if ((s.abstandM == null ? Infinity : Number(s.abstandM)) <= 200 && def.abzugNah) {
273	      add(`schutz_${s.art}`, `Nähe ${def.label}`, -def.abzugNah, 0, `${Math.round(s.abstandM)} m entfernt${s.name ? ` (${s.name})` : ""} – Verträglichkeitsprüfung wahrscheinlich`, "minus");
274	    }
275	  }
276	
277	  // Siedlungsabstand
278	  const sa = m.siedlungAbstandM == null ? null : Number(m.siedlungAbstandM);
279	  const [sMin, sVoll] = SCHWELLEN.siedlungAbstandM;
280	  const ps = sa == null ? 4 : sa < sMin ? 0 : sa >= sVoll ? 8 : 4 + ((sa - sMin) / (sVoll - sMin)) * 4;
281	  add("siedlung", "Abstand Siedlung", sk("siedlung", ps), L.siedlung, sa == null ? "unbekannt" : `${Math.round(sa).toLocaleString("de-DE")} m zur nächsten Siedlung${sa < sMin ? " – Blendung/Akzeptanz kritisch" : ""}`);
282	
283	  // Netz: Trassenlänge
284	  const netz = m.netz;
285	  if (netz) {
286	    const km = netz.trasseM / 1000;
287	    const pnetz = km <= 1 ? 22 : km <= 3 ? 22 - ((km - 1) / 2) * 4 : km <= 5 ? 18 - ((km - 3) / 2) * 5 : km <= 8 ? 13 - ((km - 5) / 3) * 6 : km <= 12 ? 7 - ((km - 8) / 4) * 4 : Math.max(0, 3 - (km - 12) / 4);
288	    const kn = netz.knoten || {};
289	    add("netz", "Netzanschluss (Trasse)", sk("netz", pnetz), L.netz, `${r1(km).toLocaleString("de-DE")} km geschätzte Trasse (Luftlinie ${r1(netz.luftlinieM / 1000).toLocaleString("de-DE")} km) zu ${kn.name || KNOTEN_ARTEN[kn.art]?.kurz || "Netzknoten"}`);
290	    if (kn.kapazitaet === "knapp") add("kapazitaet", "Netzkapazität", -8, 0, "Kapazität laut Netzbetreiber knapp – Ausbau/Wartezeit wahrscheinlich", "minus");
291	    else if (kn.kapazitaet === "frei") add("kapazitaet", "Netzkapazität", 3, 0, "freie Einspeisekapazität veröffentlicht", "plus");
292	    const anteil = netz.kosten?.anteil ?? 1;
293	    const pk = anteil < 0.08 ? 8 : anteil < 0.15 ? 8 - ((anteil - 0.08) / 0.07) * 3 : anteil < 0.25 ? 5 - ((anteil - 0.15) / 0.1) * 3 : Math.max(0, 2 - (anteil - 0.25) * 10);
294	    add("kosten", "Netzanschlusskosten", sk("kosten", pk), L.kosten, `≈ ${Math.round(anteil * 100)} % der Anlagenkosten (${Math.round((netz.kosten?.proKwp || 0))} €/kWp)`);
295	  } else {
296	    add("netz", "Netzanschluss (Trasse)", 0, L.netz, `kein geeigneter Netzknoten im Umkreis von ${TRASSE.suchradiusKm} km`, "minus");
297	    add("kosten", "Netzanschlusskosten", 0, L.kosten, "nicht bestimmbar", "minus");
298	  }
299	
300	  // Widmung
301	  const w = m.widmung || { status: "unklar" };
302	  const pw = { zone: 10, angrenzend: 6, unklar: 4, ausserhalb: 2 }[w.status] ?? 4;
303	  const widmungText = {
304	    AT: { zone: "in Zone/Priorität 1", angrenzend: "angrenzend/Priorität 2", ausserhalb: "außerhalb der Zonen", unklar: "Einzelfallprüfung" },
305	    DE: { zone: "privilegiert (§ 35 BauGB, 200-m-Streifen)", angrenzend: "teilweise privilegiert", ausserhalb: "außerhalb", unklar: "Bebauungsplan der Gemeinde nötig" },
306	    CH: { zone: "im kantonalen Eignungsgebiet", angrenzend: "teilweise im Eignungsgebiet", ausserhalb: "ausserhalb", unklar: "Ausnahmebewilligung/Richtplan – Einzelfall" },
307	  }[land];
308	  add("widmung", land === "DE" ? "Planungsrecht (BauGB)" : land === "CH" ? "Raumplanung (Kanton)" : "Widmungslage", sk("widmung", pw), L.widmung, widmungText[w.status] || widmungText.unklar);
309	  const regel = w.regel || WIDMUNG[m.bundesland] || (land !== "AT" ? WIDMUNG[`_${land}`] : null);
310	  if (regel?.maxHaAusserhalb !== undefined && w.status !== "zone" && ha > regel.maxHaAusserhalb) {
311	    ko.push({ id: "widmung", text: regel.maxHaAusserhalb > 0 ? `Außerhalb der Zonen nur bis ${regel.maxHaAusserhalb} ha widmungsfähig.` : "Außerhalb der Eignungszonen nicht zulässig.", deckel: regel.maxHaAusserhalb > 0 ? 45 : 20 });
312	  }
313	  if (regel?.maxHa && ha > regel.maxHa) add("widmung_max", "Widmungsgrenze", -3, 0, `je Widmung höchstens ${regel.maxHa} ha – Teilfläche oder Ausnahme`, "minus");
314	
315	  // Flächenkulisse (DE: EEG-Förderkulisse, CH: kantonale Eignung) – großer Pluspunkt, fehlt sie: kein EEG-Freiflächengebot
316	  const ku = m.kulisse || {};
317	  if (land === "DE") {
318	    const f = KULISSE.DE.faktor;
319	    const teile = [
320	      ["konversion", clamp(Number(ku.konversionAnteil) || 0), "Konversionsfläche"],
321	      ["randstreifen", clamp(Number(ku.randstreifenAnteil) || 0), "Randstreifen 500 m (Autobahn/Schiene)"],
322	      ["benachteiligt", clamp(Number(ku.benachteiligtAnteil) || 0), "benachteiligtes Gebiet"],
323	      ["moor", clamp(Number(ku.moorAnteil) || 0), "Moorboden (nur mit Wiedervernässung)"],
324	    ];
325	    let best = 0;
326	    for (const [id, a] of teile) best = Math.max(best, a * f[id]);
327	    const namen = teile.filter((t) => t[1] > 0).map((t) => `${t[2]} ${Math.round(t[1] * 100)} %`);
328	    add("kulisse", "EEG-Flächenkulisse", best * L.kulisse, L.kulisse, namen.length ? `${namen.join(" · ")} – förderfähig im Freiflächen-Segment (§ 37 EEG)` : "keine EEG-Flächenkulisse – nur Agri-PV (besonderes Solarsegment) oder Vermarktung ohne EEG (PPA)", best > 0 ? undefined : "minus");
329	  } else if (land === "CH") {
330	    const e = clamp(Number(ku.eignungAnteil) || 0);
331	    const vb = ku.vorbelastet ? 1 : 0;
332	    const best = Math.max(e * KULISSE.CH.faktor.eignung, vb * KULISSE.CH.faktor.vorbelastet);
333	    add("kulisse", "Eignung (Richtplan)", best * L.kulisse, L.kulisse, e > 0 ? `kantonales Eignungsgebiet ${Math.round(e * 100)} %` : vb ? "vorbelasteter Standort (Verkehrs-/Infrastrukturanlage)" : "kein Eignungsgebiet – Standortgebundenheit schwer nachweisbar", best > 0 ? undefined : "minus");
334	    const fff = clamp(Number(ku.fffAnteil) || 0);
335	    if (fff > 0.05) add("fff", "Fruchtfolgefläche", -KULISSE.CH.fffAbzug * fff, 0, `${Math.round(fff * 100)} % Fruchtfolgefläche (Sachplan FFF) – Kompensation bzw. Interessenabwägung nötig`, "minus");
336	  }
337	
338	  // Einstrahlung
339	  const ertrag = ERTRAG[m.bundesland] || ERTRAG[`_${land}`] || ERTRAG._AT;
340	  const pe = clamp((ertrag - 1000) / 200) * GEWICHTE.einstrahlung;
341	  add("einstrahlung", "Einstrahlung", sk("einstrahlung", pe), L.einstrahlung, `≈ ${ertrag.toLocaleString("de-DE")} kWh/kWp und Jahr`);
342	
343	  let score = k.reduce((s, x) => s + x.punkte, 0);
344	  score = Math.max(0, Math.min(100, score));
345	  for (const x of ko) score = Math.min(score, x.deckel);
346	  score = Math.round(score);
347	  const ampel = score >= SCHWELLEN.ampel.gruen ? "gruen" : score >= SCHWELLEN.ampel.gelb ? "gelb" : "rot";
348	  return { score, ampel, ko, kriterien: k, mwp, ertragKwhProKwp: ertrag };
349	}
