 10	import { abstandPolygonPolygonM, abstandPunktLinieM, abstandPunktPolygonM, bbox, bboxSchneidet, distanzM, flaecheM2, kompaktheit, schwerpunkt, stichproben, ueberdeckung } from "./geo.js";
 11	import { KULISSE, besterKnoten, bewerte, kennzahlen, mwpFuer, naechsterKnoten, netzkosten, prioritaet, widmungslage } from "./scoring.js";
 12	
 13	const GEEIGNET = ["acker", "gruenland"];
 14	const NACHBAR_M = 3; // Parzellen mit weniger als 3 m Abstand gelten als zusammenhängend (Feldweg-Grenzen ausgenommen)
 15	
 16	function erweitert(b, m) {
 17	  const dLat = m / 111320;
 18	  const dLon = m / (111320 * Math.cos(((b[1] + b[3]) / 2) * (Math.PI / 180)));
 19	  return [b[0] - dLon, b[1] - dLat, b[2] + dLon, b[3] + dLat];
 20	}
 21	
 22	const mehrheit = (werte) => {
 23	  const z = new Map();
 24	  for (const [w, g] of werte) z.set(w, (z.get(w) || 0) + g);
 25	  return [...z.entries()].sort((a, b) => b[1] - a[1])[0]?.[0] ?? "";
 26	};
