 28	/** Zusammenhängende Verbünde (Union-Find über Nachbarschaft) */
 29	export function verbuende(parzellen) {
 30	  const n = parzellen.length;
 31	  const eltern = parzellen.map((_, i) => i);
 32	  const wurzel = (i) => (eltern[i] === i ? i : (eltern[i] = wurzel(eltern[i])));
 33	  const boxen = parzellen.map((p) => erweitert(bbox(p.geometry), NACHBAR_M));
 34	  for (let i = 0; i < n; i++) {
 35	    for (let j = i + 1; j < n; j++) {
 36	      if (!bboxSchneidet(boxen[i], boxen[j])) continue;
 37	      if (abstandPolygonPolygonM(parzellen[i].geometry, parzellen[j].geometry) <= NACHBAR_M) eltern[wurzel(i)] = wurzel(j);
 38	    }
 39	  }
 40	  const gruppen = new Map();
 41	  parzellen.forEach((p, i) => {
 42	    const w = wurzel(i);
 43	    if (!gruppen.has(w)) gruppen.set(w, []);
 44	    gruppen.get(w).push(p);
 45	  });
 46	  return [...gruppen.values()];
 47	}
