 49	/** Knoten-Feature → flaches Objekt */
 50	export const knotenFlach = (f) => ({ ...f.properties, lon: f.geometry.coordinates[0], lat: f.geometry.coordinates[1] });
 51	
 52	const r2 = (x) => Math.round(x * 100) / 100;
 53	
 54	/**
 55	 * Flächenkulisse eines Verbunds (Ausbaustufe A1b, Deutschland/Schweiz). Liefert Anteile 0–1 (flächengewichtet):
 56	 *  - randstreifenAnteil: Stichproben ≤ 500 m zu Autobahn oder Schienenweg (§ 37 Abs. 1 Nr. 2 lit. c EEG – ohne Gleiszahl)
 57	 *  - privilegiertAnteil: ≤ 200 m zu Autobahn oder Hauptbahn mit mind. zwei Hauptgleisen (§ 35 Abs. 1 Nr. 8 lit. b BauGB)
 58	 *  - benachteiligtAnteil, moorAnteil, konversionAnteil (DE) bzw. eignungAnteil, fffAnteil, vorbelastet (CH) aus den
 59	 *    Flurstücks-Eigenschaften `kulisse` (im Dienst per Verschneidung mit den Kulissen-Polygonen, in der Demo synthetisch)
 60	 * Abstände zur OSM-Mittellinie statt zum äußeren Fahrbahnrand → der Korridor wird leicht UNTERschätzt (konservativ).
 61	 */
 62	export function kulisseFuer(gruppe, flaechen, land, verkehr = [], verkehrBoxen = []) {
 63	  if (land !== "DE" && land !== "CH") return null;
 64	  const m2 = flaechen.reduce((s, x) => s + x, 0) || 1;
 65	  const anteil = (merkmal) => gruppe.reduce((s, p, i) => s + ((p.properties.kulisse || []).includes(merkmal) ? flaechen[i] : 0), 0) / m2;
