248	/** Filter auf Kandidatenliste (gleiche Parameter wie die Dienst-API) */
249	export function filtern(liste, { bbox: box, minHa, maxTrasseKm, minScore, land, bundesland, bezirk, gemeinde, ampel, q } = {}) {
250	  let l = liste;
251	  if (land) l = l.filter((k) => k.land === land);
252	  if (box) l = l.filter((k) => bboxSchneidet(k.bbox, box));
253	  if (minHa) l = l.filter((k) => k.ha >= minHa);
254	  if (maxTrasseKm) l = l.filter((k) => k.netz && k.netz.trasseM <= maxTrasseKm * 1000);
255	  if (minScore) l = l.filter((k) => k.score >= minScore);
256	  if (bundesland) l = l.filter((k) => k.bundesland === bundesland);
257	  if (bezirk) l = l.filter((k) => k.bezirk === bezirk);
258	  if (gemeinde) l = l.filter((k) => k.gemeinde === gemeinde);
259	  if (ampel) l = l.filter((k) => k.ampel === ampel);
260	  if (q) {
261	    const s = String(q).toLowerCase();
262	    l = l.filter((k) => [k.id, k.gemeinde, k.bezirk, ...k.kg, ...k.parzellen.map((p) => `${p.kgNr} ${p.gstNr}`)].join(" ").toLowerCase().includes(s));
263	  }
264	  return l;
265	}
