136	// Client des Geodaten-Dienstes (Backend-Import/dienste/geodaten, FastAPI). Nur serverseitig: GEODATEN_URL und
137	// GEODATEN_TOKEN (= DIENST_TOKEN des Dienstes) verlassen nie den Server. Timeout, ein Wiederholungsversuch bei
138	// Netzfehlern/5xx, Konto-ID als X-Plattform-Nutzer für das Zugriffsprotokoll des Dienstes.
139	
140	import { PlattformFehler } from "../fehler";
141	
142	const TIMEOUT_MS = 20000;
143	
144	export const dienstKonfiguriert = () => !!(process.env.GEODATEN_URL && process.env.GEODATEN_TOKEN);
145	
146	async function abruf(pfad, { methode = "GET", body, nutzer } = {}) {
147	  const basis = String(process.env.GEODATEN_URL || "").replace(/\/$/, "");
148	  let letzter;
149	  for (let versuch = 1; versuch <= 2; versuch++) {
150	    const ac = new AbortController();
151	    const t = setTimeout(() => ac.abort(), TIMEOUT_MS);
152	    try {
153	      const res = await fetch(basis + pfad, {
154	        method: methode,
155	        headers: { Authorization: `Bearer ${process.env.GEODATEN_TOKEN}`, Accept: "application/json", ...(body ? { "Content-Type": "application/json" } : {}), ...(nutzer?.id ? { "X-Plattform-Nutzer": nutzer.id } : {}) },
156	        body: body ? JSON.stringify(body) : undefined,
157	        cache: "no-store",
158	        signal: ac.signal,
159	      });
160	      if (res.status === 404) return null;
161	      if (res.status >= 500 && versuch < 2) {
162	        letzter = new Error(`Dienst ${res.status}`);
163	        continue;
164	      }
165	      if (!res.ok) {
166	        const j = await res.json().catch(() => ({}));
167	        throw new PlattformFehler(res.status === 401 ? 502 : res.status, res.status === 401 ? "Geodaten-Dienst: Zugang abgelehnt (Token prüfen)." : `Geodaten-Dienst: ${j.detail || res.status}`);
168	      }
169	      return await res.json();
170	    } catch (e) {
171	      if (e instanceof PlattformFehler) throw e;
172	      letzter = e;
173	    } finally {
174	      clearTimeout(t);
175	    }
176	  }
177	  console.error("[geodaten] Dienst nicht erreichbar:", letzter?.message);
178	  throw new PlattformFehler(503, "Der Geodaten-Dienst ist gerade nicht erreichbar. Bitte später erneut versuchen.");
179	}
