181	const qs = (o) => {
182	  const p = new URLSearchParams();
183	  for (const [k, v] of Object.entries(o)) if (v !== undefined && v !== null && v !== "" && v !== 0 && v !== false) p.set(k, Array.isArray(v) ? v.join(",") : String(v));
184	  const s = p.toString();
185	  return s ? `?${s}` : "";
186	};
