241	/**
242	 * Kampagne aus Kandidatenmenge anlegen.
243	 * quelle: { kandidatIds[] } (Kartenauswahl) | { filter } (Filter der Karte) | { gemeinde, land } – rote Flächen (Score < 45)
244	 * werden bei Filter/Gemeinde ausgelassen, bei expliziter Auswahl übernommen.
245	 */
246	export async function kampagneAnlegen(n, daten = {}) {
247	  let liste = [];
248	  let art = "auswahl";
249	  if (Array.isArray(daten.kandidatIds) && daten.kandidatIds.length) {
250	    const ids = [...new Set(daten.kandidatIds.map((x) => v.text(x, 80)).filter(Boolean))].slice(0, MAX_KAMPAGNE);
251	    for (const id of ids) liste.push(await geo.kandidat(n, id));
252	  } else if (daten.gemeinde) {
253	    art = "gemeinde";
254	    const r = await geo.kandidaten(n, { gemeinde: v.text(daten.gemeinde, 80), land: ["AT", "DE", "CH"].includes(daten.land) ? daten.land : undefined, limit: 2000 });
255	    liste = r.kandidaten.filter((k) => k.score >= 45);
256	  } else if (daten.filter && typeof daten.filter === "object") {
257	    art = "filter";
258	    const f = daten.filter;
259	    const zahl = (x, max) => (Number.isFinite(Number(x)) && Number(x) > 0 ? Math.min(Number(x), max) : undefined);
260	    const filter = { minHa: zahl(f.minHa, 1000), maxTrasseKm: zahl(f.maxTrasseKm, 50), minScore: zahl(f.minScore, 100) ?? 45, land: ["AT", "DE", "CH"].includes(f.land) ? f.land : undefined, bundesland: v.text(f.bundesland, 80) || undefined, bezirk: v.text(f.bezirk, 80) || undefined, gemeinde: v.text(f.gemeinde, 80) || undefined, ampel: ["gruen", "gelb"].includes(f.ampel) ? f.ampel : undefined, limit: 2000 };
261	    const r = await geo.kandidaten(n, filter);
262	    liste = r.kandidaten;
263	    daten = { ...daten, quelleFilter: filter };
264	  } else throw new PlattformFehler(422, "Bitte Flächen auswählen, einen Filter oder eine Gemeinde angeben.");
265	  if (liste.length > MAX_KAMPAGNE) throw new PlattformFehler(422, `Die Auswahl umfasst ${liste.length} Flächen – höchstens ${MAX_KAMPAGNE} je Kampagne. Bitte Filter einschränken.`);
266	  return akquise2Backend().kampagneAnlegen(n, liste.map((k) => kandidatSchlank(k, { geometrie: true })), {
267	    name: daten.name, beschreibung: daten.beschreibung, test: daten.test === true, nachfass: daten.nachfass,
268	    quelle: { art, gemeinde: daten.gemeinde || "", filter: daten.quelleFilter || null },
269	  });
270	}
