 37	function lesen() {
 38	  const pfade = Object.fromEntries(Object.entries(DATEIEN).map(([k, liste]) => [k, liste.map((p) => path.join(process.cwd(), p))]));
 39	  const stempel = Object.values(pfade).flat().map((p) => statSync(p).mtimeMs).join("|");
 40	  if (!roh || roh.stempel !== stempel) {
 41	    const j = (p) => JSON.parse(readFileSync(p, "utf8"));
 42	    // Je Art alle Regionen zusammenführen; metadata der ersten Datei (AT) bleibt für die Quellenliste, alle unter `alle`
 43	    const d = Object.fromEntries(
 44	      Object.entries(pfade).map(([k, liste]) => {
 45	        const fcs = liste.map(j);
 46	        return [k, { type: "FeatureCollection", metadata: fcs[0].metadata, alle: fcs.map((f) => f.metadata || {}), features: fcs.flatMap((f) => f.features) }];
 47	      })
 48	    );
 49	    roh = { stempel, ...d };
 50	    cache = null;
 51	  }
 52	  return roh;
 53	}
