132	/** Ebenen: schutzgebiete (OSM) | zonen (OÖ-Prioritätsradien um Umspannwerke, abgeleitet aus dem Kriterienkatalog) | verkehr (DE) */
133	export function ebene(name, { bbox } = {}) {
134	  const r = lesen();
135	  if (name === "verkehr") {
136	    return { type: "FeatureCollection", features: r.verkehr.features.filter((f) => !bbox || bboxSchneidet(bboxVon(f.geometry), bbox)), hinweis: "Autobahnen und Schienenwege (OSM). EEG-Randstreifen 500 m (§ 37 Abs. 1 Nr. 2 lit. c EEG), Privilegierung 200 m an Autobahn bzw. zweigleisiger Hauptbahn (§ 35 Abs. 1 Nr. 8 lit. b BauGB). Gleiszahl geschätzt." };
137	  }
138	  if (name === "schutzgebiete") {
139	    return { type: "FeatureCollection", features: r.schutz.features.filter((f) => !bbox || bboxSchneidet(bboxVon(f.geometry), bbox)) };
140	  }
141	  if (name === "zonen") {
142	    // Näherung für die Demo: Knoten nördlich 48,0° und östlich 12,75° liegen im Demogebiet in Oberösterreich
143	    const uws = r.knoten.features.filter((f) => ["uw110", "uew"].includes(f.properties.art)).filter((f) => f.geometry.coordinates[1] >= 48.0 && f.geometry.coordinates[0] >= 12.75 && f.geometry.coordinates[0] <= 14.2);
144	    const features = [];
145	    for (const u of uws) {
146	      if (bbox && !bboxSchneidet([u.geometry.coordinates[0] - 0.12, u.geometry.coordinates[1] - 0.08, u.geometry.coordinates[0] + 0.12, u.geometry.coordinates[1] + 0.08], bbox)) continue;
147	      features.push({ type: "Feature", geometry: kreis(u.geometry.coordinates, 7500), properties: { id: `p2-${u.properties.id}`, name: `Priorität 2 – ${u.properties.name || "Umspannwerk"}`, art: "ooe_prioritaet_2", bundesland: "Oberösterreich" } });
148	      features.push({ type: "Feature", geometry: kreis(u.geometry.coordinates, 5000), properties: { id: `p1-${u.properties.id}`, name: `Priorität 1 – ${u.properties.name || "Umspannwerk"}`, art: "ooe_prioritaet_1", bundesland: "Oberösterreich" } });
149	    }
150	    return { type: "FeatureCollection", features, hinweis: "Abgeleitet: OÖ Kriterienkatalog PV-FFA – energiewirtschaftliche Priorität 1 (≤ 5 km) und 2 (≤ 7,5 km) um Umspannwerke. Keine amtliche Zonenkarte." };
151	  }
152	  return null;
153	}
