155	/** Suche: Gemeinde/Ort, KG, Grundstücksnummer (KG-Nr Gst-Nr), Umspannwerk, Kandidaten-ID */
156	export function suche(q, { kapazitaeten } = {}) {
157	  const s = String(q || "").trim().toLowerCase();
158	  if (s.length < 2) return { treffer: [] };
159	  const r = lesen();
160	  const d = daten(kapazitaeten);
161	  const treffer = [];
162	  for (const k of d.kandidaten) {
163	    if (treffer.length >= 6) break;
164	    if (k.id.toLowerCase().includes(s) || k.gemeinde.toLowerCase().includes(s) || k.kg.some((x) => x.toLowerCase().includes(s))) {
165	      treffer.push({ typ: "kandidat", label: `${k.gemeinde} · ${String(k.ha).replace(".", ",")} ha · Score ${k.score}`, kandidatId: k.id, lon: k.schwerpunkt[0], lat: k.schwerpunkt[1] });
166	    }
167	  }
168	  const gst = s.match(/^(\d{4,5})\s*[-/ ]\s*([\d/.]+)$/); // AT: KG-Nr (5-stellig), DE-Demo: Gemarkungsnummer (4-stellig)
169	  for (const p of r.parzellen.features) {
170	    if (treffer.length >= 10) break;
171	    const pr = p.properties;
172	    if ((gst && pr.kgNr === gst[1] && pr.gstNr === gst[2]) || (!gst && `${pr.kgNr} ${pr.gstNr}`.includes(s) && /\d/.test(s))) {
173	      const c = bboxVon(p.geometry);
174	      treffer.push({ typ: "grundstueck", label: `${pr.kg} (${pr.kgNr}), Gst. ${pr.gstNr}`, parzelleId: pr.id, lon: (c[0] + c[2]) / 2, lat: (c[1] + c[3]) / 2 });
175	    }
176	  }
177	  for (const f of d.knoten) {
178	    if (treffer.length >= 14) break;
179	    if (f.properties.art !== "trafo" && f.properties.name && f.properties.name.toLowerCase().includes(s)) {
180	      treffer.push({ typ: "netzknoten", label: `${f.properties.name} (${KNOTEN_ARTEN[f.properties.art].kurz})`, knotenId: f.properties.id, lon: f.geometry.coordinates[0], lat: f.geometry.coordinates[1] });
181	    }
182	  }
183	  for (const o of r.orte.features) {
184	    if (treffer.length >= 20) break;
185	    if (["town", "village", "city"].includes(o.properties.typ) && o.properties.name.toLowerCase().startsWith(s)) {
186	      treffer.push({ typ: "ort", label: o.properties.name, lon: o.geometry.coordinates[0], lat: o.geometry.coordinates[1] });
187	    }
188	  }
189	  return { treffer };
190	}

