125	export function matching(projekt, profil) {
126	  if (!projekt) return { score: 0, gruende: [] };
127	  const p = profil || {};
128	  const gruende = [];
129	  let score = 0;
130	
131	  // Typ
132	  if (!p.typen?.length || p.typen.includes(projekt.typ)) {
133	    score += 25;
134	    if (p.typen?.length) gruende.push(PROJEKT_TYPEN[projekt.typ] || projekt.typ);
135	  }
136	
137	  // Phase – benachbarte Phase gibt halbe Punkte
138	  if (!p.phasen?.length) score += 25;
139	  else if (p.phasen.includes(projekt.phase)) {
140	    score += 25;
141	    gruende.push(PHASEN.find((x) => x.id === projekt.phase)?.kurz || projekt.phase);
142	  } else {
143	    const idx = PHASEN.findIndex((x) => x.id === projekt.phase);
144	    const nah = p.phasen.some((ph) => Math.abs(PHASEN.findIndex((x) => x.id === ph) - idx) === 1);
145	    if (nah) score += 12;
146	  }
147	
148	  // Land
149	  if (!p.laender?.length || p.laender.includes(projekt.land)) {
150	    score += 20;
151	    if (p.laender?.length) gruende.push(LAENDER[projekt.land] || projekt.land);
152	  }
153	
154	  // Größe – bis 25 % außerhalb der Spanne halbe Punkte
155	  const m = Number(projekt.mwp) || 0;
156	  const min = Number(p.mwpMin) || 0;
157	  const max = Number(p.mwpMax) || Infinity;
158	  if (m >= min && m <= max) {
159	    score += 20;
160	    if (p.mwpMin || p.mwpMax) gruende.push("Größe passt");
161	  } else if (m >= min * 0.75 && m <= max * 1.25) score += 10;
162	
163	  // Ticket
164	  const preis = preisGesamt(projekt);
165	  const tMin = Number(p.ticketMin) || 0;
166	  const tMax = Number(p.ticketMax) || Infinity;
167	  if (!p.ticketMin && !p.ticketMax) score += 10;
168	  else if (preis === null) score += 5; // auf Anfrage – offen
169	  else if (preis >= tMin && preis <= tMax) {
170	    score += 10;
171	    gruende.push("Ticket passt");
172	  }
173	
174	  return { score: Math.round(score), gruende };
175	}

