 68	  if (Number.isNaN(d.getTime())) return null;
 69	  while (!istWerktag(d)) {
 70	    d.setUTCDate(d.getUTCDate() + 1);
 71	    d.setUTCHours(7, 0, 0, 0);
 72	  }
 73	  let rest = werktage;
 74	  while (rest > 0) {
 75	    d.setUTCDate(d.getUTCDate() + 1);
 76	    if (istWerktag(d)) rest--;
 77	  }
 78	  return d.toISOString();
 79	}
