 81	/**
 82	 * SLA-Ampel Erstkontakt. `eingangAm` = Eingang (Anfrage bzw. Einreichung), `erstkontaktAm` = erster
 83	 * Kontakt durch das Backoffice (Anruf/E-Mail/Termin im CRM, Nachricht im Thread oder Statuswechsel).
 84	 * Liefert { ampel: gruen|gelb|rot, status: erledigt|verspaetet|offen|faellig|ueberfaellig, fristBis, text }.
 85	 */
 86	export function slaStatus(eingangAm, erstkontaktAm, jetzt = Date.now()) {
 87	  if (!eingangAm) return { ampel: "grau", status: "unbekannt", fristBis: null, text: "Kein Eingang" };
 88	  const frist = werktageSpaeter(eingangAm);
 89	  const fristMs = new Date(frist).getTime();
 90	  const stunden = (a, b) => Math.max(0, Math.round((b - a) / 36e5));
 91	  if (erstkontaktAm) {
 92	    const k = new Date(erstkontaktAm).getTime();
 93	    if (k <= fristMs) return { ampel: "gruen", status: "erledigt", fristBis: frist, erstkontaktAm, text: `Erstkontakt nach ${stunden(new Date(eingangAm).getTime(), k)} h` };
 94	    return { ampel: "gelb", status: "verspaetet", fristBis: frist, erstkontaktAm, text: `Erstkontakt verspätet (${stunden(fristMs, k)} h nach Frist)` };
 95	  }
 96	  if (jetzt > fristMs) return { ampel: "rot", status: "ueberfaellig", fristBis: frist, text: `Erstkontakt überfällig seit ${stunden(fristMs, jetzt)} h` };
 97	  if (fristMs - jetzt < 24 * 36e5) return { ampel: "gelb", status: "faellig", fristBis: frist, text: `Erstkontakt fällig in ${stunden(jetzt, fristMs)} h` };
 98	  return { ampel: "gruen", status: "offen", fristBis: frist, text: `Frist läuft (${stunden(jetzt, fristMs)} h)` };
 99	}
