103	/** PLZ passt zu einem Eintrag wie "80-87", "9", "5020" (Präfix bzw. Präfix-Bereich) */
104	export function plzPasst(plz, muster) {
105	  const p = String(plz || "").replace(/\D/g, "");
106	  const m = String(muster || "").replace(/\s/g, "");
107	  if (!p || !m) return false;
108	  const bereich = m.match(/^(\d{1,5})-(\d{1,5})$/);
109	  if (bereich) {
110	    const [von, bis] = [bereich[1], bereich[2]];
111	    const len = Math.max(von.length, bis.length);
112	    const kopf = Number(p.slice(0, len));
113	    return p.length >= len && kopf >= Number(von.padEnd(len, "0")) && kopf <= Number(bis.padEnd(len, "9"));
114	  }
115	  return /^\d{1,5}$/.test(m) && p.startsWith(m);
116	}
