118	/** Bestes Gebiet für ein Objekt: PLZ (3) vor Bundesland (2) vor Land (1). Liefert { gebiet, grund } oder null */
119	export function gebietFuer(gebiete = [], { land, bundesland, plz }) {
120	  let best = null;
121	  for (const g of gebiete) {
122	    if (g.aktiv === false || !g.mitarbeiterId) continue;
123	    if (g.land && land && g.land !== land) continue;
124	    let punkte = 0;
125	    let grund = "";
126	    if ((g.plz || []).some((m) => plzPasst(plz, m))) {
127	      punkte = 3;
128	      grund = `PLZ ${plz}`;
129	    } else if ((g.bundeslaender || []).includes(bundesland)) {
130	      punkte = 2;
131	      grund = bundesland;
132	    } else if (g.land && g.land === land && !(g.plz || []).length && !(g.bundeslaender || []).length) {
133	      punkte = 1;
134	      grund = `Land ${land}`;
135	    }
136	    if (punkte && (!best || punkte > best.punkte)) best = { gebiet: g, punkte, grund };
137	  }
138	  return best;
139	}
