201	export async function akquise(n, { land, prioritaet, sla, zustaendigId, status, q, alle = false } = {}) {
202	  rechtNoetig(n, "akquise", 1);
203	  await fristenBeiBedarf();
204	  const db = await boLesen();
205	  let liste = db.flaechen.filter((f) => alle || OFFEN.includes(f.status)).map((f) => zeile(db, f));
206	  const alleZeilen = liste;
207	  if (land) liste = liste.filter((z) => z.land === land);
208	  if (prioritaet) liste = liste.filter((z) => z.prioritaet === prioritaet);
209	  if (sla) liste = liste.filter((z) => z.sla.ampel === sla);
210	  if (zustaendigId === "ohne") liste = liste.filter((z) => !z.zustaendig);
211	  else if (zustaendigId) liste = liste.filter((z) => z.zustaendig?.id === zustaendigId);
212	  if (status) liste = liste.filter((z) => z.status === status);
213	  if (q) {
214	    const s = String(q).toLowerCase();
215	    liste = liste.filter((z) => [z.id, z.bezeichnung, z.ort, z.plz, z.bundesland, z.kontakt?.name, z.kontakt?.email, z.tags.join(" ")].join(" ").toLowerCase().includes(s));
216	  }
217	  liste.sort((a, b) => PRIO_RANG[a.prioritaet] - PRIO_RANG[b.prioritaet] || SLA_RANG[a.sla.ampel] - SLA_RANG[b.sla.ampel] || b.score - a.score);
218	  const summe = (l, f) => Math.round(l.reduce((s, z) => s + (Number(z[f]) || 0), 0) * 10) / 10;
219	  return {
220	    flaechen: liste,
221	    kennzahlen: {
222	      anzahl: alleZeilen.length,
223	      ha: summe(alleZeilen, "ha"),
224	      mwp: summe(alleZeilen, "mwp"),
225	      slaRot: alleZeilen.filter((z) => z.sla.ampel === "rot").length,
226	      slaGelb: alleZeilen.filter((z) => z.sla.ampel === "gelb").length,
227	      ohneZustaendig: alleZeilen.filter((z) => !z.zustaendig).length,
228	      prioA: alleZeilen.filter((z) => z.prioritaet === "A").length,
229	      scoreMittel: alleZeilen.length ? Math.round(alleZeilen.reduce((s, z) => s + z.score, 0) / alleZeilen.length) : 0,
230	    },
231	    konten: db.nutzer.filter((u) => u.aktiv && u.rollen.includes("admin")).map(kurzKonto),
232	    gebiete: db.bo.gebiete.map((g) => ({ ...g, mitarbeiter: kurzKonto(nutzerVon(db, g.mitarbeiterId)) })),
233	  };
234	}
