293	/** Massen-Zuweisung: nach Gebiet oder an eine Person. Vorgang zur Fläche erhält dieselbe Person, wenn frei. */
294	export async function akquiseZuweisen(n, { ids = [], modus = "gebiet", zustaendigId, ueberschreiben = false } = {}) {
295	  rechtNoetig(n, "akquise", 2);
296	  rechtNoetig(n, "flaechen", 2);
297	  return boAendern((db) => {
298	    const liste = (Array.isArray(ids) ? ids : []).map(v.kennung).filter(Boolean).slice(0, 500);
299	    v.pflicht(liste.length, "Bitte Flächen auswählen.");
300	    if (modus !== "gebiet") {
301	      const u = nutzerVon(db, zustaendigId);
302	      v.pflicht(u && u.aktiv && u.rollen.includes("admin"), "Zuständig kann nur ein aktives Backoffice-Konto sein.");
303	    }
304	    const ergebnis = { zugewiesen: 0, uebersprungen: 0, ohneGebiet: 0 };
305	    for (const id of liste) {
306	      const f = objektVon(db, "flaeche", id);
307	      if (!f) continue;
308	      if (f.zustaendigId && !ueberschreiben) {
309	        ergebnis.uebersprungen++;
310	        continue;
311	      }
312	      let ziel = zustaendigId;
313	      let grund = "manuell";
314	      if (modus === "gebiet") {
315	        const g = gebietFuer(db.bo.gebiete, { land: f.land, bundesland: f.bundesland, plz: f.plz });
316	        if (!g) {
317	          ergebnis.ohneGebiet++;
318	          continue;
319	        }
320	        ziel = g.gebiet.mitarbeiterId;
321	        grund = `Gebiet „${g.gebiet.name}“`;
322	      }
323	      f.zustaendigId = ziel;
324	      f.geaendertAm = jetzt();
325	      const vg = f.vorgangId ? objektVon(db, "vorgang", f.vorgangId) : null;
326	      if (vg && (!vg.zustaendigId || ueberschreiben)) vg.zustaendigId = ziel;
327	      W.protokoll(db, n, "zuweisen", "flaeche", f.id, `Zuständig: ${nameVon(db, ziel)} (${grund})`);
328	      ergebnis.zugewiesen++;
329	    }
330	    return ergebnis;
331	  });
332	}

