 73	    .map((s, i) => ({ id: /^s\d$/.test(s?.id) ? s.id : `s${i + 1}`, art: NACHFASS_ARTEN[s?.art] ? s.art : null, nachTagen: Math.max(7, Math.min(180, Math.round(Number(s?.nachTagen) || 28))), aktiv: s?.aktiv !== false }))
 74	    .filter((s) => s.art);
 75	}
