 77	// ---------------------------------------------------------------- Einmalcode
 78	
 79	const CODE_ALPHABET = "23456789ABCDEFGHJKLMNPQRSTUVWXYZ"; // ohne 0/O/1/I
 80	export const CODE_LAENGE = 10; // 32^10 ≈ 1,1 · 10^15 (50 Bit) – zusätzlich Rate-Limit je IP
 81	
 82	/** Zufälliger Einmalcode (Web Crypto – Browser und Node ≥ 19) */
 83	export function codeErzeugen(zufall = globalThis.crypto) {
 84	  const b = new Uint8Array(CODE_LAENGE);
 85	  zufall.getRandomValues(b);
 86	  let s = "";
 87	  for (let i = 0; i < CODE_LAENGE; i++) s += CODE_ALPHABET[b[i] % CODE_ALPHABET.length];
 88	  return s;
 89	}
 90	
 91	/** Eingabe normalisieren (Groß, ohne Leer-/Bindestriche, 0→O? nein: ungültige Zeichen → ungültig) */
 92	export function codeNormalisieren(s) {
 93	  const c = String(s || "").toUpperCase().replace(/[\s-]/g, "");
 94	  return c.length === CODE_LAENGE && [...c].every((z) => CODE_ALPHABET.includes(z)) ? c : "";
 95	}
 96	
 97	/** Druckform „ABCDE-FGHJK“ */
 98	export const codeLesbar = (c) => (c ? `${c.slice(0, 5)}-${c.slice(5)}` : "");
 99	
100	// ---------------------------------------------------------------- Sperrliste (Schlüssel, ohne Klartext zu speichern)
101	
102	export function normText(s) {
103	  return String(s || "")
104	    .toLowerCase()
105	    .replace(/ä/g, "ae")
106	    .replace(/ö/g, "oe")
107	    .replace(/ü/g, "ue")
108	    .replace(/ß/g, "ss")
109	    .normalize("NFKD")
110	    .replace(/[̀-ͯ]/g, "")
111	    .replace(/\b(str\.|strasse)\b/g, "str")
112	    .replace(/[^a-z0-9]+/g, " ")
113	    .trim();
114	}
115	
116	/**
117	 * Personen-Schlüssel (vor dem Hashen): Name bzw. Firma + PLZ. Die Straße zählt bewusst NICHT (Schreibweisen „Str.“/
118	 * „Straße 5a“ …) – lieber einmal zu viel gesperrt als ein Widerspruch übersehen. Gleiche Person → gleicher Schlüssel.
119	 */
120	export function personSchluessel({ vorname = "", nachname = "", firma = "", plz = "" } = {}) {
121	  const name = firma && !nachname ? normText(firma) : `${normText(nachname)}|${normText(vorname)}`;
122	  return `p|${name}|${String(plz || "").replace(/\s/g, "").toUpperCase()}`;
123	}
124	
125	/** Flurstücks-Schlüssel (Land, Gemarkung/KG-Nummer, Flurstücks-/Grundstücksnummer) */
126	export const flurstueckSchluessel = (land, kgNr, gstNr) => `f|${land || ""}|${String(kgNr || "").trim()}|${String(gstNr || "").trim()}`;
127	
128	/** Anzeige einer gesperrten Person ohne Klartext-Namen: „M. M***, 87787“ */
129	export function personMaskiert({ vorname = "", nachname = "", firma = "", plz = "" } = {}) {
130	  const n = firma && !nachname ? firma : nachname;
131	  return `${vorname ? `${vorname[0]}. ` : ""}${n ? `${n[0]}***` : "***"}${plz ? `, ${plz}` : ""}`;
132	}
133	
134	// ---------------------------------------------------------------- Kosten, Pacht, Kennzahlen
135	
136	/** Grundbuch-Kostenschätzung für ein Ziel: je Flurstück eine Abfrage (konservativ – mehrere Flurstücke auf einem Blatt sind günstiger) */
137	export function grundbuchSchaetzung(land, anzahlFlurstuecke) {
138	  const k = GRUNDBUCH_KOSTEN[land] || GRUNDBUCH_KOSTEN.DE;
139	  const n = Math.max(1, Number(anzahlFlurstuecke) || 1);
140	  return { anzahl: n, jeAbfrage: k.jeAbfrage, betrag: Math.round(n * k.jeAbfrage * 100) / 100, waehrung: k.waehrung, text: k.text };
141	}
142	
143	/** Unverbindliche Pachtspanne je ha und Jahr nach Ampel (grün: obere Hälfte, gelb: untere Hälfte) */
144	export function pachtspanne(ha, ampel = "gelb") {
145	  const p = PACHT.freiflaecheProHa;
146	  const [min, max] = ampel === "gruen" ? [p.mittel, p.max] : [p.min, p.mittel];
147	  const h = Number(ha) || 0;
148	  return { proHaMin: min, proHaMax: max, jahrMin: Math.round((h * min) / 100) * 100, jahrMax: Math.round((h * max) / 100) * 100 };
149	}
150	
151	const tageZwischen = (a, b) => Math.floor((new Date(b).getTime() - new Date(a).getTime()) / 86400e3);
152	
153	/** Hat der Empfänger reagiert (Anfrage, Termin, Widerspruch, Rückmeldung per Brief/Telefon)? Ein bloßer Seitenaufruf zählt nicht. */
154	export const hatReagiert = (e) => !!(e.anfragen?.length || e.termine?.length || e.widerspruchAm || e.rueckmeldungAm || ["reaktion", "termin", "gesichert", "abgelehnt", "widerspruch"].includes(e.status));
155	
156	/**
157	 * Fällige Nachfassstufen eines Empfängers: [{ stufe, ergebnis: "aufgabe" | "uebersprungen", grund }].
158	 * Bedingungen: Kampagne aktiv, Erstbrief versandt, keine Reaktion, nicht gesperrt, Stufe noch nicht erledigt, Frist erreicht.
159	 */
160	export function nachfassFaellig(kampagne, empfaenger, heute = new Date().toISOString()) {
161	  if (kampagne?.status !== "aktiv" || !empfaenger) return [];
162	  const erst = (empfaenger.briefe || []).find((b) => b.nr === 1);
163	  if (!erst || empfaenger.gesperrt || hatReagiert(empfaenger)) return [];
164	  const tage = tageZwischen(erst.am, heute);
165	  const erledigt = empfaenger.nachfass || {};
166	  const out = [];
167	  for (const s of kampagne.nachfass || []) {
168	    if (!s.aktiv || erledigt[s.id] || tage < s.nachTagen) continue;
169	    if (s.art === "zweiter_brief") {
170	      if ((empfaenger.briefe || []).length >= 2) out.push({ stufe: s, ergebnis: "uebersprungen", grund: "Bereits zwei Briefe versandt." });
171	      else out.push({ stufe: s, ergebnis: "aufgabe", grund: "" });
172	    } else if (s.art === "anruf_einwilligung") {
173	      if (empfaenger.einwilligungTelefon?.am) out.push({ stufe: s, ergebnis: "aufgabe", grund: "" });
174	      else out.push({ stufe: s, ergebnis: "uebersprungen", grund: "Keine Einwilligung für Telefon – kein Anruf (UWG/TKG). Nur Brief möglich." });
175	    }
176	  }
177	  return out;
178	}
179	
180	/**
181	 * Kennzahlen einer Kampagne aus Zielen/Empfängern:
182	 * Ziele, Flurstücke, ha/MWp, Briefe, Aufrufe (Empfänger mit ≥ 1 Aufruf und Summe), Anfragen, Termine, Widersprüche,
183	 * gesicherte ha, Kosten (Grundbuch Ist + Versand + sonstige) und Kosten je gesichertem ha, Rücklaufquote.
184	 */
185	export function kampagnenKennzahlen(kampagne, ziele = []) {
186	  const land = kampagne?.land || "DE";
187	  const vk = { ...(VERSAND_KOSTEN[land] || VERSAND_KOSTEN.DE) };
188	  for (const f of ["porto", "druck"]) if (kampagne?.kosten?.[f] != null && kampagne.kosten[f] !== "") vk[f] = Number(kampagne.kosten[f]); // leer = Standard
189	  const empf = ziele.flatMap((z) => z.empfaenger || []);
190	  const briefe = empf.reduce((s, e) => s + (e.briefe || []).length, 0);
191	  const aufrufeSumme = empf.reduce((s, e) => s + (Number(e.aufrufe) || 0), 0);
192	  const mitAufruf = empf.filter((e) => Number(e.aufrufe) > 0).length;
193	  const anfragen = empf.reduce((s, e) => s + (e.anfragen || []).length, 0);
194	  const termine = empf.reduce((s, e) => s + (e.termine || []).length, 0);
195	  const widersprueche = empf.filter((e) => e.widerspruchAm).length;
196	  const gesichertHa = Math.round(ziele.reduce((s, z) => s + (z.status === "gesichert" ? Number(z.gesichertHa ?? z.ha) || 0 : 0), 0) * 100) / 100;
197	  const grundbuch = ziele.reduce((s, z) => s + (Number(z.grundbuch?.kostenIst) || 0), 0);
198	  const grundbuchPlan = ziele.reduce((s, z) => s + (Number(z.grundbuch?.schaetzung?.betrag) || 0), 0);
199	  const versand = Math.round(briefe * ((Number(vk.porto) || 0) + (Number(vk.druck) || 0)) * 100) / 100;
200	  const sonstige = Number(kampagne?.kosten?.sonstige) || 0;
201	  const kosten = Math.round((grundbuch + versand + sonstige) * 100) / 100;
202	  return {
203	    ziele: ziele.length,
204	    flurstuecke: ziele.reduce((s, z) => s + (z.parzellen || []).length, 0),
205	    ha: Math.round(ziele.reduce((s, z) => s + (Number(z.ha) || 0), 0) * 10) / 10,
206	    mwp: Math.round(ziele.reduce((s, z) => s + (Number(z.mwp) || 0), 0) * 10) / 10,
207	    empfaenger: empf.length,
208	    gesperrt: empf.filter((e) => e.gesperrt).length,
209	    briefe,
210	    aufrufe: aufrufeSumme,
211	    empfaengerMitAufruf: mitAufruf,
212	    anfragen,
213	    termine,
214	    widersprueche,
215	    gesichertHa,
216	    kosten: { grundbuch: Math.round(grundbuch * 100) / 100, grundbuchPlan: Math.round(grundbuchPlan * 100) / 100, versand, sonstige, summe: kosten, waehrung: (GRUNDBUCH_KOSTEN[land] || GRUNDBUCH_KOSTEN.DE).waehrung },
217	    kostenJeHa: gesichertHa > 0 ? Math.round(kosten / gesichertHa) : null,
218	    ruecklaufQuote: briefe ? Math.round(((anfragen + termine) / Math.max(1, empf.filter((e) => (e.briefe || []).length).length)) * 1000) / 10 : null,
219	    aufrufQuote: briefe ? Math.round((mitAufruf / Math.max(1, empf.filter((e) => (e.briefe || []).length).length)) * 1000) / 10 : null,
220	  };
221	}

