 41	function kampagneVon(akq, id) {
 42	  const k = akq.kampagnen.find((x) => x.id === v.kennung(id));
 43	  if (!k) throw nichtGefunden("Kampagne nicht gefunden.");
 44	  return k;
 45	}
 46	function zielVon(akq, id) {
 47	  const z = akq.ziele.find((x) => x.id === v.kennung(id));
 48	  if (!z) throw nichtGefunden("Zielfläche nicht gefunden.");
 49	  return z;
