 54	
 55	function personGesperrt(akq, person) {
 56	  const h = hash(personSchluessel(person));
 57	  return akq.sperrliste.find((s) => s.aktiv !== false && s.personHash === h) || null;
 58	}
 59	function flurstueckGesperrt(akq, land, p) {
 60	  const h = hash(flurstueckSchluessel(land, p.kgNr, p.gstNr));
 61	  return akq.sperrliste.find((s) => s.aktiv !== false && (s.flurstueckHashes || []).includes(h)) || null;
