 64	function sperreEintragen(db, n, { person, land, flurstuecke = [], grund = "widerspruch", quelle = "brief", kampagneId = null, zielId = null, notiz = "" }) {
 65	  const akq = akqSicher(db);
 66	  const personHash = person ? hash(personSchluessel(person)) : null;
 67	  const vorhanden = personHash ? akq.sperrliste.find((s) => s.aktiv !== false && s.personHash === personHash) : null;
 68	  const fHashes = flurstuecke.map((p) => hash(flurstueckSchluessel(land, p.kgNr, p.gstNr)));
 69	  if (vorhanden) {
 70	    vorhanden.flurstueckHashes = [...new Set([...(vorhanden.flurstueckHashes || []), ...fHashes])];
 71	    return vorhanden;
 72	  }
 73	  const s = {
 74	    id: neueId("SL"),
 75	    personHash,
 76	    anzeige: person ? personMaskiert(person) : `${flurstuecke.length} Flurstück(e)`,
 77	    flurstueckHashes: fHashes,
 78	    land: land || null,
 79	    grund: v.auswahl(grund, SPERR_GRUENDE, "widerspruch"),
 80	    quelle: v.auswahl(quelle, SPERR_QUELLEN, "brief"),
 81	    notiz: v.text(notiz, 300),
 82	    kampagneId,
 83	    zielId,
 84	    am: jetzt(),
 85	    vonId: n?.id || null,
 86	    aktiv: true,
 87	  };
 88	  akq.sperrliste.push(s);
 89	  W.protokoll(db, n || null, "sperrliste", "sperrliste", s.id, `Sperrvermerk (${SPERR_GRUENDE[s.grund]}, ${SPERR_QUELLEN[s.quelle]}) – ${s.anzeige}`);
 90	  // Sofort in allen Kampagnen wirksam: betroffene Empfänger sperren, Codes deaktivieren
 91	  for (const z of akq.ziele) {
 92	    for (const e of z.empfaenger || []) {
 93	      if (e.gesperrt) continue;
 94	      // Bestehende Empfänger: nur dieselbe Person (Miteigentümer bleiben ansprechbar); Flurstücks-Sperre wirkt bei neuen Kampagnen
 95	      if (personHash && e.sperrHash === personHash) {
 96	        e.gesperrt = true;
 97	        e.gesperrtGrund = SPERR_GRUENDE[s.grund];
 98	        e.codeAktiv = false;
 99	        if (s.grund === "widerspruch" && !e.widerspruchAm) e.widerspruchAm = s.am;
100	        e.status = "widerspruch";
101	      }
102	    }
103	    if ((z.empfaenger || []).length && z.empfaenger.every((e) => e.gesperrt)) z.status = "gesperrt";
104	  }
105	  return s;
106	}
