108	// ---------------------------------------------------------------- Nachfassen (Automationsregeln der Kampagne)
109	
110	function nachfassIntern(db, heute = jetzt()) {
111	  const akq = akqSicher(db);
112	  let neu = 0;
113	  for (const k of akq.kampagnen.filter((x) => x.status === "aktiv")) {
114	    for (const z of zieleVon(akq, k.id)) {
115	      for (const e of z.empfaenger || []) {
116	        for (const f of nachfassFaellig(k, e, heute)) {
117	          e.nachfass = e.nachfass || {};
118	          const eintrag = { am: jetzt(), ergebnis: f.ergebnis, grund: f.grund, aufgabeId: null };
119	          if (f.ergebnis === "aufgabe") {
120	            db.aufgaben = db.aufgaben || [];
121	            const zweiter = f.stufe.art === "zweiter_brief";
122	            const a = {
123	              id: neueId("AF"),
124	              titel: zweiter ? `Zweiten Brief senden (einmalig): ${z.gemeinde} · ${personMaskiert(e)}` : `Anruf (Einwilligung liegt vor): ${z.gemeinde} · ${personMaskiert(e)}`,
125	              beschreibung: [
126	                `Kampagne ${k.name} (${k.id}), Zielfläche ${z.id}: ${f.stufe.nachTagen} Tage ohne Reaktion auf den Brief vom ${String(e.briefe?.[0]?.am || "").slice(0, 10)}.`,
127	                zweiter
128	                  ? "Zweitbrief über „Serienbrief → Stufe 2“ erzeugen und den Versand bestätigen. Kein weiterer Brief danach; bei Widerspruch sofort Sperrliste."
129	                  : `Einwilligung Telefon vom ${String(e.einwilligungTelefon?.am || "").slice(0, 10)} (${e.einwilligungTelefon?.quelle || "–"}). Nur im Rahmen dieser Einwilligung anrufen; Ergebnis in der Kampagne erfassen.`,
130	                `Link: /portal/admin/akquise/kampagnen/${k.id}`,
131	              ].join("\n"),
132	              faelligAm: plusTage(3),
133	              zustaendigId: k.zustaendigId || k.erstelltVon,
134	              bezugArt: null,
135	              bezugId: null,
136	              kampagneId: k.id,
137	              kampagnenZielId: z.id,
138	              status: "offen",
139	              erstelltVon: null,
140	              erstelltAm: jetzt(),
141	              erledigtAm: null,
142	              erledigtVon: null,
143	              erinnertAm: null,
144	              quelle: "kampagne_nachfassen",
145	            };
146	            db.aufgaben.push(a);
147	            eintrag.aufgabeId = a.id;
148	          }
149	          e.nachfass[f.stufe.id] = eintrag;
150	          neu++;
151	        }
152	      }
153	    }
154	  }
