 20	export function gemeindeSchluessel(land, bundesland, name) {
 21	  const n = String(name || "")
 22	    .toLowerCase()
 23	    .replace(/\((demo|fiktiv)\)/g, "")
 24	    .replace(/^(gemeinde|stadt|markt|marktgemeinde|stadtgemeinde|ortsgemeinde|große kreisstadt|kreisstadt)\s+/, "")
 25	    .replace(/ä/g, "ae")
 26	    .replace(/ö/g, "oe")
 27	    .replace(/ü/g, "ue")
 28	    .replace(/ß/g, "ss")
 29	    .replace(/[^a-z0-9]+/g, "-")
 30	    .replace(/^-|-$/g, "");
 31	  return `${land || "XX"}:${String(bundesland || "").slice(0, 3).toLowerCase()}:${n}`;
 32	}
