 50	    const ku = k.merkmale?.kulisse;
 51	    const inKulisse = k.land === "DE" ? Math.max(ku?.randstreifenAnteil || 0, ku?.benachteiligtAnteil || 0, ku?.moorAnteil || 0, ku?.konversionAnteil || 0) : k.land === "CH" ? ku?.eignungAnteil || 0 : k.widmung?.status === "zone" ? 1 : k.widmung?.status === "angrenzend" ? 0.5 : 0;
 52	    g.haKulisse += (Number(k.ha) || 0) * inKulisse;
 53	    g.beste.push({ id: k.id, ha: k.ha, mwp: k.mwp, score: k.score, ampel: k.ampel });
 54	    const kn = k.netz?.knoten;
 55	    if (kn?.id) {
 56	      const kap = kapazitaeten[kn.id] || {};
 57	      const alt = g.knoten.get(kn.id);
 58	      g.knoten.set(kn.id, { id: kn.id, name: kn.name, art: kn.art, kapazitaet: kap.kapazitaet || kn.kapazitaet || "unbekannt", freiMw: kap.freiMw ?? null, flaechen: (alt?.flaechen || 0) + 1, mwp: (alt?.mwp || 0) + (Number(k.mwp) || 0) });
 59	    }
 60	  }
 61	  for (const g of m.values()) {
 62	    g.beste = g.beste.sort((a, b) => b.score - a.score || b.ha - a.ha).slice(0, 3);
 63	    const kn = [...g.knoten.values()];
 64	    const frei = kn.filter((x) => x.kapazitaet === "frei");
 65	    g.netz = {
 66	      knoten: kn.sort((a, b) => b.mwp - a.mwp).slice(0, 4),
 67	      status: frei.length ? "frei" : kn.some((x) => x.kapazitaet === "unbekannt") ? "unbekannt" : kn.length ? "knapp" : "keiner",
 68	      freiMw: frei.reduce((s, x) => s + (Number(x.freiMw) || 0), 0) || null,
 69	    };
 70	    delete g.knoten;
 71	    for (const f of ["ha", "mwp", "haGeeignet", "haKulisse", "gewichteteHa"]) g[f] = Math.round(g[f] * 10) / 10;
 72	  }
 73	  return m;
 74	}
