 76	/**
 77	 * Ranking-Punkte (0–100) einer Gemeinde mit Begründung.
 78	 * g: Potenzial (potenzialJeGemeinde), info: { bauleitplanung, kriterienkatalog, konkurrenz[] }
 79	 */
 80	export function gemeindeRanking(g, info = {}) {
 81	  const G = RANKING_GEWICHTE;
 82	  const teile = [];
 83	  const pf = Math.min(1, (g.gewichteteHa || 0) / 60) * G.flaeche;
 84	  teile.push({ id: "flaeche", label: "Flächenpotenzial", punkte: pf, max: G.flaeche, text: `${g.haGeeignet} ha geeignet (Score ≥ 45) von ${g.ha} ha, ${g.mwp} MWp` });
 85	  const top = g.beste?.length ? g.beste.reduce((s, x) => s + x.score, 0) / g.beste.length : 0;
 86	  teile.push({ id: "qualitaet", label: "Qualität der besten Flächen", punkte: (top / 100) * G.qualitaet, max: G.qualitaet, text: `Ø Score der besten ${g.beste?.length || 0}: ${Math.round(top)}` });
 87	  const pn = { frei: 15, unbekannt: 8, knapp: 2, keiner: 0 }[g.netz?.status || "keiner"];
 88	  teile.push({ id: "netz", label: "Netz/UW-Kapazität", punkte: pn, max: G.netz, text: { frei: `Kapazität frei${g.netz?.freiMw ? ` (${g.netz.freiMw} MW)` : ""}`, unbekannt: "Kapazität unbekannt – beim Netzbetreiber anfragen", knapp: "Kapazität knapp", keiner: "kein Netzknoten im Umkreis" }[g.netz?.status || "keiner"] });
 89	  const bp = info.bauleitplanung || "";
 90	  let pp = PLANUNG_PUNKTE[bp] ?? 6;
 91	  if (info.kriterienkatalog === "ja") pp = Math.min(15, pp + 3);
 92	  teile.push({ id: "planung", label: "Bauleitplanung / Offenheit", punkte: pp, max: G.planung, text: `${BAULEITPLANUNG_STAND[bp] || "Stand unbekannt"}${info.kriterienkatalog ? ` · Kriterienkatalog: ${KRITERIENKATALOG[info.kriterienkatalog]}` : ""}` });
 93	  const anteil = g.ha > 0 ? Math.min(1, (g.haKulisse || 0) / g.ha) : 0;
 94	  teile.push({ id: "kulisse", label: g.land === "DE" ? "EEG-Kulisse" : g.land === "CH" ? "Eignungsgebiete" : "Widmungslage", punkte: anteil * G.kulisse, max: G.kulisse, text: `${Math.round(anteil * 100)} % der Kandidatenfläche` });
 95	  const konk = (info.konkurrenz || []).filter((x) => x.aktiv !== false);
 96	  const druck = konk.reduce((s, x) => s + (KONKURRENZ_GEWICHT[x.status] || 1), 0);
 97	  const pk = Math.max(0, G.konkurrenz - druck * 2);
 98	  teile.push({ id: "konkurrenz", label: "Wettbewerb", punkte: pk, max: G.konkurrenz, text: konk.length ? `${konk.length} bekannte Projekte anderer Entwickler${konk.some((x) => x.mw) ? ` (${konk.reduce((s, x) => s + (Number(x.mw) || 0), 0)} MW)` : ""}` : "keine Hinweise erfasst" });
 99	  const punkte = Math.round(teile.reduce((s, x) => s + x.punkte, 0));
100	  for (const t of teile) t.punkte = Math.round(t.punkte * 10) / 10;
101	  const stufe = punkte >= 65 ? "A" : punkte >= 45 ? "B" : "C";
102	  return { punkte, stufe, teile };
103	}
