118	const plusTage = (tage) => new Date(Date.now() + tage * 86400e3).toISOString().slice(0, 10);
119	const nameNorm = (land, name) => gemeindeSchluessel(land, "", name).replace(/^(\w+):[^:]*:/, "$1:");
