136	/** Kommunale Anliegen (Vorgänge Typ „kommune“) je Gemeinde: letzter Stand Bauleitplanung/Kriterienkatalog */
137	function anliegenJeGemeinde(db) {
138	  const m = new Map();
139	  for (const vg of (db.vorgaenge || []).filter((x) => x.typ === "kommune" && x.daten?.gemeinde)) {
140	    const land = vg.daten.land || vg.kontakt?.land || "DE";
141	    const s = nameNorm(land, vg.daten.gemeinde);
142	    const alt = m.get(s);
143	    if (!alt || String(vg.erstelltAm) > String(alt.am)) m.set(s, { vorgangId: vg.id, am: vg.erstelltAm, status: vg.status, bauleitplanung: vg.daten.bauleitplanung || "", kriterienkatalog: vg.daten.kriterienkatalog || "" });
144	  }
145	  return m;
