148	function orgFuer(db, land, name) {
149	  const s = nameNorm(land, name);
150	  return (db.bo?.organisationen || []).find((o) => ["gemeinde", "stadtwerk"].includes(o.art) && (o.land || "DE") === land && nameNorm(land, o.name) === s) || null;
151	}
