153	/**
154	 * Screening-Liste: Kandidaten (serverseitig aus dem Geodaten-Adapter) + gepflegte Angaben + Anliegen + CRM → Ranking.
155	 * filter: { land, bundesland, bezirk, minPunkte }
156	 */
157	export async function gemeindenScreening(n, kandidaten = [], kapazitaeten = {}, filter = {}) {
158	  rechtNoetig(n, "geodaten", 1);
159	  const db = await boLesen();
160	  const gem = db.akq?.gemeinden || {};
161	  const anliegen = anliegenJeGemeinde(db);
162	  const ziele = db.akq?.ziele || [];
163	  const kampagnen = db.akq?.kampagnen || [];
164	  const liste = [];
165	  for (const g of potenzialJeGemeinde(kandidaten, kapazitaeten).values()) {
166	    if (filter.land && g.land !== filter.land) continue;
167	    if (filter.bundesland && g.bundesland !== filter.bundesland) continue;
168	    if (filter.bezirk && g.bezirk !== filter.bezirk) continue;
169	    const manuell = gem[g.schluessel] || {};
170	    const a = anliegen.get(nameNorm(g.land, g.name));
171	    const info = {
172	      bauleitplanung: manuell.bauleitplanung || a?.bauleitplanung || "",
173	      bauleitplanungQuelle: manuell.bauleitplanung ? "manuell" : a?.bauleitplanung ? "anliegen" : "",
174	      kriterienkatalog: manuell.kriterienkatalog || a?.kriterienkatalog || "",
175	      konkurrenz: manuell.konkurrenz || [],
176	    };
177	    const r = gemeindeRanking(g, info);
178	    if (filter.minPunkte && r.punkte < filter.minPunkte) continue;
179	    const org = orgFuer(db, g.land, g.name);
180	    const zg = ziele.filter((z) => z.land === g.land && z.gemeinde === g.name && kampagnen.some((k) => k.id === z.kampagneId));
181	    liste.push({
182	      ...g,
183	      ...info,
184	      notiz: manuell.notiz || "",
185	      ranking: r,
186	      anliegen: a ? { vorgangId: a.vorgangId, status: a.status, am: a.am } : null,
187	      crm: org ? { organisationId: org.id, name: org.name, aktivitaeten: (db.bo?.aktivitaeten || []).filter((x) => x.organisationId === org.id).length } : null,
188	      kampagnen: { ziele: zg.length, gesichertHa: Math.round(zg.reduce((s, z) => s + (z.status === "gesichert" ? Number(z.gesichertHa ?? z.ha) || 0 : 0), 0) * 10) / 10 },
189	      uebergabe: manuell.uebergabe || null,
190	      geaendertAm: manuell.geaendertAm || null,
191	      geaendertVon: manuell.geaendertVon ? nameVon(db, manuell.geaendertVon) : "",
192	    });
193	  }
194	  liste.sort((a, b) => b.ranking.punkte - a.ranking.punkte || b.haGeeignet - a.haGeeignet);
195	  liste.forEach((x, i) => (x.rang = i + 1));
196	  return { gemeinden: liste, stand: jetzt(), labels: { bauleitplanung: BAULEITPLANUNG_STAND, kriterienkatalog: KRITERIENKATALOG, konkurrenz: KONKURRENZ_STATUS } };
197	}
