199	function gemeindeEintrag(gem, schluessel, basis = {}) {
200	  if (!gem[schluessel]) gem[schluessel] = { schluessel, name: v.text(basis.name, 120), land: v.auswahl(basis.land, ["DE", "AT", "CH"], "DE"), bundesland: v.text(basis.bundesland, 60), konkurrenz: [], bauleitplanung: "", kriterienkatalog: "", notiz: "" };
