+239     20	/**
+239     21	 * Meilenstein-Vorlage für Land und Typ: [{ schluessel, titel, kategorie, dauerMonate, nach, phase, dokumentPflicht, externTitel, gutachten }]
+239     22	 * Abhängigkeiten auf nicht enthaltene Schritte werden durch deren (enthaltene) Vorgänger ersetzt.
+239     23	 */
+239     24	export function vorlage(land = "DE", typ = "freiflaeche") {
+239     25	  const alle = SCHRITTE[land] || SCHRITTE.DE;
+239     26	  const t = ENTWICKLUNG_TYPEN[typ] ? typ : "freiflaeche";
+239     27	  const aktiv = alle.filter((x) => passt(x, t));
