+239     54	
+239     55	// ================================================================ Termine
+239     56	
+239     57	const TAG = 86400e3;
+239     58	export const isoTag = (d) => new Date(d).toISOString().slice(0, 10);
+239     59	export const heuteIso = () => heuteLokal(); // Europe/Vienna (Überfälligkeit von Meilensteinen)
+239     60	export function plusMonate(iso, monate) {
+239     61	  const d = new Date(`${iso}T00:00:00Z`);
+239     62	  const ganz = Math.floor(monate);
+239     63	  d.setUTCMonth(d.getUTCMonth() + ganz);
+239     64	  const rest = monate - ganz;
+239     65	  if (rest) d.setTime(d.getTime() + Math.round(rest * 30.4 * TAG));
