+239     68	export const tageZwischen = (a, b) => Math.round((new Date(`${b}T00:00:00Z`) - new Date(`${a}T00:00:00Z`)) / TAG);
+239     69	const maxIso = (liste) => liste.filter(Boolean).sort().at(-1) || null;
+239     70	
+239     71	/** Effektives Ende eines Meilensteins für Nachfolger: Ist-Ende; offen und überfällig → heute (Prognose) */
+239     72	export function effektivesEnde(m, heute = heuteIso(), prognose = true) {
+239     73	  if (m.status === "erledigt") return m.istEnde || m.sollEnde;
+239     74	  if (m.status === "entfaellt") return m.istEnde || m.sollStart || m.sollEnde;
+239     75	  if (prognose && m.sollEnde && m.sollEnde < heute) return heute;
+239     76	  return m.sollEnde;
+239     77	}
+239     78	
+239     79	/** Topologische Reihenfolge (Kreise werden am Ende angehängt, nie Endlosschleife) */
+239     80	export function topologisch(meilensteine) {
+239     81	  const nachId = new Map(meilensteine.map((m) => [m.id, m]));
+239     82	  const erg = [];
+239     83	  const status = new Map();
+239     84	  const besuch = (m) => {
+239     85	    if (status.get(m.id) === 2) return;
+239     86	    if (status.get(m.id) === 1) return; // Kreis
+239     87	    status.set(m.id, 1);
+239     88	    for (const v of m.nach || []) if (nachId.has(v)) besuch(nachId.get(v));
+239     89	    status.set(m.id, 2);
+239     90	    erg.push(m);
+239     91	  };
+239     92	  for (const m of meilensteine) besuch(m);
+239     93	  return erg;
+239     94	}
+239     95	
+239     96	/** Würde die Abhängigkeit `von → id` einen Kreis erzeugen? (von hängt dann an id) */
+239     97	export function erzeugtKreis(meilensteine, id, neueVorgaenger) {
+239     98	  const nachId = new Map(meilensteine.map((m) => [m.id, { ...m }]));
+239     99	  if (nachId.has(id)) nachId.get(id).nach = neueVorgaenger;
+239    100	  const gesehen = new Set();
+239    101	  const stapel = [...neueVorgaenger];
+239    102	  while (stapel.length) {
+239    103	    const x = stapel.pop();
+239    104	    if (x === id) return true;
+239    105	    if (gesehen.has(x)) continue;
+239    106	    gesehen.add(x);
+239    107	    stapel.push(...(nachId.get(x)?.nach || []));
+239    108	  }
+239    109	  return false;
+239    110	}
+239    111	
+239    112	/**
+239    113	 * Soll-Termine vorwärts rechnen: Start = max(effektives Ende der Vorgänger) bzw. Projektstart; Ende = Start + Dauer.
+239    114	 * Erledigte Meilensteine behalten ihre Termine. `fixieren` = Meilensteine mit manuell gesetztem Soll behalten es.
+239    115	 * `prognose` = überfällige, offene Vorgänger enden frühestens heute (verschiebt Nachfolger); ohne: Soll-Basis.
+239    116	 * Liefert NEUE Objekte (sollStart, sollEnde gesetzt).
+239    117	 */
+239    118	export function planBerechnen(meilensteine, { start = heuteIso(), heute = heuteIso(), fixieren = true, prognose = true } = {}) {
+239    119	  const neu = new Map();
+239    120	  for (const m of topologisch(meilensteine)) {
+239    121	    const x = { ...m };
+239    122	    if (x.status !== "erledigt" && x.status !== "entfaellt" && !(fixieren && x.sollFix)) {
+239    123	      const vorg = (x.nach || []).map((v) => neu.get(v)).filter(Boolean);
+239    124	      const beginn = maxIso([start, ...vorg.map((v) => effektivesEnde(v, heute, prognose))]);
+239    125	      const s = x.istStart || beginn;
+239    126	      x.sollStart = s;
+239    127	      x.sollEnde = plusMonate(s, Number(x.dauerMonate) || 1);
+239    128	    }
+239    129	    neu.set(x.id, x);
+239    130	  }
+239    131	  return meilensteine.map((m) => neu.get(m.id));
+239    132	}
+239    133	
+239    134	/**
+239    135	 * Kritischer Pfad über Soll-/Prognose-Termine: Rückwärtsrechnung der spätesten Enden, Puffer ≤ 0 Tage = kritisch.
+239    136	 * Liefert Map id → { puffer, kritisch, prognoseStart, prognoseEnde } und das Prognose-Ende des Projekts.
+239    137	 */
+239    138	export function kritischerPfad(meilensteine, { heute = heuteIso() } = {}) {
+239    139	  const aktiv = meilensteine.filter((m) => m.status !== "entfaellt");
+239    140	  const ids = new Set(aktiv.map((m) => m.id));
+239    141	  // Prognose vorwärts (Verzug schiebt Nachfolger)
+239    142	  const prog = new Map();
+239    143	  for (const m of topologisch(aktiv)) {
+239    144	    const dauer = Math.max(1, tageZwischen(m.sollStart || heute, m.sollEnde || heute));
+239    145	    const vorg = (m.nach || []).filter((v) => ids.has(v)).map((v) => prog.get(v)).filter(Boolean);
+239    146	    let start = m.status === "erledigt" ? m.istStart || m.sollStart : maxIso([m.istStart || m.sollStart, ...vorg.map((v) => v.ende)]);
+239    147	    start = start || heute;
+239    148	    let ende;
+239    149	    if (m.status === "erledigt") ende = m.istEnde || m.sollEnde;
+239    150	    else {
+239    151	      ende = isoTag(new Date(`${start}T00:00:00Z`).getTime() + dauer * TAG);
+239    152	      if (ende < heute) ende = heute;
+239    153	    }
+239    154	    prog.set(m.id, { start, ende, dauer });
+239    155	  }
+239    156	  const projektEnde = maxIso([...prog.values()].map((p) => p.ende)) || heute;
+239    157	  const nachfolger = new Map(aktiv.map((m) => [m.id, []]));
+239    158	  for (const m of aktiv) for (const v of m.nach || []) if (nachfolger.has(v)) nachfolger.get(v).push(m.id);
+239    159	  const spaet = new Map();
+239    160	  for (const m of [...topologisch(aktiv)].reverse()) {
+239    161	    const nf = nachfolger.get(m.id) || [];
+239    162	    const lf = nf.length ? nf.map((n) => isoTag(new Date(`${spaet.get(n)}T00:00:00Z`).getTime() - prog.get(n).dauer * TAG)).sort()[0] : projektEnde;
+239    163	    spaet.set(m.id, lf);
+239    164	  }
+239    165	  const erg = new Map();
+239    166	  for (const m of aktiv) {
+239    167	    const p = prog.get(m.id);
+239    168	    const puffer = tageZwischen(p.ende, spaet.get(m.id));
+239    169	    erg.set(m.id, { puffer, kritisch: m.status !== "erledigt" && puffer <= 0, prognoseStart: p.start, prognoseEnde: p.ende });
+239    170	  }
+239    171	  return { je: erg, projektEnde };
+239    172	}
+239    173	
+239    174	/** Verzug in Tagen (> 0 = überfällig bzw. verspätet erledigt), sonst 0 */
+239    175	export function verzugTage(m, heute = heuteIso()) {
+239    176	  if (!m?.sollEnde || m.status === "entfaellt") return 0;
+239    177	  if (m.status === "erledigt") return Math.max(0, m.istEnde ? tageZwischen(m.sollEnde, m.istEnde) : 0);
+239    178	  return Math.max(0, tageZwischen(m.sollEnde, heute));
+239    179	}
+239    180	export const istUeberfaellig = (m, heute = heuteIso()) => !MEILENSTEIN_FERTIG.includes(m.status) && !!m.sollEnde && m.sollEnde < heute;
+239    181	
+239    182	/** Fehlende Vorgänger (nicht erledigt/entfallen) – Erledigen ist erst danach möglich */
+239    183	export function offeneVorgaenger(meilensteine, m) {
+239    184	  const nachId = new Map(meilensteine.map((x) => [x.id, x]));
+239    185	  return (m.nach || []).map((v) => nachId.get(v)).filter((v) => v && !MEILENSTEIN_FERTIG.includes(v.status));
+239    186	}
+239    187	
+239    188	// ================================================================ Phase & Pipeline-Wert
+239    189	
+239    190	const PHASEN_IDS = PHASEN.map((p) => p.id);
+239    191	
+239    192	/** Erreichte Phase = höchste Phase erledigter Meilensteine (null = Akquise, vor Flächensicherung) */
+239    193	export function phaseAusMeilensteinen(meilensteine) {
+239    194	  let best = -1;
+239    195	  for (const m of meilensteine) if (m.status === "erledigt" && m.phase) best = Math.max(best, PHASEN_IDS.indexOf(m.phase));
+239    196	  return best >= 0 ? PHASEN_IDS[best] : null;
+239    197	}
+239    198	
+239    199	export const phaseLabel = (id) => (id ? PHASEN.find((p) => p.id === id)?.kurz || id : "Akquise");
+239    200	
+239    201	/** Pipeline-Wert = MWp × 1000 × €/kWp (Mitte der Phasenspanne) × Wahrscheinlichkeit */
+239    202	export function pipelineWert({ mwp, phase, wahrscheinlichkeit = null }) {
+239    203	  const p = PHASEN.find((x) => x.id === phase) || PHASEN[0];
+239    204	  const preisProKwp = (p.preisProKwp.min + p.preisProKwp.max) / 2;
+239    205	  const w = wahrscheinlichkeit !== null && wahrscheinlichkeit !== undefined && wahrscheinlichkeit !== "" ? Number(wahrscheinlichkeit) : ENTWICKLUNG.wahrscheinlichkeit[phase || "akquise"] ?? 0;
+239    206	  const kwp = (Number(mwp) || 0) * 1000;
+239    207	  const volumen = Math.round(kwp * preisProKwp);
+239    208	  return { phase: phase || null, phaseLabel: phaseLabel(phase), preisProKwp, wahrscheinlichkeit: w, volumen, wert: Math.round(volumen * w), gewichtetMwp: Math.round((Number(mwp) || 0) * w * 100) / 100 };
+239    209	}
+239    210	
+239    211	/** Plan-Dauer bis COD über die Vorlage (Monate entlang des längsten Pfads) */
+239    212	export function planMonate(schritte) {
+239    213	  const ende = new Map();
+239    214	  const nachS = new Map(schritte.map((s) => [s.schluessel, s]));
+239    215	  const rechne = (s, tiefe = 0) => {
+239    216	    if (ende.has(s.schluessel)) return ende.get(s.schluessel);
+239    217	    if (tiefe > 60) return 0;
+239    218	    const v = Math.max(0, ...s.nach.map((n) => (nachS.has(n) ? rechne(nachS.get(n), tiefe + 1) : 0)));
+239    219	    const e = v + s.dauerMonate;
+239    220	    ende.set(s.schluessel, e);
+239    221	    return e;
+239    222	  };
