+239    226	/** Grobe MWp-Schätzung aus Fläche (ha) für den Assistenten – Agri-PV mit größerem Reihenabstand */
+239    227	export function mwpAusFlaeche(ha, { agri = false, haProMwp = 1.1 } = {}) {
+239    228	  const x = Number(ha) || 0;
+239    229	  return Math.round((x / (agri ? haProMwp * 1.6 : haProMwp)) * 10) / 10;
+239    230	}
+239    231	
+239    232	export const ZIEL_MWP_JAHR = ENTWICKLUNG.zielMwpJahr;
