+239    234	/** Quartal eines Datums (für vereinfachte Sichten): „Q3 2027“ */
+239    235	export function quartal(iso) {
+239    236	  if (!iso) return "";
+239    237	  const d = new Date(`${String(iso).slice(0, 10)}T00:00:00Z`);
+239    238	  return `Q${Math.floor(d.getUTCMonth() / 3) + 1} ${d.getUTCFullYear()}`;

