  3	// Standard-Projektdatenblatt der Projektbörse (Anbieter → Börse): phasenabhängige Felder aus
  4	// datenblatt-schema.json, Bereinigung (Positivliste), Vollständigkeit, Plausibilitätsprüfungen und
  5	// Due-Diligence-Index (acht Kategorien mit Ampel). Reine Funktionen – Browser, Server und Node-Tests.
  6	// Frappe-Gegenstück: Backend-Import/oekoinvest_app/oekoinvest_app/plattform/fach/datenblatt.py (gleiche Regeln).
  7	//
  8	// Speicherort: projekt.datenblatt = { feldId: wert } – vertraulich (nie in der öffentlichen Projektion).
  9	// Felder mit `pfad: "vertraulich"` liegen weiter im bestehenden Objekt projekt.vertraulich (kein Doppelbestand).
 10	
 11	import SCHEMA from "./datenblatt-schema.js";
 12	import { BAUART, ERLOESE, FREIFLAECHE, PACHT, PHASEN, AGRI, CARPORT, regionById } from "../../invest/markt.js";
