 17	export const DD_KATEGORIEN = SCHEMA.dd;
 18	/** Felder, die im Objekt `vertraulich` liegen (im Formular-Schritt „Vertrauliches“ ausblenden) */
 19	export const DATENBLATT_VERTRAULICH = DATENBLATT_FELDER.filter((f) => f.pfad === "vertraulich").map((f) => f.id);
 20	
 21	const PHASE_IDX = (id) => PHASEN.findIndex((p) => p.id === id);
 22	const DATUM = /^20\d\d-(0[1-9]|1[0-2])-(0[1-9]|[12]\d|3[01])$/;
 23	const STEUER = /[\u0000-\u001F\u007F]/g;
