 25	// ---------------------------------------------------------------- Werte lesen/bereinigen
 26	
 27	function zahlWert(v, f) {
 28	  if (v === undefined || v === null || v === "" || typeof v === "object" || typeof v === "boolean") return null;
 29	  const n = typeof v === "number" ? v : Number(String(v).replace(/\s/g, "").replace(",", "."));
 30	  if (!Number.isFinite(n) || n < (f.min ?? -Infinity) || n > (f.max ?? Infinity)) return null;
 31	  const s = f.stellen ?? 2;
 32	  return Math.round(n * 10 ** s) / 10 ** s;
 33	}
 34	
 35	function textWert(v, laenge = 200) {
 36	  if (v === undefined || v === null || typeof v === "object") return "";
 37	  return String(v).replace(STEUER, " ").replace(/\s{2,}/g, " ").trim().slice(0, laenge);
 38	}
 39	
 40	/** Ein Feld bereinigen – liefert null/"" für ungültig oder leer */
 41	export function feldBereinigen(f, v) {
 42	  switch (f.typ) {
 43	    case "zahl":
 44	      return zahlWert(v, f);
 45	    case "auswahl":
 46	      return f.optionen.some(([id]) => id === v) ? v : "";
 47	    case "datum": {
 48	      const s = textWert(v, 10);
 49	      if (!DATUM.test(s)) return "";
 50	      const d = new Date(`${s}T00:00:00Z`);
 51	      return Number.isNaN(d.getTime()) || d.toISOString().slice(0, 10) !== s ? "" : s;
 52	    }
 53	    case "tabelle": {
 54	      if (!Array.isArray(v)) return [];
 55	      return v
 56	        .slice(0, 40)
 57	        .map((z) => ({
 58	          jahr: zahlWert(z?.jahr, { min: 1990, max: 2100, stellen: 0 }),
 59	          istMwh: zahlWert(z?.istMwh, { min: 0, max: 10000000, stellen: 1 }),
 60	          prognoseMwh: zahlWert(z?.prognoseMwh, { min: 0, max: 10000000, stellen: 1 }),
 61	        }))
 62	        .filter((z) => z.jahr !== null && (z.istMwh !== null || z.prognoseMwh !== null))
 63	        .sort((a, b) => a.jahr - b.jahr);
