 97	/** Ist das Feld für dieses Projekt überhaupt relevant (Typ, Land, Bestand, Bedingung)? */
 98	export function feldRelevant(p, f) {
 99	  const bestand = p?.phase === "cod";
100	  if (f.nurTypen && !f.nurTypen.includes(p?.typ)) return false;
101	  if (f.ohneTypen && f.ohneTypen.includes(p?.typ)) return false;
102	  if (f.land && f.land !== p?.land) return false;
103	  if (f.nurBestand && !bestand) return false;
104	  if (f.ohneBestand && bestand) return false;
105	  if (f.wenn) {
106	    const bezug = DATENBLATT_FELDER.find((x) => x.id === f.wenn.feld);
107	    const w = bezug ? feldWert(p, bezug) : undefined;
108	    if (f.wenn.gesetzt) return gefuellt(w);
109	    if (f.wenn.in && !f.wenn.in.includes(w)) return false;
110	  }
111	  return true;
112	}
