114	/** Wird das Feld in der aktuellen Phase erwartet (zählt für die Vollständigkeit)? */
115	export function feldErwartet(p, f) {
116	  if (!f.pflicht || !feldRelevant(p, f)) return false;
117	  const phase = PHASE_IDX(p?.phase);
118	  if (phase < 0) return false;
