128	export function datenblattVollstaendigkeit(p) {
129	  const bereiche = SCHEMA.bereiche.map((b) => {
130	    const erwartet = b.felder.filter((f) => feldErwartet(p, f));
131	    const fehlend = erwartet.filter((f) => !gefuellt(feldWert(p, f)));
132	    return { id: b.id, titel: b.titel, erwartet: erwartet.length, erfuellt: erwartet.length - fehlend.length, fehlend: fehlend.map((f) => f.label) };
133	  });
134	  const erwartet = bereiche.reduce((s, b) => s + b.erwartet, 0);
135	  const erfuellt = bereiche.reduce((s, b) => s + b.erfuellt, 0);
136	  return { quote: erwartet ? Math.round((erfuellt / erwartet) * 100) : 100, erwartet, erfuellt, bereiche };
