165	  if (db.aufstaenderung === "dach" || p?.typ === "dach") return Math.round(region.ertrag * 0.9);
166	  if (db.aufstaenderung === "schwimmend") return Math.round(region.ertrag * 0.97);
167	  return Math.round(region.ertrag * BAUART[bauartFuer(db.aufstaenderung, p?.typ)].faktor);
168	}
169	
170	const heute = (jetzt) => (jetzt ? new Date(jetzt) : new Date()).toISOString().slice(0, 10);
171	
172	/**
173	 * Plausibilitätsprüfungen. Stufen: fehler (widersprüchlich), warnung (ungewöhnlich – bitte erläutern), info.
174	 * @returns {[{stufe, feld, dd, text}]}
175	 */
176	export function datenblattPruefen(p, { jetzt } = {}) {
177	  const h = [];
178	  const add = (stufe, feld, dd, text) => h.push({ stufe, feld, dd, text });
179	  const db = p?.datenblatt || {};
180	  const vt = p?.vertraulich || {};
181	  const mwp = Number(p?.mwp) || 0;
182	  const heuteIso = heute(jetzt);
183	  const phase = PHASE_IDX(p?.phase);
184	  const bestand = p?.phase === "cod";
185	  const pv = p?.typ !== "speicher";
186	
187	  // DC/AC-Verhältnis
188	  if (pv && mwp > 0 && db.mwac > 0) {
189	    const r = mwp / db.mwac;
190	    if (r < 0.95) add("warnung", "mwac", "technisch", `DC/AC-Verhältnis ${r.toFixed(2)} – AC-Leistung größer als die Modulleistung ist unüblich. Bitte prüfen.`);
191	    else if (r > 1.5) add("warnung", "mwac", "technisch", `DC/AC-Verhältnis ${r.toFixed(2)} – starke Überbauung, Abregelungsverluste im Ertragsgutachten ausweisen.`);
192	  }
193	
194	  // Flächenbedarf MWp/ha
195	  if (pv && mwp > 0 && Number(p?.flaecheHa) > 0 && !["dach", "carport"].includes(p?.typ)) {
196	    const bauart = BAUART[bauartFuer(db.aufstaenderung, p?.typ)];
197	    const haProMwp = Number(p.flaecheHa) / mwp;
198	    if (haProMwp < bauart.haProMwp * 0.6) add("warnung", "flaecheHa", "technisch", `Belegung ${(mwp / p.flaecheHa).toFixed(2)} MWp/ha ist für „${bauart.label}“ sehr dicht (üblich rund ${(1 / bauart.haProMwp).toFixed(2)} MWp/ha). Fläche oder Leistung prüfen.`);
199	    else if (haProMwp > bauart.haProMwp * 2.5) add("info", "flaecheHa", "technisch", `Belegung nur ${(mwp / p.flaecheHa).toFixed(2)} MWp/ha – Fläche enthält vermutlich Ausgleichs-, Abstands- oder Erweiterungsflächen. Bitte kurz erläutern.`);
200	  }
201	
202	  // Spezifischer Ertrag und P-Werte
203	  const p50 = Number(vt.ertragKwhKwp) || null;
204	  if (pv && p50) {
205	    const soll = erwarteterErtrag(p);
206	    const abw = p50 / soll - 1;
207	    if (abw > 0.12) add("warnung", "ertragKwhKwp", "ertrag", `P50 ${p50} kWh/kWp liegt ${Math.round(abw * 100)} % über dem regionalen Richtwert (${soll} kWh/kWp). Gutachten und Annahmen (Albedo, Bifazialgewinn, Verluste) prüfen.`);
208	    else if (abw < -0.2) add("warnung", "ertragKwhKwp", "ertrag", `P50 ${p50} kWh/kWp liegt deutlich unter dem regionalen Richtwert (${soll} kWh/kWp) – Verschattung oder Abregelung erläutern.`);
209	  }
210	  if (pv && p50 && db.ertragP90) {
211	    if (db.ertragP90 >= p50) add("fehler", "ertragP90", "ertrag", "P90 muss kleiner als P50 sein (höhere Überschreitungswahrscheinlichkeit = niedrigerer Wert).");
212	    else {
213	      const q = db.ertragP90 / p50;
214	      if (q > 0.97) add("warnung", "ertragP90", "ertrag", `P90/P50 = ${(q * 100).toFixed(1)} % – ungewöhnlich geringe Unsicherheit. Handelt es sich um einen 10-Jahres-P90? Für die Finanzierung zählt meist der 1-Jahres-P90.`);
215	      else if (q < 0.8) add("warnung", "ertragP90", "ertrag", `P90/P50 = ${(q * 100).toFixed(1)} % – sehr hohe Unsicherheit. Datenbasis und Unsicherheitsbudget des Gutachtens prüfen.`);
216	    }
217	  }
218	  if (pv && db.ertragP75) {
219	    if ((p50 && db.ertragP75 >= p50) || (db.ertragP90 && db.ertragP75 <= db.ertragP90)) add("fehler", "ertragP75", "ertrag", "Reihenfolge der P-Werte stimmt nicht: P90 < P75 < P50.");
220	  }
221	  if (pv && db.ertragDatenbasis === "eigen" && phase >= PHASE_IDX("satzung")) add("warnung", "ertragDatenbasis", "ertrag", "Nur Eigenberechnung – ab Baurecht erwarten Investoren und Banken ein unabhängiges Ertragsgutachten.");
222	
223	  // Netz
224	  const acRef = db.mwac || (mwp || null);
225	  if (db.zusageMw > 0 && acRef && db.zusageMw < acRef * 0.98) {
226	    if (db.ueberbauung !== "ja" && !db.einspeiseLimitMw) add("warnung", "zusageMw", "netz", `Zusage ${db.zusageMw} MW liegt unter der Anlagenleistung (${acRef} MW) – Überbauung bzw. Einspeisebegrenzung angeben und im Ertrag berücksichtigen.`);
227	    else add("info", "zusageMw", "netz", `Anschluss überbaut (${(acRef / db.zusageMw).toFixed(2)}-fach) – Abregelungsverluste sollten im Ertragsgutachten enthalten sein.`);
228	  }
229	  if (db.zusageBefristetBis && !bestand) {
230	    if (db.zusageBefristetBis < heuteIso) add("fehler", "zusageBefristetBis", "netz", "Die Befristung der Netzzusage ist abgelaufen – Verlängerung oder neue Zusage nachweisen.");
231	    else if (p?.codGeplant && String(p.codGeplant) > db.zusageBefristetBis.slice(0, String(p.codGeplant).length)) add("warnung", "zusageBefristetBis", "netz", "Geplante Inbetriebnahme liegt nach dem Ende der Netzreservierung.");
232	  }
233	  if (Number(vt.entfernungNetzKm) > 15) add("warnung", "entfernungNetzKm", "netz", `Netzverknüpfungspunkt ${vt.entfernungNetzKm} km entfernt – Trassensicherung (Dienstbarkeiten) und Kabelkosten gesondert ausweisen.`);
234	  if (["zusage", "reserviert", "vorhanden"].includes(p?.netzanschluss) && pv && !db.zusageDatum && !bestand && phase >= PHASE_IDX("netz")) add("info", "zusageDatum", "netz", "Netzanschluss laut Grunddaten zugesagt – Datum der Zusage ergänzen.");
235	  if (phase >= PHASE_IDX("netz") && p?.netzanschluss === "offen") add("warnung", "netz", "netz", "Phase „Netzzusage“ oder später, aber Netzanschluss laut Grunddaten „noch nicht angefragt“ – Angaben widersprechen sich.");
236	
237	  // Speicher
238	  if (db.speicherMw > 0 && db.speicherMwh > 0) {
239	    const dauer = db.speicherMwh / db.speicherMw;
240	    if (dauer < 0.5 || dauer > 8) add("warnung", "speicherMwh", "technisch", `Speicherdauer ${dauer.toFixed(1)} h ist ungewöhnlich (üblich 1–4 h).`);
241	  }
242	
243	  // Fläche / Pacht
244	  if (db.pachtEurHa) {
245	    const sp = p?.typ === "agri" ? PACHT.agriProHa : PACHT.freiflaecheProHa;
246	    if (db.pachtEurHa > sp.max * 1.3) add("warnung", "pachtEurHa", "kaufmaennisch", `Pacht ${db.pachtEurHa} €/ha liegt deutlich über der Marktspanne (${sp.min}–${sp.max} €/ha) – belastet die Wirtschaftlichkeit.`);
247	    else if (db.pachtEurHa < sp.min * 0.5) add("info", "pachtEurHa", "kaufmaennisch", `Pacht ${db.pachtEurHa} €/ha deutlich unter Marktspanne – Nachverhandlungs- bzw. Anfechtungsrisiko prüfen.`);
248	  }
249	  if (db.pachtLaufzeitJahre !== undefined && pv) {
250	    const gesamt = (db.pachtLaufzeitJahre || 0) + (db.pachtVerlaengerungJahre || 0);
251	    if (gesamt < 25) add("warnung", "pachtLaufzeitJahre", "rechtlich", `Pacht einschließlich Optionen nur ${gesamt} Jahre – unter der üblichen Betriebsdauer (25–30+ Jahre). Finanzierung und Restwert sind eingeschränkt.`);
252	  }
253	  if (db.gesichertPct !== undefined && db.gesichertPct < 100 && phase >= PHASE_IDX("satzung")) add("warnung", "gesichertPct", "rechtlich", `Nur ${db.gesichertPct} % der Fläche gesichert – ab Baurecht sollten alle Flurstücke gesichert sein.`);
254	  if (db.eigentuemerAnzahl > 10) add("info", "eigentuemerAnzahl", "rechtlich", `${db.eigentuemerAnzahl} Eigentümer – höherer Aufwand bei Dienstbarkeiten und Vertragsänderungen.`);
255	
256	  // Vermarktung
257	  if (db.eegZuschlagCt) {
258	    const hoechst = ERLOESE.eegBesondereCt + 1.5;
259	    if (db.eegZuschlagCt > hoechst) add("warnung", "eegZuschlagCt", "kaufmaennisch", `Zuschlagswert ${db.eegZuschlagCt} ct/kWh ungewöhnlich hoch (Zuschläge zuletzt um ${ERLOESE.eegFreiflaecheCt} ct/kWh) – Segment und Bescheid prüfen.`);
260	  }
261	  if (db.eegRealisierungsfrist && !bestand) {
262	    if (db.eegRealisierungsfrist < heuteIso) add("fehler", "eegRealisierungsfrist", "kaufmaennisch", "Realisierungsfrist des Zuschlags ist abgelaufen – Pönale bzw. Erlöschen des Zuschlags prüfen.");
263	    else if (p?.codGeplant && String(p.codGeplant) > db.eegRealisierungsfrist.slice(0, String(p.codGeplant).length)) add("warnung", "eegRealisierungsfrist", "kaufmaennisch", "Geplante Inbetriebnahme liegt nach der Realisierungsfrist des Zuschlags.");
264	  }
265	  if (db.ppaPreisCt && db.ppaPreisCt > ERLOESE.ppaCt.max * 1.6) add("warnung", "ppaPreisCt", "kaufmaennisch", `PPA-Preis ${db.ppaPreisCt} ct/kWh deutlich über Marktniveau (${ERLOESE.ppaCt.min}–${ERLOESE.ppaCt.max} ct/kWh) – Struktur (z. B. Baseload) erläutern.`);
266	
267	  // Wirtschaftlichkeit
268	  if (db.capexEurKwp && pv) {
269	    const sp = p?.typ === "agri" ? AGRI.capexProKwp.hoch : p?.typ === "carport" ? CARPORT.capexProKwp : FREIFLAECHE.capexProKwp;
270	    if (db.capexEurKwp < sp.min * 0.75) add("warnung", "capexEurKwp", "kaufmaennisch", `Capex ${db.capexEurKwp} €/kWp unter der Marktspanne (${sp.min}–${sp.max} €/kWp) – Umfang (Netz, Trafo, Zaun) prüfen.`);
271	    else if (db.capexEurKwp > sp.max * 1.35) add("warnung", "capexEurKwp", "kaufmaennisch", `Capex ${db.capexEurKwp} €/kWp über der Marktspanne (${sp.min}–${sp.max} €/kWp).`);
272	  }
273	  if (db.opexEurKwp && pv && (db.opexEurKwp < 4 || db.opexEurKwp > 25)) add("warnung", "opexEurKwp", "kaufmaennisch", `Opex ${db.opexEurKwp} €/kWp·a außerhalb der üblichen Spanne (rund 6–15 €/kWp·a ohne Pacht).`);
274	  if (db.irrPct !== undefined && db.irrPct > 14) add("warnung", "irrPct", "kaufmaennisch", `Angegebene Rendite ${db.irrPct} % ist für PV im DACH-Raum sehr hoch – Basis (Projekt/Eigenkapital, vor/nach Steuern) und Annahmen offenlegen.`);
275	
276	  // Genehmigung: Datumsreihenfolge
277	  const reihe = [["mAufstellung", "Aufstellungsbeschluss"], ["mBeteiligung", "frühzeitige Beteiligung"], ["mOffenlage", "Offenlage"], ["mSatzung", "Satzungsbeschluss"], ["mBaugenehmigung", "Baugenehmigung"]];
278	  let vorher = null;
279	  for (const [id, label] of reihe) {
280	    if (!db[id]) continue;
281	    if (db[id] > heuteIso) add("warnung", id, "genehmigung", `${label} liegt in der Zukunft (${db[id]}) – Meilensteine bitte nur mit erreichtem Datum eintragen.`);
282	    if (vorher && db[id] < vorher[1]) add("fehler", id, "genehmigung", `${label} liegt vor „${vorher[0]}“ – Reihenfolge prüfen.`);
283	    vorher = [label, db[id]];
284	  }
285	  if (phase >= PHASE_IDX("satzung") && db.genehmigungsweg === "bplan" && !db.mSatzung) add("info", "mSatzung", "genehmigung", "Phase „Baurecht“ – Datum des Satzungsbeschlusses ergänzen.");
286	  if (db.genehmigungsweg === "par35" && p?.land === "DE" && p?.typ === "agri" && Number(p?.flaecheHa) > AGRI.privilegierungHa) add("warnung", "genehmigungsweg", "genehmigung", `Privilegierung für Agri-PV nach § 35 Abs. 1 Nr. 9 BauGB nur bis ${AGRI.privilegierungHa} ha Grundfläche mit Hofbezug – bei ${p.flaecheHa} ha ist in der Regel ein B-Plan nötig.`);
287	  if (["umwidmung_at"].includes(db.genehmigungsweg) && p?.land !== "AT") add("fehler", "genehmigungsweg", "genehmigung", "Umwidmung Grünland-PV gilt nur für Österreich.");
288	  if (["bplan", "par35"].includes(db.genehmigungsweg) && p?.land && p.land !== "DE") add("fehler", "genehmigungsweg", "genehmigung", "B-Plan bzw. § 35 BauGB gelten nur für Deutschland.");
289	
290	  // Bestand
291	  if (bestand) {
292	    const reihen = (db.ertraege || []).filter((z) => z.istMwh > 0 && z.prognoseMwh > 0);
293	    if (reihen.length) {
294	      const q = reihen.reduce((s, z) => s + z.istMwh, 0) / reihen.reduce((s, z) => s + z.prognoseMwh, 0);
295	      if (q < 0.92) add("warnung", "ertraege", "ertrag", `Ist-Erträge im Mittel ${Math.round(q * 100)} % der Prognose – Ursachen (Verfügbarkeit, Abregelung, Degradation) erläutern.`);
296	      else if (q > 1.08) add("info", "ertraege", "ertrag", `Ist-Erträge im Mittel ${Math.round(q * 100)} % der Prognose – Prognosebasis prüfen (konservatives Gutachten?).`);
297	    }
298	    if (db.verfuegbarkeitPct !== undefined && db.verfuegbarkeitPct < 97) add("warnung", "verfuegbarkeitPct", "technisch", `Verfügbarkeit ${db.verfuegbarkeitPct} % – üblich sind ≥ 98–99 %. O&M-Leistung und Garantien prüfen.`);
299	    if (db.eegEnde && db.pachtEnde && db.pachtEnde < db.eegEnde) add("warnung", "pachtEnde", "rechtlich", "Pacht endet vor dem Förderende – Verlängerung sichern, sonst fehlen Förderjahre.");
300	    if (db.wrTausch === "offen" && db.codDatum && Number(db.codDatum.slice(0, 4)) <= Number(heuteIso.slice(0, 4)) - 8) add("info", "wrTausch", "technisch", "Anlage älter als acht Jahre, Wechselrichtertausch noch nicht geplant – Rücklage einplanen.");
301	  }
302	  return h;
303	}
