307	/**
308	 * Zuordnung der Checklisten-Punkte (checkliste.js) zu DD-Kategorien – ein vorhandenes Dokument stärkt die Kategorie.
309	 */
310	export const DD_CHECKLISTE = {
311	  rechtlich: ["pacht", "lageplan"],
312	  netz: ["netzzusage"],
313	  genehmigung: ["aufstellung", "satzung", "baugenehmigung"],
314	  ertrag: ["ertrag"],
315	  kaufmaennisch: ["eeg"],
316	  umwelt: ["gutachten"],
317	  technisch: ["betrieb"],
318	  steuern: [],
319	};
320	
321	/** Typische Prüfpunkte einer Kauf-Due-Diligence je Kategorie (Anzeige im Exposé) */
322	export const DD_PRUEFPUNKTE = {
323	  technisch: ["Anlagenkonzept und Komponenten (Bankability der Hersteller)", "DC/AC-Auslegung, Layout, Verschattung", "Bestand: Verfügbarkeit, O&M-Vertrag, Garantien, Wechselrichtertausch"],
324	  rechtlich: ["Pacht-/Nutzungsverträge aller Flurstücke inkl. Laufzeit und Optionen", "Dingliche Sicherung (Dienstbarkeiten, Rang)", "Gesellschaftsrecht, Change-of-Control-Klauseln"],
325	  netz: ["Netzzusage mit Leistung, NVP und Befristung", "Kostenvoranschlag, Baukostenzuschuss", "Einspeisebegrenzung, Überbauung, Redispatch"],
326	  genehmigung: ["B-Plan/Widmung/Baugenehmigung und Bestandskraft", "Auflagen und Fristen", "FNP-Anpassung, Raumordnung"],
327	  ertrag: ["Unabhängiges Ertragsgutachten P50/P90", "Datenbasis und Unsicherheiten", "Bestand: Ist-Erträge vs. Prognose"],
328	  kaufmaennisch: ["Vermarktung (EEG-Zuschlag, PPA, Merchant)", "Capex/Opex-Annahmen, Pacht", "Finanzierbarkeit (DSCR auf P90)"],
329	  steuern: ["Deal-Struktur (Asset/Share), Grunderwerbsteuer", "Umsatzsteuer (Geschäftsveräußerung im Ganzen)", "Gewerbesteuer-Zerlegung, Verlustvorträge"],
330	  umwelt: ["UVP-Pflicht, Umweltbericht", "Artenschutz, CEF- und Ausgleichsmaßnahmen", "Schutzgebiete, Boden, Wasser"],
331	};
332	
333	/**
334	 * Due-Diligence-Index je Kategorie mit Ampel.
335	 * ampel: gruen (erwartete Angaben und Unterlagen vollständig, keine Warnung) · gelb (Lücken oder Warnungen) ·
336	 *        rot (wesentliche Lücken ≥ 50 % oder Widerspruch) · grau (in dieser Phase noch nicht relevant)
337	 * @param p Projekt mit datenblatt/vertraulich
338	 * @param checkliste Ausgabe von checklisteProjekt (optional; nur `punkte` mit id/erwartet/vorhanden)
339	 */
340	export function ddIndex(p, checkliste = null, { jetzt } = {}) {
341	  const pruef = datenblattPruefen(p, { jetzt });
342	  const punkte = checkliste?.punkte || [];
343	  const out = {};
344	  for (const [kat, meta] of Object.entries(SCHEMA.dd)) {
345	    const felder = DATENBLATT_FELDER.filter((f) => f.dd === kat && feldErwartet(p, f));
346	    const fehlend = felder.filter((f) => !gefuellt(feldWert(p, f)));
347	    const doks = punkte.filter((x) => DD_CHECKLISTE[kat].includes(x.id) && x.erwartet && x.pflicht !== false);
348	    const doksFehlend = doks.filter((x) => !x.vorhanden);
349	    const hinweise = pruef.filter((x) => x.dd === kat);
350	    const erwartet = felder.length + doks.length;
351	    const erfuellt = erwartet - fehlend.length - doksFehlend.length;
352	    const quote = erwartet ? Math.round((erfuellt / erwartet) * 100) : null;
353	    let ampel = "grau";
354	    if (erwartet || hinweise.length) {
355	      if (hinweise.some((x) => x.stufe === "fehler") || (quote !== null && quote < 50)) ampel = "rot";
356	      else if (hinweise.some((x) => x.stufe === "warnung") || (quote !== null && quote < 100)) ampel = "gelb";
357	      else ampel = "gruen";
358	    }
359	    out[kat] = {
360	      id: kat,
361	      label: meta.label,
362	      text: meta.text,
363	      ampel,
364	      quote,
365	      fehlend: [...fehlend.map((f) => f.label), ...doksFehlend.map((x) => `Unterlage: ${x.label}`)],
366	      hinweise: hinweise.map((x) => ({ stufe: x.stufe, text: x.text })),
367	      pruefpunkte: DD_PRUEFPUNKTE[kat],
368	    };
369	  }
370	  const liste = Object.values(out);
371	  const relevant = liste.filter((k) => k.ampel !== "grau");
372	  return {
373	    kategorien: liste,
374	    gesamt: relevant.length ? (relevant.some((k) => k.ampel === "rot") ? "rot" : relevant.some((k) => k.ampel === "gelb") ? "gelb" : "gruen") : "grau",
375	    rot: liste.filter((k) => k.ampel === "rot").length,
376	    gelb: liste.filter((k) => k.ampel === "gelb").length,
377	    gruen: liste.filter((k) => k.ampel === "gruen").length,
378	  };
379	}
