381	/** Kennzahlen für die Anzeige (DC/AC, MWp/ha, P90/P50) */
382	export function datenblattKennzahlen(p) {
383	  const db = p?.datenblatt || {};
384	  const mwp = Number(p?.mwp) || 0;
385	  const p50 = Number(p?.vertraulich?.ertragKwhKwp) || null;
386	  return {
387	    dcAc: mwp && db.mwac ? Math.round((mwp / db.mwac) * 100) / 100 : null,
388	    mwpProHa: mwp && Number(p?.flaecheHa) ? Math.round((mwp / p.flaecheHa) * 100) / 100 : null,
389	    p90ZuP50: p50 && db.ertragP90 ? Math.round((db.ertragP90 / p50) * 1000) / 1000 : null,
390	    ertragRichtwert: p?.typ !== "speicher" ? erwarteterErtrag(p) : null,
391	    jahresertragP50Mwh: p50 && mwp ? Math.round(p50 * mwp) : null,
392	    speicherDauerH: db.speicherMw && db.speicherMwh ? Math.round((db.speicherMwh / db.speicherMw) * 10) / 10 : null,
393	  };
394	}
