396	/** Anzeige-Wert eines Felds (für Exposé/Datenraum) */
397	export function feldAnzeige(f, w) {
398	  if (!gefuellt(w)) return "";
399	  if (f.typ === "auswahl") return f.optionen.find(([id]) => id === w)?.[1] || String(w);
400	  if (f.typ === "datum") return `${w.slice(8, 10)}.${w.slice(5, 7)}.${w.slice(0, 4)}`;
401	  if (f.typ === "zahl") return `${Number(w).toLocaleString("de-DE", { maximumFractionDigits: f.stellen ?? 2 })}${f.einheit ? ` ${f.einheit}` : ""}`;
402	  if (f.typ === "tabelle") return w.map((z) => `${z.jahr}: ${z.istMwh ?? "–"} / ${z.prognoseMwh ?? "–"} MWh`).join(" · ");
403	  return String(w);
404	}

