  3	// Anschreiben-Vorlage (Serienbrief) an Grundeigentümer einer Kandidatenfläche – reine Funktion.
  4	// Rechtlicher Rahmen (keine Rechtsberatung, vor Einsatz von der Datenschutzberatung freigeben lassen):
  5	//  - Nur BRIEF (Post). Telefon, E-Mail, SMS zu Werbezwecken nur mit vorheriger Einwilligung (§ 174 TKG 2021).
  6	//  - Einmalige postalische Kontaktaufnahme auf Basis öffentlich einsehbarer Grundbuchdaten kann nach Art. 6 Abs. 1
  7	//    lit. f DSGVO zulässig sein (DSB, GZ DSB-D123.626/0006-DSB/2018) – Voraussetzungen: Information nach Art. 14,
  8	//    Widerspruchsmöglichkeit, keine wiederholten Zusendungen, Liegenschaftsdaten nicht von außen sichtbar.
  9	//  - Datenquelle offenlegen (Art. 14 Abs. 2 lit. f DSGVO): Grundbuch (Auszug über Verrechnungsstelle).
 10	// Platzhalter in «…» werden beim Serienbrief aus dem CRM-Kontakt befüllt (Name, Anschrift), nie aus dem Geodaten-Dienst.
 11	
 12	import { GESELLSCHAFT, SITE, abs } from "@/data/site";
 13	import { briefFuer } from "./serienbrief";
 14	
 15	const ha = (x) => `${(Math.round(Number(x) * 10) / 10).toLocaleString("de-DE")} ha`;
 16	
 17	export const DSGVO_HINWEIS =
 18	  "Direktwerbung an Eigentümer nur per Brief und nur einmalig ohne Reaktion; Telefon/E-Mail erst nach Einwilligung (§ 174 TKG 2021). Datenquelle (Grundbuch) und Widerspruchsrecht im Brief nennen (Art. 14, Art. 21 DSGVO). Widersprüche sofort im CRM als Sperrvermerk erfassen. Die Vorlage vor dem ersten Einsatz von der Datenschutzberatung freigeben lassen.";
 19	
 20	export const DSGVO_HINWEIS_DE_CH =
 21	  "Direktwerbung an Eigentümer nur per Brief (Art. 6 Abs. 1 lit. f DSGVO, § 7 UWG); Telefon und E-Mail nur mit vorheriger ausdrücklicher Einwilligung (§ 7 Abs. 2 UWG). Datenquelle (Grundbuch – DE: § 12 GBO/§ 43a GBV, CH: Art. 970 ZGB) und Widerspruchsrecht im Brief nennen. Für Serienbriefe mit persönlichem Link, Sperrliste und Nachfassen: Akquise-Kampagnen.";
 22	
 23	/** Liefert { betreff, text, hinweis } für einen Kandidaten (Objekt aus dem Geodaten-Adapter) */
 24	export function anschreiben(k, { datum = new Date() } = {}) {
 25	  if (k.land && k.land !== "AT") {
 26	    // Deutschland/Schweiz (A1b): gleicher Brief wie der Serienbrief der Kampagnen, Platzhalter statt Eigentümerdaten
 27	    const b = briefFuer({ id: "Vorlage", name: "Anschreiben", land: k.land }, { ...k, id: k.id }, { anrede: "", vorname: "«Vorname»", nachname: "«Nachname»", strasse: "«Straße Hausnummer»", plz: "«PLZ»", ort: "«Ort»", code: "XXXXXXXXXX" }, { basisUrl: SITE.url, datum });
 28	    const text = [b.absenderZeile, "", ...b.anschrift, "", b.datum, "", b.betreff, "", b.text, "", b.keinInteresse, "", "Persönlicher Link (Einmalcode je Empfänger, nur in Kampagnen): " + b.link, "", ...b.gruss, "", b.widerspruch, "", "— Datenschutzinformation —", ...b.datenschutz].join("\n");
 29	    return { betreff: b.betreff, text, hinweis: DSGVO_HINWEIS_DE_CH, absender: SITE.firma };
 30	  }
 31	  const grundstuecke = (k.parzellen || []).map((p) => `KG ${p.kgNr || "«KG»"}, Gst.-Nr. ${p.gstNr || "«Gst.-Nr.»"}`);
 32	  const liste = grundstuecke.length > 4 ? `${grundstuecke.slice(0, 4).join("; ")} und ${grundstuecke.length - 4} weitere` : grundstuecke.join("; ");
 33	  const d = datum.toLocaleDateString("de-AT", { day: "2-digit", month: "long", year: "numeric", timeZone: "Europe/Vienna" });
 34	  const betreff = `Ihre Fläche in ${k.gemeinde || "«Gemeinde»"} – Anfrage zur Verpachtung für eine Photovoltaik-Anlage`;
 35	  const text = [
 36	    `${GESELLSCHAFT.name} · ${GESELLSCHAFT.sitz} · ${GESELLSCHAFT.plz} ${GESELLSCHAFT.ort}`,
 37	    "",
 38	    "«Anrede» «Vorname» «Nachname»",
 39	    "«Straße Hausnummer»",
 40	    "«PLZ» «Ort»",
 41	    "",
 42	    `${GESELLSCHAFT.ort}, ${d}`,
 43	    "",
 44	    betreff,
 45	    "",
 46	    "«Briefanrede»,",
 47	    "",
 48	    `wir sind die ${GESELLSCHAFT.name} aus ${GESELLSCHAFT.ort} und entwickeln Freiflächen- und Agri-Photovoltaikanlagen in Österreich. Bei unserer Standortsuche sind wir auf Grundstücke in Ihrem Eigentum gestoßen (${liste}), die zusammen mit angrenzenden Flächen rund ${ha(k.ha)} umfassen.`,
 49	    "",
 50	    "Ob sich eine Fläche tatsächlich eignet, hängt von Widmung, Netzanschluss und Naturschutz ab – das prüfen wir für Sie kostenfrei und unverbindlich. Möglich sind eine langfristige Verpachtung (in der Regel 25 bis 30 Jahre, wertgesichert) oder Agri-PV, bei der die landwirtschaftliche Nutzung weiterläuft.",
 51	    "",
 52	    `Wenn Sie Interesse an einem Gespräch haben, antworten Sie uns bitte formlos per Brief oder über ${abs("/flaeche-verpachten")}. Haben Sie kein Interesse, müssen Sie nichts tun – wir schreiben Sie zu dieser Fläche nicht erneut an.`,
 53	    "",
 54	    "Mit freundlichen Grüßen",
 55	    "",
 56	    "«Name Ansprechperson»",
 57	    GESELLSCHAFT.name,
 58	    "",
 59	    "— Datenschutzinformation (Art. 13/14 DSGVO) —",
 60	    `Verantwortlich: ${GESELLSCHAFT.name}, ${GESELLSCHAFT.sitz}, ${GESELLSCHAFT.plz} ${GESELLSCHAFT.ort}, ${GESELLSCHAFT.register}.`,
 61	    "Zweck: einmalige Kontaktaufnahme zur möglichen Verpachtung Ihrer Fläche für eine Photovoltaik-Anlage.",
 62	    "Rechtsgrundlage: berechtigtes Interesse (Art. 6 Abs. 1 lit. f DSGVO) an der Suche geeigneter Flächen für erneuerbare Energie.",
 63	    "Datenquelle: Ihr Name und Ihre Anschrift stammen aus dem öffentlichen Grundbuch (Grundbuchauszug über eine Verrechnungsstelle); Lage und Größe der Grundstücke aus dem Kataster (BEV) und öffentlichen Geodaten.",
 64	    "Speicherdauer: bis zum Abschluss der Anfrage, höchstens 12 Monate ohne Rückmeldung; bei Widerspruch nur ein Sperrvermerk, damit wir Sie nicht erneut anschreiben.",
 65	    "Ihre Rechte: Auskunft, Berichtigung, Löschung, Einschränkung und insbesondere WIDERSPRUCH gegen diese Verarbeitung (Art. 21 DSGVO) – formlos an die obige Anschrift. Beschwerden sind bei der Österreichischen Datenschutzbehörde (www.dsb.gv.at) möglich.",
 66	    `Weitere Informationen: ${abs("/datenschutz")}`,
 67	  ].join("\n");
 68	  return { betreff, text, hinweis: DSGVO_HINWEIS, absender: SITE.firma };
 69	}
 70	// src/lib/plattform/geodaten/serienbrief.js
 71	//
 72	// Serienbrief der Akquise-Kampagnen (reine Funktionen, Client + Server): Brief je Empfänger mit persönlicher Ansprache,
 73	// Flächendaten, unverbindlicher Pachtspanne, Link/QR-Code zur personalisierten Angebotsseite /angebot/[code],
 74	// Datenschutzinformation (Art. 13/14 DSGVO bzw. Art. 19 DSG) und hervorgehobenem Widerspruchshinweis (Art. 21 DSGVO).
 75	//
 76	// Der Brieftext (Betreff + Hauptteil) läuft über die vorhandene Vorlagen-Engine (src/lib/plattform/vorlagen.js → rendern):
 77	// Standardtext unten oder eine Vorlage aus dem Backoffice (Bereich „Vorlagen“). Pflichtblöcke (Absender, Anschrift,
 78	// Link/QR, Datenschutz, Widerspruch) sind fest und nicht über Vorlagen änderbar.
 79	// Anschriftfeld nach DIN 5008 (Form B) – im Fenster erscheinen nur Name und Anschrift, keine Grundstücksangaben.
 80	// Telefon/E-Mail der ÖkoInvest sind nicht freigegeben und werden NICHT eingesetzt.
 81	
 82	import { GESELLSCHAFT } from "@/data/site";
 83	import { rendern } from "../vorlagen";
 84	import { codeLesbar, pachtspanne } from "../akquise-kampagne";
 85	
 86	const zahl = (x, st = 0) => (Number(x) || 0).toLocaleString("de-DE", { minimumFractionDigits: st, maximumFractionDigits: st });
 87	
 88	export const STANDARD_VORLAGE = {
 89	  version: 1,
 90	  betreff: "Ihre Fläche in {{flaeche.gemeinde}} – Anfrage zur Verpachtung für eine Photovoltaik-Anlage",
 91	  text: [
 92	    "{{briefanrede}},",
 93	    "",
 94	    "wir sind die ÖkoInvest GmbH, ein Unternehmen der ÖKOVOLT Gruppe, und entwickeln Freiflächen- und Agri-Photovoltaikanlagen. Bei unserer Standortsuche sind wir auf Grundstücke in Ihrem Eigentum in {{flaeche.gemeinde}} gestoßen ({{flaeche.flurstuecke}}). Zusammen mit angrenzenden Flächen umfasst der Bereich rund {{flaeche.ha}} ha – genug für eine Anlage mit etwa {{flaeche.mwp}} MWp.",
 95	    "",
 96	    "Nach unserer ersten Einschätzung kommt die Fläche grundsätzlich für einen Solarpark in Frage. Für vergleichbare Flächen zahlen wir in der Regel eine Pacht zwischen {{flaeche.pachtMin}} und {{flaeche.pachtMax}} € je Hektar und Jahr, über 25 bis 30 Jahre und wertgesichert. Die Spanne ist unverbindlich; maßgeblich sind Netzanschluss, Baurecht und Naturschutz, die wir für Sie kostenfrei prüfen. Möglich ist auch Agri-PV, bei der die landwirtschaftliche Nutzung weiterläuft.",
 97	    "",
 98	    "Unter dem Link bzw. QR-Code unten finden Sie einen persönlichen Steckbrief Ihrer Fläche und können die Pacht selbst durchrechnen. Wenn Sie Interesse an einem unverbindlichen Gespräch haben, antworten Sie uns dort oder formlos per Brief.",
 99	  ].join("\n"),
100	};
101	
102	/** Datenquelle der Eigentümerdaten je Land (Art. 14 Abs. 2 lit. f DSGVO) */
103	export const DATENQUELLE = {
104	  DE: "Ihr Name und Ihre Anschrift stammen aus dem Grundbuch (Einsicht beim Grundbuchamt nach § 12 GBO; für Vorhaben der erneuerbaren Energien § 43a GBV). Lage und Größe der Flurstücke stammen aus dem Liegenschaftskataster (ALKIS, Open Data der Länder) und öffentlichen Geodaten.",
105	  AT: "Ihr Name und Ihre Anschrift stammen aus dem öffentlichen Grundbuch (Grundbuchauszug über eine Verrechnungsstelle). Lage und Größe der Grundstücke stammen aus dem Kataster (BEV) und öffentlichen Geodaten.",
106	  CH: "Ihr Name und Ihre Anschrift stammen aus der Eigentümerauskunft des Grundbuchs (Art. 970 Abs. 2 ZGB). Lage und Größe der Parzellen stammen aus der amtlichen Vermessung (geodienste.ch) und öffentlichen Geodaten.",
107	};
108	
109	export const BESCHWERDE = {
110	  DE: "Sie können sich bei einer Datenschutz-Aufsichtsbehörde beschweren, insbesondere in dem Mitgliedstaat Ihres Aufenthaltsorts (z. B. beim Landesamt bzw. Landesbeauftragten für den Datenschutz Ihres Bundeslandes), oder bei der für uns zuständigen Österreichischen Datenschutzbehörde (www.dsb.gv.at).",
111	  AT: "Sie können sich bei der Österreichischen Datenschutzbehörde (www.dsb.gv.at) beschweren.",
112	  CH: "Sie können sich an den Eidgenössischen Datenschutz- und Öffentlichkeitsbeauftragten (EDÖB) oder an die Österreichische Datenschutzbehörde (www.dsb.gv.at) wenden.",
113	};
114	
115	/** Satz zum Umgang bei fehlendem Interesse – Österreich: einmalige Zusendung */
116	export const KEIN_INTERESSE = {
117	  DE: "Haben Sie kein Interesse, müssen Sie nichts tun. Möchten Sie keine weiteren Schreiben von uns erhalten, genügt ein kurzer Widerspruch – dann schreiben wir Sie nie wieder an.",
118	  AT: "Haben Sie kein Interesse, müssen Sie nichts tun – wir schreiben Sie zu dieser Fläche nicht erneut an.",
119	  CH: "Haben Sie kein Interesse, müssen Sie nichts tun. Möchten Sie keine weiteren Schreiben von uns erhalten, genügt ein kurzer Widerspruch – dann schreiben wir Sie nie wieder an.",
120	};
121	
122	function briefanrede(e) {
123	  const a = String(e.anrede || "").toLowerCase();
124	  if (a === "frau" && e.nachname) return `Sehr geehrte Frau ${[e.titel, e.nachname].filter(Boolean).join(" ")}`;
125	  if (a === "herr" && e.nachname) return `Sehr geehrter Herr ${[e.titel, e.nachname].filter(Boolean).join(" ")}`;
126	  if (e.firma && !e.nachname) return "Sehr geehrte Damen und Herren";
127	  return `Guten Tag ${[e.vorname, e.nachname].filter(Boolean).join(" ")}`.trim();
128	}
129	
130	/** Flurstücke eines Empfängers als Text (höchstens 4 genannt) */
131	export function flurstueckText(ziel, empfaenger) {
132	  const alle = ziel.parzellen || [];
133	  const eigene = empfaenger?.flurstuecke?.length ? alle.filter((p) => empfaenger.flurstuecke.includes(p.id)) : alle;
134	  const land = ziel.land || "DE";
135	  // nach Gemarkung/KG gruppiert: „Gemarkung X, Flst. 12, 13/1 und 2 weitere“
136	  const gruppen = new Map();
137	  for (const p of eigene) {
138	    const gem = String(p.kg || "").replace(/^DEMO-(KG|Gemarkung)\s*/, "") || p.kgNr;
139	    if (!gruppen.has(gem)) gruppen.set(gem, []);
140	    gruppen.get(gem).push(p.gstNr);
141	  }
142	  const teile = [...gruppen.entries()].map(([gem, nr]) => {
143	    const liste = nr.length > 4 ? `${nr.slice(0, 4).join(", ")} und ${nr.length - 4} weitere` : nr.join(", ");
144	    if (land === "AT") return `KG ${gem}, Gst.-Nr. ${liste}`;
145	    if (land === "CH") return `${gem}, Parzelle ${liste}`;
146	    return `Gemarkung ${gem}, Flst. ${liste}`;
147	  });
148	  return teile.join("; ");
149	}
150	
151	/**
152	 * Brief für einen Empfänger. Liefert strukturierte Blöcke für PDF, Vorschau und Druckformat.
153	 * opt: { basisUrl, datum, vorlage: { betreff, text } (Standard: STANDARD_VORLAGE), zustaendig: { name } }
154	 */
155	export function briefFuer(kampagne, ziel, empfaenger, { basisUrl = "https://www.oekoinvest.com", datum = new Date(), vorlage = STANDARD_VORLAGE, zustaendig = null } = {}) {
156	  const land = ziel.land || kampagne.land || "DE";
157	  const sp = pachtspanne(ziel.ha, ziel.ampel);
158	  const link = `${String(basisUrl).replace(/\/$/, "")}/angebot/${empfaenger.code}`;
159	  const kontext = {
160	    anrede: empfaenger.anrede || "",
161	    briefanrede: briefanrede(empfaenger),
162	    vorname: empfaenger.vorname || "",
163	    nachname: empfaenger.nachname || "",
164	    firma: empfaenger.firma || "",
165	    ort: empfaenger.ort || "",
166	    kampagne: { name: kampagne.name },
167	    flaeche: {
168	      bezeichnung: `${ziel.gemeinde} · ${zahl(ziel.ha, 1)} ha`,
169	      gemeinde: ziel.gemeinde || "",
170	      ha: zahl(ziel.ha, 1),
171	      mwp: zahl(ziel.mwp, 1),
172	      ort: ziel.gemeinde || "",
173	      bundesland: ziel.bundesland || "",
174	      flurstuecke: flurstueckText(ziel, empfaenger),
175	      pachtMin: zahl(sp.proHaMin),
176	      pachtMax: zahl(sp.proHaMax),
177	    },
178	    angebot: { link, code: codeLesbar(empfaenger.code) },
179	    zustaendig: { name: zustaendig?.name || "Ihr ÖkoInvest-Team", vorname: zustaendig?.vorname || "" },
180	    heute: datum.toLocaleDateString("de-DE", { timeZone: "Europe/Vienna", day: "2-digit", month: "2-digit", year: "numeric" }),
181	  };
182	  const b = rendern(vorlage.betreff || STANDARD_VORLAGE.betreff, kontext);
183	  const t = rendern(vorlage.text || STANDARD_VORLAGE.text, kontext);
184	  const anschrift = [
185	    [empfaenger.firma, !empfaenger.firma || empfaenger.nachname ? [empfaenger.anrede, empfaenger.titel, empfaenger.vorname, empfaenger.nachname].filter(Boolean).join(" ") : ""].filter(Boolean).join("\n"),
186	    empfaenger.zusatz,
187	    empfaenger.strasse,
188	    [empfaenger.plz, empfaenger.ort].filter(Boolean).join(" "),
189	    empfaenger.land && empfaenger.land !== land ? { DE: "DEUTSCHLAND", AT: "ÖSTERREICH", CH: "SCHWEIZ" }[empfaenger.land] || "" : "",
190	  ]
191	    .join("\n")
192	    .split("\n")
193	    .filter(Boolean);
194	  const G = GESELLSCHAFT;
195	  return {
196	    land,
197	    absenderZeile: `${G.name} · ${G.sitz} · ${G.plz} ${G.ort} · ${G.land}`,
198	    anschrift,
199	    datum: `${G.ort}, ${datum.toLocaleDateString("de-DE", { timeZone: "Europe/Vienna", day: "2-digit", month: "long", year: "numeric" })}`,
200	    zeichen: `${kampagne.id} · ${ziel.id}`,
201	    betreff: b.text,
202	    text: t.text,
203	    keinInteresse: KEIN_INTERESSE[land] || KEIN_INTERESSE.DE,
204	    gruss: ["Mit freundlichen Grüßen", "", kontext.zustaendig.name, G.name],
205	    link,
206	    code: codeLesbar(empfaenger.code),
207	    codeRoh: empfaenger.code,
208	    flaechenDaten: [
209	      ["Gemeinde", ziel.gemeinde],
210	      ["Flurstücke", `${(empfaenger?.flurstuecke?.length || (ziel.parzellen || []).length)} in ${[...new Set((ziel.parzellen || []).map((p) => String(p.kg || "").replace(/^DEMO-(KG|Gemarkung)\s*/, "")))].slice(0, 2).join(", ")}`],
211	      ["Fläche (Bereich)", `rund ${kontext.flaeche.ha} ha`],
212	      ["Mögliche Leistung", `etwa ${kontext.flaeche.mwp} MWp`],
213	      ["Pacht (unverbindlich)", `${kontext.flaeche.pachtMin}–${kontext.flaeche.pachtMax} € je ha und Jahr`],
214	    ],
215	    widerspruch: `WIDERSPRUCHSRECHT: Sie können der Verwendung Ihrer Daten für diese Kontaktaufnahme jederzeit ohne Angabe von Gründen widersprechen (Art. 21 Abs. 2 DSGVO) – formlos per Brief an die obige Anschrift oder online über den Link bzw. QR-Code („Nicht mehr anschreiben“). Wir vermerken Ihren Widerspruch dann dauerhaft in unserer Sperrliste und schreiben Sie nicht mehr an.`,
216	    datenschutz: [
217	      `Verantwortlich: ${G.name}, ${G.sitz}, ${G.plz} ${G.ort}, ${G.land}, ${G.register} (${G.gericht}).`,
218	      "Zweck: Kontaktaufnahme zur möglichen Verpachtung Ihrer Fläche für eine Photovoltaik-Anlage.",
219	      `Rechtsgrundlage: berechtigtes Interesse (Art. 6 Abs. 1 lit. f DSGVO) an der Suche geeigneter Flächen für erneuerbare Energien; Direktwerbung per Brief (Erwägungsgrund 47 DSGVO)${land === "CH" ? "; für die Schweiz zusätzlich Art. 31 DSG (überwiegendes Interesse)" : ""}.`,
220	      "Kategorien: Name, Anschrift, Bezeichnung und Größe Ihrer Grundstücke, Eigentumsverhältnis.",
221	      `Datenquelle: ${DATENQUELLE[land] || DATENQUELLE.DE}`,
222	      "Empfänger: gegebenenfalls Druck- und Versanddienstleister als Auftragsverarbeiter; keine Weitergabe an Dritte zu deren Werbezwecken.",
223	      "Speicherdauer: bis zum Abschluss der Anfrage, höchstens 12 Monate ohne Rückmeldung. Nach einem Widerspruch speichern wir nur einen Sperrvermerk (verschlüsselter Abgleichswert), damit wir Sie nicht erneut anschreiben.",
224	      `Ihre Rechte: Auskunft, Berichtigung, Löschung, Einschränkung der Verarbeitung, Datenübertragbarkeit und Widerspruch. ${BESCHWERDE[land] || BESCHWERDE.DE}`,
225	      `Weitere Informationen: ${String(basisUrl).replace(/\/$/, "")}/datenschutz`,
226	    ],
227	    unbekanntePlatzhalter: [...new Set([...b.unbekannt, ...t.unbekannt])],
228	    leerePlatzhalter: [...new Set([...b.leer, ...t.leer])],
229	  };
230	}

