import { geojsonPrimitive } from "./geo.mjs";
import { kennzahlen } from "./dxf.mjs";
// 100 m x 100 m square at lat 48 with 50x50 m hole, layer Baugrenze
const dLat = 100/111190, dLon = 100/(111320*Math.cos(48*Math.PI/180));
const o=[[13,48],[13+dLon,48],[13+dLon,48+dLat],[13,48+dLat],[13,48]];
const h=[[13+dLon/4,48+dLat/4],[13+dLon*3/4,48+dLat/4],[13+dLon*3/4,48+dLat*3/4],[13+dLon/4,48+dLat*3/4],[13+dLon/4,48+dLat/4]];
const gj={type:"FeatureCollection",features:[{type:"Feature",properties:{layer:"Baugrenze"},geometry:{type:"Polygon",coordinates:[o,h]}}]};
const {prims,einheit}=geojsonPrimitive(gj);
console.log(kennzahlen(prims,einheit).anlageM2, "erwartet 7500 (10000-2500)");
const gj2={type:"FeatureCollection",features:[{type:"Feature",properties:{layer:"Baugrenze"},geometry:{type:"Polygon",coordinates:[o]}}]};
const r2=geojsonPrimitive(gj2); console.log(kennzahlen(r2.prims,r2.einheit).anlageM2, "erwartet ~10000 (true meridian deg 111190 m @48°)");
// empty point in KML
EOF
node t.mjs

